def _png_rgba(data):
    """(width, height, rows of RGBA bytes) from one of the icon PNGs above (8-bit RGBA, not interlaced)."""
    import struct
    import zlib
    assert data[:8] == b"\x89PNG\r\n\x1a\n"
    pos, idat, w = 8, b"", 0
    while pos < len(data):
        n, kind = struct.unpack(">I4s", data[pos:pos + 8])
        body = data[pos + 8:pos + 8 + n]
        if kind == b"IHDR":
            w, h, depth, ctype, _, _, lace = struct.unpack(">IIBBBBB", body)
            if (depth, ctype, lace) != (8, 6, 0):
                raise ValueError("unexpected PNG format")
        elif kind == b"IDAT":
            idat += body
        pos += 12 + n
    raw, bpp, stride = zlib.decompress(idat), 4, w * 4
    rows, prev = [], bytearray(stride)
    for y in range(h):
        f = raw[y * (stride + 1)]
        line = bytearray(raw[y * (stride + 1) + 1:(y + 1) * (stride + 1)])
        for i in range(stride):
            a = line[i - bpp] if i >= bpp else 0
            b, c = prev[i], (prev[i - bpp] if i >= bpp else 0)
            if f == 1:
                line[i] = (line[i] + a) & 255
            elif f == 2:
                line[i] = (line[i] + b) & 255
            elif f == 3:
                line[i] = (line[i] + ((a + b) >> 1)) & 255
            elif f == 4:
                pa, pb, pc = abs(b - c), abs(a - c), abs(a + b - 2 * c)
                line[i] = (line[i] + (a if pa <= pb and pa <= pc else b if pb <= pc else c)) & 255
        rows.append(bytes(line))
        prev = line
    return w, h, rows


def app_icon_ico():
    """The icon as a Windows .ico file's bytes (plain bitmaps up to 64 px, PNG at 256 — what Explorer expects)."""
    import base64
    import struct
    images = []
    for size in sorted(APP_ICON_PNG):
        png = base64.b64decode("".join(APP_ICON_PNG[size]))
        if size >= 256:
            images.append((size, png))
            continue
        w, h, rows = _png_rgba(png)
        xor = b"".join(bytes(v for i in range(0, len(r), 4) for v in (r[i + 2], r[i + 1], r[i], r[i + 3]))
                       for r in reversed(rows))                       # bottom-up BGRA
        mask = bytes(((w + 31) // 32) * 4) * h                        # (transparency comes from the alpha channel)
        images.append((size, struct.pack("<IiiHHIIiiII", 40, w, h * 2, 1, 32, 0, len(xor) + len(mask), 0, 0, 0, 0)
                       + xor + mask))
    out, offset = struct.pack("<HHH", 0, 1, len(images)), 6 + 16 * len(images)
    for size, blob in images:
        out += struct.pack("<BBBBHHII", size % 256, size % 256, 0, 0, 1, 32, len(blob), offset)
        offset += len(blob)
    return out + b"".join(blob for _, blob in images)


def app_icon_file():
    """Path of the icon file on this computer (written once; "" if it can't be)."""
    path = os.path.join(LOCAL_DIR, "session-scribe.ico")
    try:
        data = app_icon_ico()
        try:
            with open(path, "rb") as f:
                same = f.read() == data
        except OSError:
            same = False
        if not same:                                  # first time, or the icon changed in a new version
            os.makedirs(LOCAL_DIR, exist_ok=True)
            with open(path, "wb") as f:
                f.write(data)
        return path
    except Exception:
        return ""


def shortcut_icon_fix():
    """Give a desktop shortcut made by an older version the app's icon (Windows; once, quietly)."""
    if not IS_WIN or not shortcut_exists():
        return False
    ico = app_icon_file()
    if not ico:
        return False
    ps = ("$w=New-Object -ComObject WScript.Shell;"
          "foreach($d in @([Environment]::GetFolderPath('Desktop'),(Join-Path $env:PUBLIC 'Desktop'))){"
          "$p=Join-Path $d 'Session Scribe.lnk';if(Test-Path $p){$s=$w.CreateShortcut($p);"
          f"$s.IconLocation='{ico},0';$s.Save()}}}}")
    subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps], capture_output=True,
                   timeout=30, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    return True


def shortcut_exists():
    """Is there already a Session Scribe shortcut/app on this computer?"""
    with _PROBE_LOCK:
        if "shortcut" in _SETUP_PROBES:
            return _SETUP_PROBES["shortcut"]
    home = os.path.expanduser("~")
    if IS_MAC:
        res = os.path.isdir(os.path.join(home, "Applications", "Session Scribe.app"))
    elif IS_WIN:
        res = any(
            os.path.isfile(os.path.join(desk, "Session Scribe.lnk"))
            for desk in (os.path.join(home, "Desktop"), os.path.join(home, "OneDrive", "Desktop"),
                         os.path.join(os.environ.get("PUBLIC", ""), "Desktop"))
        )
    else:
        res = os.path.isfile(os.path.join(APP_DIR, "session_scribe.sh"))
    with _PROBE_LOCK:
        _SETUP_PROBES["shortcut"] = res
    return res


def desktop_shortcut(launcher, log=lambda t: None):
    """Put a 'Session Scribe' shortcut on the desktop (Windows: .lnk; Mac: link to the app)."""
    if IS_MAC:
        app = os.path.join(os.path.expanduser("~"), "Applications", "Session Scribe.app")
        link = os.path.join(os.path.expanduser("~"), "Desktop", "Session Scribe.app")
        try:
            if not os.path.isdir(app):
                write_mac_app(os.path.join(os.path.dirname(launcher), os.path.basename(os.path.abspath(__file__))),
                              _gui_python(load_config().get("python_path") or sys.executable))
            if os.path.islink(link) or os.path.exists(link):
                os.remove(link)
            os.symlink(app, link)
            return link
        except OSError as e:
            log(f"Couldn't make the desktop shortcut ({e}).")
            return ""
    if os.name != "nt":
        return ""
    ps = ("$d=[Environment]::GetFolderPath('Desktop');"
          "$s=(New-Object -ComObject WScript.Shell).CreateShortcut((Join-Path $d 'Session Scribe.lnk'));"
          f"$s.TargetPath='{launcher}';$s.WorkingDirectory='{os.path.dirname(launcher)}';"
          + (f"$s.IconLocation='{app_icon_file()},0';" if app_icon_file() else "") +
          "$s.WindowStyle=7;$s.Save();Write-Output (Join-Path $d 'Session Scribe.lnk')")
    try:
        out = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
                             capture_output=True, text=True, timeout=30,
                             creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        return out.stdout.strip()
    except Exception as e:
        log(f"Couldn't make the desktop shortcut ({e}).")
        return ""


def move_program(cfg, dst, shortcut=True, log=lambda t: None, data_target=None):
    """Copy the program (script, FFmpeg in bin/, launcher) to `dst`. If the patient data also
    lives in the old program folder it is moved too (checked, old copy kept as a dated backup).
    Old program files are removed only after the new copy is verified. Returns a summary dict."""
    src = APP_DIR
    dst = os.path.normpath(os.path.abspath(dst))
    if os.path.normcase(dst) == os.path.normcase(src):
        raise RuntimeError("That's already where the program is.")
    if _inside(dst, src):
        raise RuntimeError("Choose a folder outside the current program folder.")
    if is_cloud_path(dst):
        raise RuntimeError("Keep the program itself on this computer (not in Google Drive) — only the "
                           "shared data folder should be in Drive.")
    os.makedirs(dst, exist_ok=True)
    script = os.path.basename(os.path.abspath(__file__))
    new_script = os.path.join(dst, script)
    log("Copying the program…")
    shutil.copy2(os.path.abspath(__file__), new_script)
    if os.path.isdir(BIN_DIR):
        log("Copying FFmpeg…")
        shutil.copytree(BIN_DIR, os.path.join(dst, "bin"), dirs_exist_ok=True)
    with open(os.path.abspath(__file__), "rb") as a, open(new_script, "rb") as b:
        if a.read() != b.read():
            raise RuntimeError("The copied program didn't match the original. Nothing was removed.")
    result = {"dir": dst, "script": new_script, "data_moved": "", "backup": "", "shortcut": "", "left": []}

    # Patient data that lives inside the old program folder moves with it
    droot = data_root(cfg)
    if _inside(droot, src) and folder_has_vault(droot):
        rel = os.path.relpath(droot, src)
        new_root = os.path.normpath(data_target) if data_target else os.path.join(dst, "data" if rel == "." else rel)
        if folder_has_vault(new_root):
            # The Google Drive folder already has the shared files (e.g. from the other computer):
            # use those, and set the local copy aside as a backup instead of mixing the two.
            log("Google Drive already has Session Scribe files — using those.")
            backup = os.path.join(droot, f"vault-backup-{date.today().isoformat()}")
            i = 2
            while os.path.exists(backup):
                backup = os.path.join(droot, f"vault-backup-{date.today().isoformat()}-{i}")
                i += 1
            os.rename(os.path.join(droot, "vault"), backup)
            result["backup"] = backup
            result["joined_existing"] = True
        else:
            log("Moving patient data (encrypted)…")
            result["backup"] = move_data(droot, new_root, log)
        result["data_moved"] = new_root
        for name in ("templates", SHARED_SETTINGS):          # copied and checked; not patient data
            p = os.path.join(droot, name)
            try:
                shutil.rmtree(p) if os.path.isdir(p) else (os.path.isfile(p) and os.remove(p))
            except OSError:
                pass
        cfg["data_dir"] = new_root
        cfg["vault_dir"] = ""
        cfg["_vault_derived"] = True
        set_data_paths(cfg)
        save_config(cfg)
    elif _inside(droot, src):          # empty/new data folder inside the program folder: just repoint
        cfg["data_dir"] = os.path.join(dst, "data")
        cfg["vault_dir"] = ""
        cfg["_vault_derived"] = True
        set_data_paths(cfg)
        save_config(cfg)

    # The data folder link (e.g. H:\My Drive\Session Scribe) lives in this computer's own settings
    # (%LOCALAPPDATA%), not in the program folder, so it carries over untouched. Confirm it.
    after = load_config()
    if os.path.normcase(after.get("data_dir") or "") != os.path.normcase(cfg.get("data_dir") or ""):
        raise RuntimeError("The data folder setting didn't carry over — the old program was left in place.")
    result["data_dir"] = cfg.get("data_dir", "")
    result["data_synced"] = is_cloud_path(result["data_dir"])
    result["data_reachable"] = folder_has_vault(result["data_dir"]) if result["data_dir"] else False

    runner = _gui_python(cfg.get("python_path") or sys.executable)
    launcher = write_launcher(dst, runner)
    result["launcher"] = launcher
    if shortcut:
        result["shortcut"] = desktop_shortcut(launcher, log)

    # Remove the old program files (never patient data — that's kept as a backup above)
    for name in (script, "Session Scribe.bat", "Session Scribe.command", "session_scribe.sh", "bin", "__pycache__"):
        p = os.path.join(src, name)
        try:
            if os.path.isdir(p):
                shutil.rmtree(p)
            elif os.path.isfile(p):
                os.remove(p)
        except OSError:
            result["left"].append(p)
    if os.path.isfile(LEGACY_CONFIG_PATH):
        try:
            os.remove(LEGACY_CONFIG_PATH)       # already copied to this computer's settings
        except OSError:
            pass
    for name in os.listdir(src) if os.path.isdir(src) else []:
        if name.startswith("vault-backup-") or name in ("vault", "templates", "data"):
            result["left"].append(os.path.join(src, name))
    log("Done.")
    return result


def create_launcher(py, ver, has_whisperx, log):
    """Prepare a compatible Python and write a double-click launcher that uses it."""
    v = f"{ver[0]}.{ver[1]}"
    log(f"Preparing Python {v}: {py}")
    pkgs = ["cryptography"] + ([] if has_whisperx else ["whisperx"])
    if not has_whisperx:
        log("WhisperX isn't in that Python yet — installing it too (large download, can take 10+ minutes)…")
    if run_streamed([py, "-m", "pip", "install", "--upgrade"] + pkgs, log):
        raise RuntimeError(f"pip couldn't install {', '.join(pkgs)} into Python {v} — see the log above.")
    runner = _gui_python(py)
    cfg = load_config()
    cfg["python_path"] = py
    save_config(cfg)
    path = write_launcher(APP_DIR, runner)
    return {"launcher": path, "runner": runner, "version": v}


def install_engine(log):
    if not python_supported():
        raise RuntimeError(f"WhisperX doesn't support Python {sys.version_info[0]}.{sys.version_info[1]} "
                           "(it needs 3.10–3.13). Use the \"Use Python 3.x\" button instead.")
    log(f"Installing WhisperX into: {sys.executable}")
    log("This downloads ~2-3 GB (PyTorch and friends) and can take 10+ minutes…")
    code = run_streamed([sys.executable, "-m", "pip", "install", "--upgrade", "whisperx"], log)
    if code != 0:
        raise RuntimeError("pip couldn't install WhisperX — see the log above.")
    if not engine_installed():
        raise RuntimeError("Install finished but WhisperX still isn't visible. Restart the app.")
    return "WhisperX installed."


def install_ffmpeg(log):
    log("Installing a self-contained FFmpeg…")
    if run_streamed([sys.executable, "-m", "pip", "install", "--upgrade", "imageio-ffmpeg"], log):
        raise RuntimeError("pip couldn't install imageio-ffmpeg.")
    out = subprocess.run([sys.executable, "-c",
                          "import imageio_ffmpeg;print(imageio_ffmpeg.get_ffmpeg_exe())"],
                         capture_output=True, text=True)
    src = out.stdout.strip()
    if not src or not os.path.isfile(src):
        raise RuntimeError("Couldn't locate the FFmpeg program after installing.")
    os.makedirs(BIN_DIR, exist_ok=True)
    shutil.copy2(src, os.path.join(BIN_DIR, "ffmpeg.exe" if os.name == "nt" else "ffmpeg"))
    return "FFmpeg installed in the app's bin folder."


def download_models(cfg, hf_token, log):
    env = {k: v for k, v in dict(ONLINE_ENV, PATH=os.environ["PATH"]).items()
           if k not in ("HF_HUB_OFFLINE", "TRANSFORMERS_OFFLINE", "HF_DATASETS_OFFLINE")}
    if hf_token:
        env["HF_TOKEN"] = hf_token   # passed via environment, not the command line
    cmd = [sys.executable, os.path.abspath(__file__), "--download-models",
           "--whisper-model", cfg["whisper_model"], "--language", cfg["language"] or "en"]
    if run_streamed(cmd, log, env=env):
        raise RuntimeError("Model download failed — see the log. For speaker labels, accept the "
                           "pyannote model terms on huggingface.co with the same account as your token.")
    return "Models downloaded. Transcription now works fully offline."


def download_models_main():
    args = sys.argv
    model = args[args.index("--whisper-model") + 1] if "--whisper-model" in args else "large-v3-turbo"
    lang = args[args.index("--language") + 1] if "--language" in args else "en"
    print("Downloading models. No patient data is used in this step.", flush=True)
    try:
        import torch
        import whisperx
        device = "cuda" if torch.cuda.is_available() else "cpu"
        compute = "float16" if device == "cuda" else "int8"
        print(f"• Speech model ({model})…", flush=True)
        del_m = whisperx.load_model(model, device, compute_type=compute, language=lang or None)
        del del_m
        print(f"• Word-alignment model ({lang or 'en'})…", flush=True)
        whisperx.load_align_model(language_code=lang or "en", device=device)
        token = os.environ.get("HF_TOKEN")
        if token:
            print("• Speaker-identification model…", flush=True)
            DP = getattr(whisperx, "DiarizationPipeline", None)
            if DP is None:
                from whisperx.diarize import DiarizationPipeline as DP
            try:
                DP(use_auth_token=token, device=device)
            except TypeError:
                DP(token=token, device=device)
        else:
            print("• No Hugging Face token saved — skipping the speaker model.", flush=True)
        print("DONE", flush=True)
        return 0
    except Exception as e:
        print(f"FAILED: {type(e).__name__}: {e}", flush=True)
        return 1


# --------------------------------------------------------------------------- #
# Documents: text extraction, agency manual reference, past-note import
# --------------------------------------------------------------------------- #
IMPORT_EXTS = (".txt", ".md", ".docx", ".pdf")


def pdf_support():
    with _PROBE_LOCK:
        if "pdf" in _SETUP_PROBES:
            return _SETUP_PROBES["pdf"]
    res = importlib.util.find_spec("pypdf") is not None
    with _PROBE_LOCK:
        _SETUP_PROBES["pdf"] = res
    return res


def install_pdf_support(log):
    if run_streamed([sys.executable, "-m", "pip", "install", "--upgrade", "pypdf"], log):
        raise RuntimeError("pip couldn't install pypdf.")
    return "PDF support installed."


def text_from_bytes(data, ext):
    """extract_text for a file held in memory (a decrypted vault file): nothing readable touches the disk."""
    import io
    return extract_text("memory" + ext, src=io.BytesIO(data))


def extract_text(path, src=None):
    """Plain text from .txt/.md/.docx/.pdf — all read locally. `src`: an open binary file instead of path."""
    ext = os.path.splitext(path)[1].lower()
    if ext == ".docx":
        import html
        import zipfile
        with zipfile.ZipFile(src or path) as z:
            xml = z.read("word/document.xml").decode("utf-8", errors="replace")
        paras = []
        for p in re.findall(r"<w:p[ >].*?</w:p>", xml, flags=re.S):
            p = re.sub(r"<w:tab/>", "\t", p)
            # page breaks become form feeds, so multi-page documents can be reassembled
            p = re.sub(r"<w:br[^>]*w:type=\"page\"[^>]*/>|<w:lastRenderedPageBreak/>", "<w:t>\f</w:t>", p)
            p = re.sub(r"<w:br[^>]*/>", "\n", p)
            # only <w:t> itself — "<w:t[^>]*>" also matched <w:tabs>, <w:tc>, <w:tbl>…, pulling the paragraph's
            # formatting XML into the text
            runs = re.findall(r"<w:t(?:\s[^>]*)?>(.*?)</w:t>", p, flags=re.S)
            paras.append(html.unescape(re.sub(r"<[^>]+>", "", "".join(runs))))
        return _normalize("\n".join(paras))
    if ext == ".pdf":
        try:
            from pypdf import PdfReader
        except ImportError:
            raise RuntimeError("Reading PDFs needs a small add-on: click Settings → Install next to "
                               "\"PDF support\". (Or use a .docx / .txt copy.)") from None
        pages = []
        for pg in PdfReader(src or path).pages:
            try:   # layout mode keeps lines intact; plain mode can put one word per line
                txt = pg.extract_text(extraction_mode="layout") or ""
            except TypeError:
                txt = pg.extract_text() or ""
            pages.append(txt)
        return _normalize("\f".join(pages))
    if src is not None:
        return _normalize(src.read().decode("utf-8", errors="replace"))
    with open(path, encoding="utf-8", errors="replace") as f:
        return _normalize(f.read())


def strip_word_xml(text):
    """Text imported before the .docx fix could carry Word formatting XML (<w:pPr>…); keep only the words."""
    if "<w:" not in (text or ""):
        return text or ""
    import html
    return _normalize(html.unescape(re.sub(r"<[^>]+>", "", text)))


def _normalize(text):
    text = re.sub(r"[​‌‍﻿ ]", lambda m: " " if m.group() == " " else "", text)
    text = text.replace("’", "'").replace("“", '"').replace("”", '"')
    pages = text.split("\f")                       # keep page boundaries
    return "\f".join("\n".join(re.sub(r"[ \t]{2,}", " ", line).rstrip() for line in pg.split("\n"))
                     for pg in pages)


def _clean_lines(s):
    out = []
    for line in s.splitlines():
        line = line.strip().replace("\\.", ".")
        if not line or re.fullmatch(r"\d{1,3}", line) or "SOUTH SHORE COUNSELING" in line.upper() \
                or line.lower().startswith("feel free to print"):
            continue
        out.append(line)
    return out


def _section(text, start_pat, end_pats, max_len=9000):
    """Text after the first heading match that isn't a table-of-contents entry."""
    for m in re.finditer(start_pat, text, flags=re.I):
        line_rest = text[m.end():text.find("\n", m.end()) if "\n" in text[m.end():] else len(text)]
        if "(page" in line_rest.lower():
            continue
        rest = text[m.end():]
        end = len(rest)
        for ep in end_pats:
            e = re.search(ep, rest, flags=re.I)
            if e and e.start() < end:
                end = e.start()
        chunk = rest[:end][:max_len]
        if len(chunk.strip()) > 40:
            return chunk
    return ""


def parse_reference(text):
    """Pull the example progress notes, intervention vocabulary and intake discussion
    points out of the agency manual's text. Nothing leaves the computer."""
    ex = _section(text, r"progress note examples", [r"examples? of keywords", r"common (intervention )?"
                                                    r"documentation terms", r"theranest guidelines"])
    lines = _clean_lines(ex)
    joined = "\n".join(lines)
    items = [re.sub(r"\s+", " ", x).strip() for x in re.split(r"(?:^|\n)\s*\d{1,2}\.\s+", joined)]
    items = [x for x in items if len(x) > 80]
    if len(items) < 2:                                   # unnumbered: one example per paragraph
        items, cur = [], ""
        for line in lines:
            cur = (cur + " " + line).strip()
            if re.search(r"[.!?\"”]$", line) and len(cur) > 150:
                items.append(cur)
                cur = ""
        if len(cur) > 80:
            items.append(cur)
    vocab = _section(text, r"examples? of keywords[^\n]*", [r"theranest guidelines", r"how to write a treatment plan"],
                     max_len=5000)
    points = _section(text, r"intake discussion points", [r"administrative reminders", r"phone call script",
                                                          r"\bsafety plan\b\s*\n\s*\n", r"registration form"],
                      max_len=2500)
    return {"examples": items[:12], "vocabulary": "\n".join(_clean_lines(vocab)),
            "intake_points": "\n".join(_clean_lines(points))}


def style_block(ref, kind):
    if not ref:
        return ""
    exs = voc = pts = ""
    if kind == "progress" and ref.get("examples"):
        exs = "\nEXAMPLE PROGRESS NOTES:\n" + "\n\n".join(
            f"Example {i}: {e}" for i, e in enumerate(ref["examples"][:9], 1)) + "\n"
    if kind in ("progress", "intake") and ref.get("vocabulary"):
        voc = f"\nAPPROVED INTERVENTION VOCABULARY:\n{ref['vocabulary'][:4000]}\n"
    if kind == "intake" and ref.get("intake_points"):
        pts = f"\nINTAKE DISCUSSION POINTS:\n{ref['intake_points'][:2000]}\n"
    if not (exs or voc or pts):
        return ""
    return fill(STYLE_HEADER, {"examples": exs, "vocabulary": voc, "intake_points": pts})


_MONTHS = {m: i for i, m in enumerate(["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug",
                                       "sep", "oct", "nov", "dec"], 1)}


# ---------------------------------------------------------------- date format
# Dates are always stored as YYYY-MM-DD; this only changes how they're shown and typed.
DATE_FORMATS = {"iso": "YYYY-MM-DD", "us": "MM/DD/YYYY", "eu": "DD/MM/YYYY", "long": "Nov 7, 2026"}
_DATE_PREF = {"fmt": "iso"}
_ISO_RE = re.compile(r"\b(\d{4})-(\d{2})-(\d{2})\b")
_MON_ABBR = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def set_date_format(fmt):
    _DATE_PREF["fmt"] = fmt if fmt in DATE_FORMATS else "iso"


def date_hint():
    """What to type, for messages: e.g. 'MM/DD/YYYY'."""
    return {"iso": "YYYY-MM-DD", "us": "MM/DD/YYYY", "eu": "DD/MM/YYYY", "long": "Nov 7, 2026"}[_DATE_PREF["fmt"]]


def _fmt_ymd(y, m, d):
    f = _DATE_PREF["fmt"]
    if f == "us":
        return f"{m:02d}/{d:02d}/{y:04d}"
    if f == "eu":
        return f"{d:02d}/{m:02d}/{y:04d}"
    if f == "long" and 1 <= m <= 12:
        return f"{_MON_ABBR[m - 1]} {d}, {y}"
    return f"{y:04d}-{m:02d}-{d:02d}"


def fmt_date(s):
    """'2026-11-07' (or '2026-11-07T15:19…') in the chosen format; anything else unchanged."""
    if not s:
        return s or ""
    s = str(s)
    m = re.match(r"(\d{4})-(\d{2})-(\d{2})", s)
    if not m:
        return s
    rest = s[10:]
    if rest[:1] == "T":                       # timestamp: keep just the date
        rest = ""
    return _fmt_ymd(int(m[1]), int(m[2]), int(m[3])) + rest


def fmt_short(s):
    """Month and day only, in the chosen format (for chart labels): '11/12', '12/11', 'Nov 12' or '11-12'."""
    m = re.match(r"(\d{4})-(\d{2})-(\d{2})", str(s or ""))
    if not m:
        return str(s or "")
    mo, d = int(m[2]), int(m[3])
    f = _DATE_PREF["fmt"]
    if f == "us":
        return f"{mo}/{d}"
    if f == "eu":
        return f"{d}/{mo}"
    if f == "long" and 1 <= mo <= 12:
        return f"{_MON_ABBR[mo - 1]} {d}"
    return f"{mo:02d}-{d:02d}"


def fmt_dates_in(text):
    """Every YYYY-MM-DD inside a piece of text, in the chosen format."""
    if _DATE_PREF["fmt"] == "iso" or not text:
        return text
    return _ISO_RE.sub(lambda m: _fmt_ymd(int(m[1]), int(m[2]), int(m[3])), text)


def parse_date(s):
    """A date typed in any common format -> 'YYYY-MM-DD', or '' if it isn't a real date.
    Ambiguous 03/04/2026 follows the chosen format (day first only for DD/MM/YYYY)."""
    s = (s or "").strip()
    if not s:
        return ""
    y = mo = d = None
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", s)
    if m:
        y, mo, d = int(m[1]), int(m[2]), int(m[3])
    else:
        m = re.fullmatch(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})", s)
        if m:
            a, b, y = int(m[1]), int(m[2]), int(m[3]) + (2000 if len(m[3]) == 2 else 0)
            mo, d = (b, a) if _DATE_PREF["fmt"] == "eu" else (a, b)
            if mo > 12 >= d:                   # 25/12/2026 can only mean one thing
                mo, d = d, mo
        else:
            m = re.fullmatch(r"([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})", s)
            if m and m[1].lower() in _MONTHS:
                y, mo, d = int(m[3]), _MONTHS[m[1].lower()], int(m[2])
            else:
                m = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})", s)
                if m and m[2].lower() in _MONTHS:
                    y, mo, d = int(m[3]), _MONTHS[m[2].lower()], int(m[1])
    if y is None:
        return ""
    try:
        return date(y, mo, d).isoformat()
    except ValueError:
        return ""


def find_date(s):
    """First date in the text as YYYY-MM-DD, or ''."""
    best = None
    for m in re.finditer(r"\b(20\d{2})-(\d{1,2})-(\d{1,2})\b", s):
        cand = (m.start(), (int(m[1]), int(m[2]), int(m[3])))
        best = cand if best is None or cand[0] < best[0] else best
    for m in re.finditer(r"\b(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}|\d{2})\b", s):
        y = int(m[3]) + (2000 if len(m[3]) == 2 else 0)
        cand = (m.start(), (y, int(m[1]), int(m[2])))
        best = cand if best is None or cand[0] < best[0] else best
    for m in re.finditer(r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})\b",
                         s, flags=re.I):
        cand = (m.start(), (int(m[3]), _MONTHS[m[1].lower()[:3]], int(m[2])))
        best = cand if best is None or cand[0] < best[0] else best
    if best and best[1]:
        y, mo, d = best[1]
        if 1 <= mo <= 12 and 1 <= d <= 31:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    return ""


def guess_kind(text):
    head = text[:400].lower()
    return "intake" if any(k in head for k in ("intake", "initial exam", "diagnostic impression",
                                               "presenting problem")) else "progress"


def guess_session_number(text):
    m = re.search(r"session\s*(?:#|no\.?|number)?\s*(\d{1,3})\b", text[:300], flags=re.I)
    return m[1] if m else ""


# TheraNest exports: each document starts with one of these headings, and a document
# that runs over several pages repeats its heading (and header block) on every page.
EHR_HEADERS = [
    ("intake", re.compile(r"^\s*INITIAL\s+ASSESSMENT\s+AND\s+DIAGNOSTIC\s+IMPRESSIONS?\b", re.I)),
    ("plan", re.compile(r"^\s*MUTUAL\s+TREATMENT\s+PLAN\b", re.I)),
    ("progress", re.compile(r"^\s*PROGRESS\s+NOTES?\b", re.I)),
]
# which "…Date:" label dates each kind of document (first match wins); DOB etc. never count
DATE_LABELS = {
    "progress": ["service", "session", "appointment", ""],
    "plan": ["", "plan", "start", "created", "creation"],
    "intake": ["intake", "assessment", "service", "evaluation", "session", ""],
}
NOT_A_VISIT_DATE = ("birth", "dob", "review", "target", "end", "sign", "due", "discharge", "expir", "next")
PAGE_ARTIFACT = re.compile(r"^\s*(page\s+\d+(\s*(of|/)\s*\d+)?|\d+\s*(of|/)\s*\d+)\s*$", re.I)


def header_kind(line):
    if len(line.strip()) > 90:                 # a heading, not a sentence that mentions it
        return None
    for kind, rx in EHR_HEADERS:
        if rx.search(line):
            return kind
    return None


def labeled_date(text, kind):
    """The document's own date, e.g. 'Service Date: 04/01/2026' for a progress note."""
    found = []                                  # (label prefix, iso date)
    for line in text.split("\n")[:60]:
        for m in re.finditer(r"([A-Za-z][A-Za-z /]{0,25}?)?\bdate\s*(?:of\s+(\w+)\s*)?[:\-]\s*([^\n]{4,40})",
                             line, flags=re.I):
            prefix = ((m.group(1) or "") + " " + (m.group(2) or "")).strip().lower()
            if any(bad in prefix for bad in NOT_A_VISIT_DATE):
                continue
            iso = find_date(m.group(3))
            if iso:
                found.append((prefix, iso))
    for want in DATE_LABELS.get(kind, [""]):
        for prefix, iso in found:
            if (want == "" and prefix in ("", "the")) or (want and want in prefix):
                return iso
    if found:
        return found[0][1]
    for line in text.split("\n"):              # last resort: first date not on a birth-date line
        if not any(bad in line.lower() for bad in ("birth", "dob")):
            iso = find_date(line)
            if iso:
                return iso
    return ""


def parse_ehr_export(text):
    """Split a TheraNest bulk export into documents. Returns None if the text doesn't
    use the TheraNest headings (so the generic splitter is used instead)."""
    text = text.replace("\r\n", "\n")
    if not any(header_kind(l) for l in text.split("\n")):
        return None
    # 1) pages (form feeds) — or, for pasted text, start a new piece at every heading
    from collections import Counter
    counts = Counter(l.strip() for l in text.split("\n") if l.strip())
    # letterhead-style lines repeated on every page (they belong with the heading below them)
    repeated = {l for l, n in counts.items() if n >= 3 and len(l) < 90 and not header_kind(l)}
    pieces = []
    for page in text.split("\f"):
        cur = []
        for line in page.split("\n"):
            if header_kind(line) and any(header_kind(x) for x in cur):   # another heading on this page
                carry = []
                while cur and (not cur[-1].strip() or cur[-1].strip() in repeated):
                    carry.insert(0, cur.pop())
                pieces.append("\n".join(cur))
                cur = carry
            cur.append(line)
        pieces.append("\n".join(cur))
    # 2) classify each piece
    segs = []
    for pc in pieces:
        lines = [l for l in pc.split("\n") if not PAGE_ARTIFACT.match(l)]
        if not any(l.strip() for l in lines):
            continue
        kind = next((header_kind(l) for l in lines[:25] if header_kind(l)), None)
        body = "\n".join(lines).strip()
        segs.append({"kind": kind, "date": labeled_date(body, kind) if kind else "", "text": body})
    # 3) glue pages of the same document back together
    docs = []
    for sg in segs:
        prev = docs[-1] if docs else None
        same = prev is not None and (sg["kind"] is None or (
            sg["kind"] == prev["kind"] and (not sg["date"] or sg["date"] == prev["date"])))
        if same:
            top = {l.strip() for l in prev["text"].split("\n")[:20] if l.strip()}
            lines = sg["text"].split("\n")
            i = 0                                   # drop the repeated page header block
            while i < len(lines) and i < 20 and (not lines[i].strip() or lines[i].strip() in top
                                                 or header_kind(lines[i])):
                i += 1
            rest = "\n".join(lines[i:]).strip()
            if rest:
                prev["text"] += "\n" + rest
        elif sg["kind"] is None and not docs:
            if len(sg["text"]) > 200:               # substantial text before any heading
                docs.append({"kind": guess_kind(sg["text"]), "date": find_date(sg["text"][:300]),
                             "text": sg["text"]})
        else:
            docs.append(dict(sg))
    return [{"date": d["date"], "number": guess_session_number(d["text"]) if d["kind"] == "progress" else "",
             "kind": d["kind"], "text": tidy_ehr_note(d["text"], d["kind"]), "ehr": True}
            for d in docs if len(d["text"]) >= 20]


# ---- tidying imported TheraNest notes ------------------------------------------------
MSE_FIELDS = ["Thought Process", "Thought Content", "Appearance", "Orientation", "Behaviour", "Behavior",
              "Speech", "Affect", "Mood", "Perception", "Judgement", "Judgment", "Insight", "Appetite", "Sleep"]
MSE_LABEL = re.compile(r"\b(" + "|".join(f.replace(" ", r"\s+") for f in MSE_FIELDS) + r")\s*:", re.I)
MSE_START = re.compile(r"^\s*(" + "|".join(f.replace(" ", r"\s+") for f in MSE_FIELDS) + r")\s*:", re.I)
FIELD_LINE = re.compile(r"^\s*[A-Z][A-Za-z0-9 /()&'#.,-]{1,45}:(\s|$)")
LETTERHEAD = re.compile(r"south\s+shore\s+counseling", re.I)
INSURER = re.compile(r"Insurer\(?s?\)?\s*:.*?(?=\b(?:Place\s+of\s+Service|CPT\s+Code|Case\s*#|Provider\(s\)|"
                     r"Service\s+Date|Session\s+Start)\b|$)", re.I)
STAFF_SIG = re.compile(r"\bStaff\s+Signature\b", re.I)
SIG_DETAIL = re.compile(r"(\bsign(ed|ature)?\b|electronically|\bdate\b|\btime\b|\d{1,2}/\d{1,2}/\d{2,4}|"
                        r"\d{1,2}:\d{2}|\b(MHC|LMHC|LMHC-D|LCSW|LMSW|MA|EdM|PhD|PsyD|NPI|Extern|Intern)\b)", re.I)
FOCUS_LINE = re.compile(r"^\s*([A-Za-z /()&'-]{0,40}\bfocus\b[A-Za-z /()&'-]{0,40}):\s*(.*)$", re.I)
WNL_ONLY = re.compile(r"^\s*(wnl|w\.n\.l\.?|within\s+normal\s+limits?)\s*[.,;]?\s*$", re.I)


def _mse_summary(region_text):
    """'Appearance: WNL Orientation: WNL Mood: Anxious, tired' -> ['Mood: Anxious, tired']"""
    hits = list(MSE_LABEL.finditer(region_text))
    keep = []
    for i, m in enumerate(hits):
        end = hits[i + 1].start() if i + 1 < len(hits) else len(region_text)
        value = re.sub(r"\s+", " ", region_text[m.end():end]).strip(" ,;")
        if value and not WNL_ONLY.match(value):
            label = re.sub(r"\s+", " ", m.group(1)).title()
            keep.append(f"{label}: {value}")
    return keep


def tidy_ehr_note(text, kind="progress"):
    """Clean a note imported from TheraNest:
    - drop the letterhead ("SOUTH SHORE COUNSELING …") and the document heading
    - drop the Insurer(s) entry and the Staff Signature block
    - progress notes: keep only mental-status items that say more than plain "WNL"
    - progress notes: put the primary focus of the session at the top"""
    lines = text.replace("\r\n", "\n").replace("\f", "\n").split("\n")
    out = []
    i = 0
    while i < len(lines):
        line = lines[i]
        t = line.strip()
        if LETTERHEAD.search(t) and len(t) < 90 or header_kind(t) or PAGE_ARTIFACT.match(t):
            i += 1
            continue
        if re.search(r"Insurer\(?s?\)?\s*:", line, re.I):
            line = INSURER.sub("", line).rstrip()
            if not line.strip():
                i += 1
                continue
        sig = STAFF_SIG.search(line)
        if sig:
            before = line[:sig.start()].rstrip()
            if before.strip():
                out.append(before)
            i += 1                                   # signature details that follow it
            while i < len(lines) and (not lines[i].strip() or (
                    SIG_DETAIL.search(lines[i]) and len(lines[i].split()) <= 14
                    and not re.search(r"\b(supervisor|clinical)\s+signature\b", lines[i], re.I)
                    and not MSE_START.match(lines[i]) and not FOCUS_LINE.match(lines[i]))):
                i += 1
            continue
        if kind == "progress" and MSE_START.match(line):
            region = [line]
            j = i + 1
            while j < len(lines):
                nxt = lines[j].strip()
                if not nxt or MSE_START.match(nxt):
                    region.append(lines[j])
                    j += 1
                    continue
                # a short wrapped value, only if more mental-status fields follow it
                k = j + 1
                while k < len(lines) and not lines[k].strip():
                    k += 1
                if len(nxt.split()) <= 8 and not FIELD_LINE.match(nxt) and k < len(lines) \
                        and MSE_START.match(lines[k]):
                    region.append(lines[j])
                    j += 1
                    continue
                # the last field's value wrapped onto the next line ("Sleep: Decreased, waking at / night")
                if lines[j - 1].strip() and len(nxt.split()) <= 6 and not FIELD_LINE.match(nxt) \
                        and (nxt[:1].islower() or lines[j - 1].rstrip().endswith((",", "and", "or", "at", "to"))):
                    region.append(lines[j])
                    j += 1
                break
            kept = _mse_summary(" ".join(region))
            out.extend(kept)
            if kept:
                out.append("")
            i = j
            continue
        out.append(line)
        i += 1

    if kind == "progress":
        out = _focus_first(out)
    text = "\n".join(l.rstrip() for l in out)
    text = re.sub(r"(?<=[^.:;!?\n])\n(?=[a-z])", " ", text)      # rejoin sentences the PDF wrapped
    return re.sub(r"\n{3,}", "\n\n", text).strip()


def _focus_first(lines):
    """Move the 'Primary Focus of Session' entry to the top. Without one, the first narrative
    paragraph (the clinical summary) goes first instead, ahead of the admin header lines."""
    for i, l in enumerate(lines):
        m = FOCUS_LINE.match(l)
        if not m:
            continue
        block, j = [l.strip()], i + 1
        if not m.group(2).strip():                       # value on the following line(s)
            while j < len(lines) and not lines[j].strip():
                j += 1
        while j < len(lines) and lines[j].strip() and not FIELD_LINE.match(lines[j]):
            block.append(lines[j].strip())
            j += 1
        if len(block) == 1 and not m.group(2).strip():
            return lines                                 # empty field: leave as is
        label = m.group(1).strip()
        value = " ".join([m.group(2).strip()] + block[1:]).strip()
        return [f"{label}: {value}", ""] + lines[:i] + lines[j:]
    # no labelled focus: first real paragraph goes first
    start = next((i for i, l in enumerate(lines) if len(l.split()) >= 8 and not FIELD_LINE.match(l)
                  and re.search(r"[a-z]", l)), None)
    if start is None or start == 0:
        return lines
    j = start
    while j < len(lines) and lines[j].strip() and not FIELD_LINE.match(lines[j]):
        j += 1
    return lines[start:j] + [""] + lines[:start] + lines[j:]


TIDY_VERSION = 1      # bump if the import clean-up rules change, so older imports get re-tidied once


def tidy_all_imported(vault):
    """One-time clean-up of every note/plan imported before the clean-up existed (all patients).
    Each record is marked with TIDY_VERSION afterwards, so it's never re-tidied — later edits you
    make to an imported note stay exactly as you leave them. Returns (notes changed, plans changed)."""
    now = datetime.now().isoformat(timespec="seconds")
    n_notes = n_plans = 0
    for sid, m in vault.session_index().items():
        if m.get("source") != "imported" or m.get("tidy_version", 0) >= TIDY_VERSION:
            continue
        try:
            d = vault.load_session(sid)
        except Exception:
            continue
        meta = d.setdefault("meta", {})
        new = tidy_ehr_note(d.get("note", ""), meta.get("kind", "progress"))
        if new and new != d.get("note", "").strip():
            d["note"] = new
            meta["updated"] = now
            n_notes += 1
        meta["tidy_version"] = TIDY_VERSION
        vault.save_session(d, sid)
    for c in vault.list_clients():
        changed = False
        for pl in c.get("treatment_plans", []):
            if pl.get("imported") and pl.get("tidy_version", 0) < TIDY_VERSION:
                new = tidy_ehr_note(pl.get("text", ""), "plan")
                if new and new != pl.get("text", "").strip():
                    pl["text"] = new
                    n_plans += 1
                pl["tidy_version"] = TIDY_VERSION
                changed = True
        if changed:
            vault.save_client(c)
    return n_notes, n_plans


def split_notes(text, split=True):
    """One file may hold several notes (e.g. copied from the EHR). TheraNest exports are
    split by their headings; anything else at short lines that contain a date.
    Returns [{date, number, kind, text}] (kind: intake / progress / plan)."""
    text = text.replace("\r\n", "\n").strip()
    if not text:
        return []
    if split:
        ehr = parse_ehr_export(text)
        if ehr is not None:
            return ehr
    text = text.replace("\f", "\n")

    chunks = [text]
    if split:
        lines, starts = text.split("\n"), []
        for i, line in enumerate(lines):
            if len(line.strip()) <= 70 and find_date(line):
                starts.append(i)
        if len(starts) >= 2:
            if starts[0] != 0 and "\n".join(lines[:starts[0]]).strip():
                starts.insert(0, 0)
            chunks = ["\n".join(lines[a:b]).strip() for a, b in zip(starts, starts[1:] + [len(lines)])]
    out = []
    for c in chunks:
        if len(c) < 20:
            continue
        out.append({"date": find_date(c[:200]), "number": guess_session_number(c),
                    "kind": guess_kind(c), "text": c})
    return out


# --------------------------------------------------------------------------- #
# Transcription
# --------------------------------------------------------------------------- #
def fmt_ts(seconds):
    s = int(seconds or 0)
    return f"{s // 3600:02d}:{s % 3600 // 60:02d}:{s % 60:02d}"


# --------------------------------------------------------------------------- #
# Stopping a task that's running in the background
# --------------------------------------------------------------------------- #
class Cancelled(Exception):
    """The task was called off (e.g. its session was discarded)."""


class WorkerError(Exception):
    """A failure reported by the transcription process; the message is already user-friendly."""


class CancelToken:
    """Handed to one background task. cancel() stops it for real: the transcription process is
    killed and the connection to LM Studio is cut (which makes LM Studio stop writing)."""

    def __init__(self):
        self._ev = threading.Event()
        self._lock = threading.Lock()
        self._stoppers = []
        self._pausers = []                  # (freeze, unfreeze) for work that can be paused in place
        self.paused = threading.Event()

    def is_set(self):
        return self._ev.is_set()

    def on_pause(self, freeze, unfreeze):
        """Register how to freeze/unfreeze this task's work in place. Returns an unregister function."""
        pair = (freeze, unfreeze)
        with self._lock:
            self._pausers.append(pair)
        if self.paused.is_set():
            _quiet(freeze)
        return lambda: self._unpause_forget(pair)

    def _unpause_forget(self, pair):
        with self._lock:
            if pair in self._pausers:
                self._pausers.remove(pair)

    def can_freeze(self):
        with self._lock:
            return bool(self._pausers) and not self._ev.is_set()

    def pause(self):
        self.paused.set()
        with self._lock:
            pairs = list(self._pausers)
        for freeze, _ in pairs:
            _quiet(freeze)

    def resume(self):
        with self._lock:
            pairs = list(self._pausers)
        for _, unfreeze in pairs:
            _quiet(unfreeze)
        self.paused.clear()

    def check(self):
        if self._ev.is_set():
            raise Cancelled()

    def on_cancel(self, fn):
        """Run fn() when the task is cancelled (now, if it already was). Returns an unregister function."""
        with self._lock:
            if not self._ev.is_set():
                self._stoppers.append(fn)
                return lambda: self._forget(fn)
        _quiet(fn)
        return lambda: None

    def _forget(self, fn):
        with self._lock:
            if fn in self._stoppers:
                self._stoppers.remove(fn)

    def cancel(self):
        with self._lock:
            if self._ev.is_set():
                return
            self._ev.set()
            fns, self._stoppers = self._stoppers, []
        for fn in fns:
            _quiet(fn)


_TASK = threading.local()          # the CancelToken of the background task running on this thread


def current_token():
    return getattr(_TASK, "token", None)


def check_cancelled():
    t = current_token()
    if t is not None:
        t.check()


def on_cancel(fn):
    t = current_token()
    return t.on_cancel(fn) if t is not None else (lambda: None)


class StageError(Exception):
    """Wraps a failure with the transcription step it happened in."""

    def __init__(self, stage, original):
        super().__init__(f"{stage}: {original}")
        self.stage, self.original = stage, original


def friendly_error(e):
    if isinstance(e, (WorkerError, Cancelled)):
        return str(e) or "Stopped."
    if isinstance(e, StageError):
        base = friendly_error(e.original)
        detail = f"{type(e.original).__name__}: {e.original}".strip()
        if len(detail) > 400:
            detail = detail[:400] + "…"
        return f"{base}\n\nStep that failed: {e.stage}\nDetails: {detail}"
    msg = str(e)
    if isinstance(e, ModuleNotFoundError) and "whisperx" in msg:
        return ("The speech engine (WhisperX) isn't installed for the Python running this app.\n\n"
                "Click Settings (top right) → Install next to \"Speech engine\".")
    if isinstance(e, FileNotFoundError) and "ffmpeg" in msg.lower():
        return "FFmpeg is missing. Click Settings → Install next to \"FFmpeg\"."
    if any(t in msg for t in ("LocalEntryNotFound", "Cannot find an appropriate cached",
                              "offline mode", "HF_HUB_OFFLINE", "local_files_only")):
        return ("A model this step needs isn't downloaded yet. Open Settings: the Speech models row "
                "shows which piece is missing. Click Download there (one-time; no patient data).")
    if isinstance(e, NetworkBlocked):
        return (f"A component tried to go online and was blocked ({msg}). If you haven't yet, "
                "run Settings → Download models; afterwards everything works offline.")
    return f"{type(e).__name__}: {msg}"


def _stage(name, fn, *a, **k):
    try:
        return fn(*a, **k)
    except (ModuleNotFoundError, StageError):
        raise
    except Exception as e:
        raise StageError(name, e) from e


class _ProgressStream:
    """Stands in for stdout/stderr while WhisperX runs and turns its progress
    printouts ("Progress: 42.1%..." or "[12.3 --> 15.6]") into a fraction 0..1.
    Also keeps the app working under pythonw, where stdout/stderr don't exist."""

    def __init__(self, on_fraction, duration):
        self.on_fraction, self.duration, self.buf, self.best = on_fraction, duration, "", 0.0

    def write(self, s):
        self.buf += s
        *lines, self.buf = re.split(r"[\r\n]", self.buf)
        for line in lines:
            frac = None
            m = re.search(r"Progress:\s*([\d.]+)\s*%", line)
            if m:
                frac = float(m[1]) / 100
            else:
                m = re.search(r"\[\s*[\d.]+\s*-->\s*([\d.]+)\s*\]", line)
                if m and self.duration:
                    frac = float(m[1]) / self.duration
            if frac is not None:
                frac = max(0.0, min(frac, 1.0))
                if frac >= self.best:
                    self.best = frac
                    self.on_fraction(frac)
        return len(s)

    def flush(self):
        pass

    def isatty(self):
        return False

    def fileno(self):                   # not a real file: say so the standard way (libraries handle this)
        import io
        raise io.UnsupportedOperation("fileno")


def _with_progress(on_fraction, duration, fn, *a, **k):
    import contextlib
    stream = _ProgressStream(on_fraction, duration)
    with contextlib.redirect_stdout(stream), contextlib.redirect_stderr(stream):
        return fn(*a, **k)


def _call_with_optional(fn, optional, *a, **k):
    """Call fn with extra keyword args if this WhisperX version accepts them."""
    try:
        return fn(*a, **dict(k, **optional))
    except TypeError as e:
        if not any(name in str(e) for name in optional):
            raise
        return fn(*a, **k)


class _HookedPipeline:
    """Wraps pyannote's pipeline so WhisperX's diarization reports progress."""

    def __init__(self, inner, hook):
        self._inner, self._hook = inner, hook

    def __call__(self, *a, **k):
        try:
            return self._inner(*a, hook=self._hook, **k)
        except TypeError as e:
            if "hook" not in str(e):
                raise
            return self._inner(*a, **k)

    def __getattr__(self, name):
        return getattr(self._inner, name)


_WORKER_TAG = "@@SSW "


def _kill_tree(p):
    """Stop the transcription process and anything it started (FFmpeg), immediately."""
    if p.poll() is not None:
        return
    try:
        if IS_WIN:
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(p.pid)], capture_output=True, timeout=15)
        else:
            import signal
            os.killpg(p.pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        p.kill()
    except Exception:
        pass


def _worker_python():
    """The Python running this app — the console build on Windows (no window appears: see
    _QuietPopen) so the child has proper pipes."""
    py = sys.executable
    if IS_WIN and os.path.basename(py).lower() == "pythonw.exe":
        alt = os.path.join(os.path.dirname(py), "python.exe")
        if os.path.isfile(alt):
            py = alt
    return py


# --------------------------------------------------------------------------- #
# Learned timing: how fast THIS computer does each step (for an accurate bar and "time left")
# --------------------------------------------------------------------------- #
TIMING_PATH = os.path.join(LOCAL_DIR, "timing.json")      # per computer, never synced: speeds differ
_TIMING_LOCK = threading.Lock()
# seconds for "load"/"spk_load"; seconds per minute of recording for the rest. First guesses only —
# replaced by what this computer actually takes after its first transcription.
TX_DEFAULTS = {"cpu": {"load": 35.0, "read": 0.4, "tx": 18.0, "align": 4.0, "spk_load": 12.0, "spk": 14.0},
               "cuda": {"load": 15.0, "read": 0.4, "tx": 2.5, "align": 1.0, "spk_load": 6.0, "spk": 3.0}}
TX_PER_MIN = ("read", "tx", "align", "spk")
LLM_DEFAULTS = {"prefill": 350.0, "gen": 20.0}             # characters per second: reading the prompt / writing
CHARS_PER_AUDIO_MIN = 800                                 # transcript size, roughly, for estimates ahead of time


_TIMING_MEMO = {"stamp": None, "data": {}}


def _timing_load():
    """The learned timings (read again only when the file changes; it's checked on every
    progress repaint). Returns a copy, so callers can change it freely."""
    try:
        st = os.stat(TIMING_PATH)
        stamp = (st.st_mtime_ns, st.st_size)
    except OSError:
        return {}
    if stamp != _TIMING_MEMO["stamp"]:
        try:
            with open(TIMING_PATH, encoding="utf-8") as f:
                t = json.load(f)
        except (OSError, ValueError):
            return {}
        _TIMING_MEMO.update(stamp=stamp, data=t if isinstance(t, dict) else {})
    return copy.deepcopy(_TIMING_MEMO["data"])


def _timing_save(t):
    try:
        os.makedirs(os.path.dirname(TIMING_PATH), exist_ok=True)
        tmp = TIMING_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(t, f, indent=1)
        _replace_with_retry(tmp, TIMING_PATH)
    except OSError:
        pass


def _blend(old, new, n):
    """Average of the first few runs, then weighted toward recent ones (adapts within a few jobs)."""
    if old is None:
        return new
    w = max(0.25, 1.0 / (n + 1))
    return old * (1 - w) + new * w


def timing_tx(model):
    """{'cpu': {...}, 'cuda': {...}, 'last_device': ...} for one speech model — learned where known."""
    t = _timing_load().get("tx", {})
    out = {"last_device": t.get("last_device"), "typical_secs": t.get("typical_secs")}
    for dev, base in TX_DEFAULTS.items():
        d, learned = dict(base), t.get(f"{model}|{dev}") or {}
        d.update({k: v for k, v in learned.items() if k in base and isinstance(v, (int, float)) and v > 0})
        d["n"] = learned.get("n", 0)
        out[dev] = d
    return out


def record_tx(model, device, timings, audio_secs):
    """Learn from a finished transcription. timings: {step: seconds actually spent (pauses excluded)}."""
    if not audio_secs or audio_secs < 30 or device not in TX_DEFAULTS:
        return
    mins = audio_secs / 60
    with _TIMING_LOCK:
        t = _timing_load()
        cur = t.setdefault("tx", {}).setdefault(f"{model}|{device}", {})
        n = cur.get("n", 0)
        for step, secs in (timings or {}).items():
            if step in TX_DEFAULTS[device] and isinstance(secs, (int, float)) and secs > 0:
                val = secs / mins if step in TX_PER_MIN else secs
                cur[step] = round(_blend(cur.get(step), val, n), 3)
        cur["n"] = n + 1
        t["tx"]["last_device"] = device
        t["tx"]["typical_secs"] = round(_blend(t["tx"].get("typical_secs"), audio_secs, n))  # your usual length
        _timing_save(t)


def typical_audio_secs():
    """Your usual recording length (learned), for estimates when a recording's own length can't be read."""
    v = _timing_load().get("tx", {}).get("typical_secs")
    return v if isinstance(v, (int, float)) and v > 0 else 45 * 60


def timing_llm(model=None):
    t = _timing_load().get("llm", {})
    d = dict(LLM_DEFAULTS)
    d.update(t.get(model or t.get("last_model") or "", {}))
    return d


def record_llm(model, prompt_chars, prefill_secs, out_chars, gen_secs):
    with _TIMING_LOCK:
        t = _timing_load()
        llm = t.setdefault("llm", {})
        cur = llm.setdefault(model or "?", {})
        n = cur.get("n", 0)
        if gen_secs > 1.0 and out_chars > 200:
            cur["gen"] = round(_blend(cur.get("gen"), out_chars / gen_secs, n), 2)
        if prefill_secs > 0.5 and prompt_chars > 2000:
            cur["prefill"] = round(_blend(cur.get("prefill"), prompt_chars / prefill_secs, n), 1)
        cur["n"] = n + 1
        llm["last_model"] = model
        _timing_save(t)


def _out_key(label):
    return re.sub(r"\d+", "#", label or "")


def expected_out(label, default):
    """How long this kind of document usually turns out (characters), learned per step."""
    v = _timing_load().get("out", {}).get(_out_key(label))
    return v if isinstance(v, (int, float)) and v > 50 else default


def record_out(label, chars):
    if chars < 50:
        return
    with _TIMING_LOCK:
        t = _timing_load()
        out = t.setdefault("out", {})
        k = _out_key(label)
        n = out.get(k + "|n", 0)
        out[k] = round(_blend(out.get(k), chars, n))
        out[k + "|n"] = n + 1
        _timing_save(t)


def estimate_tx_secs(model, diarize, audio_secs, device=None):
    prof = timing_tx(model)
    p = prof[device or prof["last_device"] or "cpu"]
    mins = (audio_secs or typical_audio_secs()) / 60
    total = p["load"] + mins * (p["read"] + p["tx"] + p["align"])
    return total + ((p["spk_load"] + mins * p["spk"]) if diarize else 0)


WRITE_STEPS = {"progress": (("Writing the progress note", 1000), ("Writing the session overview", 3500)),
               "intake": (("Writing the intake assessment", 4000),
                          ("Filling in the #-section intake questionnaire", 5000)),
               "parent": (("Writing the contact note", 1200), ("Writing the conversation summary", 2500))}


def estimate_write_secs(kind, transcript_chars, context_chars=8000):
    r = timing_llm()
    total = 0.0
    for label, dflt in WRITE_STEPS.get(kind, WRITE_STEPS["progress"]):
        total += (transcript_chars + context_chars) / r["prefill"] + expected_out(label, dflt) / r["gen"]
    return total


def fmt_left(secs):
    """'~4 min left', '~1 h 10 min left', '~30 s left'."""
    secs = max(0, float(secs))
    if secs >= 3600:
        h, m = divmod(int(round(secs / 60)), 60)
        return f"~{h} h {m} min left" if m else f"~{h} h left"
    if secs >= 90:
        return f"~{round(secs / 60)} min left"
    return f"~{max(5, round(secs / 5) * 5):.0f} s left"


_DUR_RE = re.compile(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)")


def audio_seconds(path):
    """A recording's length, read by FFmpeg in a fraction of a second (None if it can't tell)."""
    exe = shutil.which("ffmpeg")
    if not exe or not path or not os.path.isfile(path):
        return None
    try:
        r = subprocess.run([exe, "-hide_banner", "-i", path], capture_output=True, timeout=20,
                           **({"creationflags": 0x08000000} if IS_WIN else {}))
    except Exception:
        return None
    m = _DUR_RE.search(r.stderr.decode("utf-8", "replace"))
    if not m:
        return None
    h, mi, sec = m.groups()
    return int(h) * 3600 + int(mi) * 60 + float(sec)


def set_eta(secs):
    """Time left for the running task (seconds, or None). The task's progress updates carry it to the bar."""
    _TASK.eta = None if secs is None else max(0.0, float(secs))


# ---- picking up where a transcription left off ------------------------------------------------------
# A recording is transcribed in pieces of about CHUNK_SECS, cut at a quiet moment. Each finished piece
# (and each finished step after it) is saved at once to an encrypted checkpoint on this computer, so if
# the transcription is interrupted — the computer slept, the app was closed, the power went — the next
# run starts after the last finished piece instead of from the beginning. Checkpoints are encrypted with
# a key derived from the vault key, named by keyed hashes (no file names or patient details), removed as
# soon as the session is saved, and after CKPT_KEEP_SECS regardless.
CHUNK_SECS = 10 * 60
SESSION_EXTRA_KEYS = ("review", "risk_check", "goals_check", "ai_draft", "revisions")   # kept when a session is re-saved
QUEUE_FILE = os.path.join(LOCAL_DIR, "queue.enc")   # this computer's recording queue, kept between runs (encrypted)
CKPT_DIR = os.path.join(LOCAL_DIR, "checkpoints")
CKPT_KEEP_SECS = 3 * 24 * 3600
CKPT_VERSION = 1
_CKPT = {"secret": None}


def set_checkpoint_secret(vault_key):
    """Called when the vault is unlocked (vault_key: its urlsafe-base64 key)."""
    _CKPT["secret"] = hmac.new(base64.urlsafe_b64decode(vault_key), b"session-scribe/checkpoints/v1",
                               hashlib.sha256).digest()


def _ckpt_tag(text):
    return hmac.new(_CKPT["secret"], text.encode("utf-8"), hashlib.sha256).hexdigest()


def checkpoint_for(audio_path, cfg, diarize):
    """{"dir", "key"} for this recording with these settings (None if the vault isn't unlocked)."""
    if not _CKPT["secret"] or not audio_path:
        return None
    try:
        st = os.stat(audio_path)
    except OSError:
        return None
    full = os.path.abspath(audio_path)
    who = json.dumps([full, st.st_size, st.st_mtime_ns, cfg.get("whisper_model") or "large-v3-turbo",
                      cfg.get("language") or "", bool(diarize), cfg.get("min_speakers"), cfg.get("max_speakers"),
                      CHUNK_SECS, CKPT_VERSION])
    name = _ckpt_tag("path:" + os.path.normcase(full))[:16] + "-" + _ckpt_tag("run:" + who)[:16]
    key = base64.urlsafe_b64encode(hmac.new(_CKPT["secret"], ("key:" + who).encode("utf-8"),
                                            hashlib.sha256).digest()).decode()
    return {"dir": os.path.join(CKPT_DIR, name), "key": key}


def checkpoint_clear(audio_path):
    """The session from this recording is saved: its checkpoints aren't needed any more."""
    if not _CKPT["secret"] or not audio_path or not os.path.isdir(CKPT_DIR):
        return
    prefix = _ckpt_tag("path:" + os.path.normcase(os.path.abspath(audio_path)))[:16] + "-"
    for d in os.listdir(CKPT_DIR):
        if d.startswith(prefix):
            _ckpt_remove(os.path.join(CKPT_DIR, d))


def checkpoint_tidy():
    """Remove checkpoints nobody came back for."""
    try:
        names = os.listdir(CKPT_DIR)
    except OSError:
        return
    for d in names:
        p = os.path.join(CKPT_DIR, d)
        try:
            if time.time() - os.path.getmtime(p) > CKPT_KEEP_SECS:
                _ckpt_remove(p)
        except OSError:
            pass


def _ckpt_remove(folder):
    try:
        for fn in os.listdir(folder):
            _quiet(wipe_file, os.path.join(folder, fn))
        os.rmdir(folder)
    except OSError:
        pass


class _Checkpoint:
    """The worker's side: encrypted pieces of one transcription in progress."""

    def __init__(self, info):
        self.on = bool(info and info.get("dir") and info.get("key"))
        if self.on:
            from cryptography.fernet import Fernet
            self.dir, self.f = info["dir"], Fernet(info["key"].encode())
            try:
                os.makedirs(self.dir, exist_ok=True)
                os.utime(self.dir)                     # in use: not "abandoned" yet
            except OSError:
                self.on = False

    def load(self, name):
        if not self.on:
            return None
        try:
            with open(os.path.join(self.dir, name + ".enc"), "rb") as fh:
                return json.loads(self.f.decrypt(fh.read()))
        except Exception:                              # missing, half-written or unreadable: redo that part
            return None

    def save(self, name, obj):
        if not self.on:
            return

        def plain(o):
            for attr in ("item", "tolist"):
                if hasattr(o, attr):
                    return getattr(o, attr)()
            return str(o)
        try:
            path = os.path.join(self.dir, name + ".enc")
            with open(path + ".tmp", "wb") as fh:
                fh.write(self.f.encrypt(json.dumps(obj, default=plain).encode("utf-8")))
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(path + ".tmp", path)
        except OSError:
            pass

    def reset(self):
        if self.on:
            for fn in os.listdir(self.dir):
                _quiet(os.remove, os.path.join(self.dir, fn))


def _chunk_bounds(audio, sr=16000):
    """[(start, end)] sample ranges of about CHUNK_SECS each, cut at the quietest half second near each
    boundary so no word is split. A recording up to 1.5 × CHUNK_SECS is one piece."""
    n = len(audio)
    step = CHUNK_SECS * sr
    if n <= step * 1.5:
        return [(0, n)]
    try:
        import numpy as np
        a = np.asarray(audio, dtype="float32")
    except Exception:                                    # (no NumPy: cut at the plain marks)
        a = None
    cuts, pos = [0], step
    while n - pos > step * 0.5:
        lo, hi = max(cuts[-1] + 60 * sr, pos - 20 * sr), min(n - 30 * sr, pos + 20 * sr)
        cut = pos
        if a is not None and hi - lo > sr:
            fr = sr // 10
            seg = a[lo:hi]
            k = len(seg) // fr
            e = (seg[:k * fr].reshape(k, fr) ** 2).mean(axis=1)
            if k >= 5:
                e = np.convolve(e, np.ones(5) / 5, mode="same")
            cut = lo + int(np.argmin(e)) * fr + fr // 2
        cuts.append(int(cut))
        pos = int(cut) + step
    cuts.append(n)
    return [(int(x), int(y)) for x, y in zip(cuts[:-1], cuts[1:])]


def _shift_segments(segs, offset):
    """Move segment and word times by offset seconds (pieces are transcribed from 0)."""
    out = []
    for s in segs or []:
        s = dict(s)
        for k in ("start", "end"):
            if s.get(k) is not None:
                s[k] = round(float(s[k]) + offset, 3)
        if s.get("words"):
            s["words"] = [dict(w, **{k: round(float(w[k]) + offset, 3) for k in ("start", "end")
                                     if w.get(k) is not None}) for w in s["words"]]
        out.append(s)
    return out


class _SleepWatch:
    """Notices when the computer was asleep (time jumps ahead while nothing ran), so waiting limits
    don't count that time and a connection broken by it is retried."""
    last_gap_at = 0.0

    @classmethod
    def start(cls):
        if getattr(cls, "_started", False):
            return
        cls._started = True

        def run():
            prev = time.time()
            while True:
                time.sleep(2.0)
                now = time.time()
                if now - prev > 20.0:
                    cls.last_gap_at = now
                prev = now
        threading.Thread(target=run, daemon=True).start()

    @classmethod
    def slept_since(cls, t):
        return cls.last_gap_at >= t


def keep_awake(on):
    """While a recording is being transcribed or its notes written, don't let the computer go to sleep
    on its own (Windows; per thread: call from the thread doing the work). Closing the lid or choosing
    Sleep still works — the work then carries on, or picks up where it left off, afterwards."""
    if not IS_WIN:
        return
    try:
        import ctypes
        ctypes.windll.kernel32.SetThreadExecutionState(0x80000000 | (0x00000001 if on else 0))
    except Exception:
        pass


WORKER_LOG = os.path.join(LOCAL_DIR, "logs", "transcription.log")
WORKER_STALL_SECS = 20 * 60        # no word at all from the worker for this long: it's hung, stop it
_TICK_RE = re.compile(r" \(\d+:\d\d\)$")


def worker_log_text(limit=200_000):
    """The last transcription's technical log (this computer only), or ''."""
    out = []
    for path in (WORKER_LOG + ".1", WORKER_LOG):          # the run before, then the latest
        try:
            with open(path, encoding="utf-8", errors="replace") as f:
                out.append(f"==== {os.path.basename(path)} ====\n" + f.read()[-limit:])
        except OSError:
            pass
    return "\n".join(out)


def _start_worker_log(audio_path):
    """Open a fresh log for this run (keeping the previous one). Returns (file, redact) or (None, None)."""
    try:
        os.makedirs(os.path.dirname(WORKER_LOG), exist_ok=True)
        if os.path.exists(WORKER_LOG):
            _replace_with_retry(WORKER_LOG, WORKER_LOG + ".1")
        f = open(WORKER_LOG, "w", encoding="utf-8", errors="replace")
    except OSError:
        return None, None
    hide = sorted({x for x in (audio_path, os.path.abspath(audio_path), os.path.basename(audio_path),
                               os.path.splitext(os.path.basename(audio_path))[0]) if x and len(x) > 3},
                  key=len, reverse=True)

    def redact(line):                   # the recording's name can carry a client code: never log it
        for h in hide:
            line = line.replace(h, "<recording>")
        return line
    return f, redact


WORKER_RETRIES = 2                 # a worker that dies (or hangs) mid-way is started again this many times


def transcribe(audio_path, cfg, hf_token, progress):
    """progress(text, percent). Runs WhisperX in its own process on this computer, so it can be
    stopped instantly (the session was discarded, the queue job was cancelled) and its memory is
    fully released afterwards. The audio never leaves the computer; results come back over a pipe.

    While a step runs with nothing new to say (the model loading can take minutes on a processor),
    the status shows how long it has been going, so "slow" never looks like "stuck". If the worker
    says nothing at all for WORKER_STALL_SECS it is stopped and reported, instead of hanging forever.

    Interrupted part-way (the worker died, hung, or the computer slept long enough to break it), it is
    started again automatically and carries on from the last finished piece (see checkpoint_for)."""
    check_cancelled()
    ckpt = checkpoint_for(audio_path, cfg, speakers_on(hf_token))
    if ai_engine(cfg) == "builtin":
        ENGINE.make_room(cfg)          # a computer short on memory unloads the AI while it transcribes
    if os.environ.get("SESSION_SCRIBE_INPROC_TRANSCRIBE"):
        return transcribe_here(audio_path, cfg, hf_token, progress, ckpt)
    _SleepWatch.start()
    keep_awake(True)
    try:
        attempt = 0

        def pieces_saved():
            try:
                return len(os.listdir(ckpt["dir"])) if ckpt else 0
            except OSError:
                return 0
        while True:
            before = pieces_saved()
            result, error, stalled, code = _transcribe_run(audio_path, cfg, hf_token, progress, ckpt, attempt)
            check_cancelled()
            if result is not None or error is not None:
                break
            if attempt >= WORKER_RETRIES:
                break
            if stalled is not None and pieces_saved() <= before:
                break                    # hung without finishing anything: trying again would hang the same way
            attempt += 1
            print(f"[app] the transcription process {'stopped responding' if stalled else 'ended early'}"
                  f" (exit code {code}); starting it again (attempt {attempt + 1})", file=sys.stderr)
            progress("Picking up where it left off…", None)
    finally:
        keep_awake(False)
    mname = cfg.get("whisper_model") or "large-v3-turbo"
    if stalled is not None and result is None and error is None:
        raise WorkerError(f"Transcription stopped responding during “{stalled.rstrip('…')}” (nothing for "
                          f"{WORKER_STALL_SECS // 60} minutes) and was stopped. Settings → “Test the speech engine” "
                          "checks this computer; the technical details are under Settings → “Transcription log”. "
                          "What was finished is kept: starting it again carries on from there.")
    if error is not None:
        if error.get("missing_module"):
            raise ModuleNotFoundError(error["msg"], name=error["missing_module"])
        raise WorkerError(error["msg"])
    if result is not None and result.get("timing"):
        tm = result["timing"]                              # learn this computer's speed (pauses excluded)
        _quiet(record_tx, mname, tm.get("device"), tm.get("times"), tm.get("audio_secs"))
    if result is None:
        raise WorkerError("The transcription process stopped unexpectedly (exit code "
                          f"{code}). If this keeps happening, the computer may be running out of memory "
                          "— try a smaller speech model in Settings. Details: Settings → “Transcription log”. "
                          "What was finished is kept: starting it again carries on from there.")
    return result["segments"], result["duration"], result["diarized"], result["aligned"]


def _transcribe_run(audio_path, cfg, hf_token, progress, ckpt, attempt=0):
    """One run of the worker process: (result, error, stalled step or None, exit code)."""
    env = dict(os.environ)
    extra = [p for p in sys.path if p and os.path.isdir(p)
             and not any(os.path.abspath(p).startswith(os.path.abspath(b))
                         for b in {sys.prefix, sys.base_prefix, sys.exec_prefix})]
    if extra:                     # paths added at run time (rare) must reach the child too
        env["PYTHONPATH"] = os.pathsep.join(extra + [env["PYTHONPATH"]] if env.get("PYTHONPATH") else extra)
    env["PYTHONIOENCODING"] = "utf-8"
    env["PYTHONUNBUFFERED"] = "1"
    kw = {} if IS_WIN else {"start_new_session": True}
    log, redact = _start_worker_log(audio_path)
    p = subprocess.Popen([_worker_python(), os.path.abspath(__file__), "--transcribe-worker"],
                         stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE if log else subprocess.DEVNULL,
                         cwd=APP_DIR, env=env, **kw)
    forget = on_cancel(lambda: _kill_tree(p))
    tok = current_token()
    unpause = tok.on_pause(lambda: _freeze_process(p, True), lambda: _freeze_process(p, False)) if tok \
        else (lambda: None)
    inbox = queue.Queue()

    def read_out():                     # stdout -> inbox, so this thread can keep time while waiting
        try:
            for raw in p.stdout:
                inbox.put(raw)
        except (OSError, ValueError):
            pass
        inbox.put(None)

    def read_err():                     # stderr -> the local log, file name blanked out
        try:
            for raw in p.stderr:
                log.write(redact(raw.decode("utf-8", errors="replace").replace("\r\n", "\n")))
                log.flush()
        except (OSError, ValueError):
            pass
        _quiet(log.close)
    threading.Thread(target=read_out, daemon=True).start()
    if log:
        threading.Thread(target=read_err, daemon=True).start()
    result, error, ok, stalled = None, None, False, None
    try:
        mname = cfg.get("whisper_model") or "large-v3-turbo"
        job = {"audio": audio_path, "hf_token": hf_token or "", "parent_pid": os.getpid(),
               "cfg": dict({k: cfg.get(k) for k in ("whisper_model", "language", "batch_size", "whisper_threads",
                                                    "min_speakers", "max_speakers") if cfg.get(k) is not None},
                           timing=timing_tx(mname), duration_hint=audio_seconds(audio_path)),
               "ckpt": ckpt}
        p.stdin.write((json.dumps(job) + "\n").encode("utf-8"))
        p.stdin.flush()
        _quiet(p.stdin.close)               # the job is all it gets; it watches this process to know we're gone
        last_text = "Starting the speech engine…" if not attempt else "Picking up where it left off…"
        last_pct, last_eta = None if attempt else 0, None
        heard = step_start = last_tick = wall = time.time()
        shown = -1
        while True:
            try:
                raw = inbox.get(timeout=1.0)
            except queue.Empty:
                raw = False
            now = time.time()
            if now - wall > 20:                 # the computer was asleep: that time isn't "silence"
                heard += now - wall - 1.0
                step_start += now - wall - 1.0
                last_tick = now
            wall = now
            if raw is False:
                if tok is not None and tok.paused.is_set():   # frozen on purpose: the clocks don't run
                    heard += now - last_tick
                    step_start += now - last_tick
                    last_tick = now
                    continue
                last_tick = now
                if now - heard > WORKER_STALL_SECS:
                    stalled = last_text
                    _kill_tree(p)
                    break
                secs = int(now - step_start)
                if now - heard >= 8 and secs >= 10 and secs // 5 != shown:   # gone quiet: show it's still going
                    shown = secs // 5
                    set_eta(None if last_eta is None else last_eta - (now - heard))
                    progress(f"{last_text.rstrip('…')}… ({secs // 60}:{secs % 60:02d})", last_pct)
                continue
            if raw is None:
                break
            line = raw.decode("utf-8", errors="replace")
            if not line.startswith(_WORKER_TAG):
                continue
            heard = last_tick = time.time()
            msg = json.loads(line[len(_WORKER_TAG):])
            if msg["t"] == "p":
                if msg["text"] != last_text:
                    step_start, shown = heard, -1
                last_text, last_pct, last_eta = msg["text"], msg.get("pct"), msg.get("eta")
                set_eta(last_eta)
                progress(msg["text"], msg.get("pct"))
            elif msg["t"] == "r":
                result = msg
            elif msg["t"] == "e":
                error = msg
        ok = True
    except (BrokenPipeError, OSError, ValueError):
        ok = True
    finally:
        forget()
        unpause()
        if not ok:                          # stopped by an error here (or cancelled): don't leave it running
            _kill_tree(p)
        _quiet(p.stdin.close)
        try:
            p.wait(timeout=30)
        except Exception:
            _kill_tree(p)
    return result, error, stalled, p.returncode


def _freeze_process(p, freeze):
    """Pause (freeze) or continue a worker process exactly where it is."""
    if p.poll() is not None:
        return
    if IS_WIN:
        import ctypes
        nt = ctypes.WinDLL("ntdll")
        fn = nt.NtSuspendProcess if freeze else nt.NtResumeProcess
        fn.argtypes = (ctypes.c_void_p,)
        fn(ctypes.c_void_p(int(p._handle)))
    else:
        import signal
        sig = signal.SIGSTOP if freeze else signal.SIGCONT
        try:
            os.killpg(p.pid, sig)                  # the worker and anything it started (ffmpeg)
        except OSError:
            os.kill(p.pid, sig)


def _watch_parent(pid):
    """Worker: exit the moment the app that started it is gone (closed, crashed, or killed).

    This must NOT be done by waiting to read stdin. On Windows, while one thread waits to read a
    pipe, every other query of that pipe waits too — and loading the speech engine's libraries
    queries stdin (their C runtime start-up does), so the engine froze forever while loading NumPy.
    Waiting on the app's process handle touches no pipe at all."""
    if not pid:
        return
    if IS_WIN:
        import ctypes
        from ctypes import wintypes
        k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        k32.OpenProcess.restype = wintypes.HANDLE
        k32.OpenProcess.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.DWORD)
        k32.WaitForSingleObject.restype = wintypes.DWORD
        k32.WaitForSingleObject.argtypes = (wintypes.HANDLE, wintypes.DWORD)
        handle = k32.OpenProcess(0x00100000, False, int(pid))         # SYNCHRONIZE
        if handle:
            k32.WaitForSingleObject(handle, 0xFFFFFFFF)                  # returns when the app ends
    else:
        while os.getppid() == int(pid):
            time.sleep(1.0)
    os._exit(3)


def transcribe_worker_main():
    """Child process: read one job from stdin, transcribe on this computer, write the result to stdout."""
    out = os.fdopen(os.dup(1), "w", encoding="utf-8", buffering=1)
    devnull = os.open(os.devnull, os.O_WRONLY)
    os.dup2(devnull, 1)              # anything WhisperX/C libraries print goes nowhere, not into our pipe
    sys.stdout = open(os.devnull, "w")
    # stderr is NOT thrown away: the app writes it (with the recording's file name blanked out) to a
    # log on this computer, so a crash or hang while loading leaves something to go on
    import faulthandler
    real_err = sys.stderr      # kept: during transcription sys.stderr is the progress catcher, not a file
    faulthandler.enable(file=real_err)                # a hard crash prints where it happened
    lock = threading.Lock()

    def plain(o):                       # numpy numbers/arrays inside WhisperX results
        for attr in ("item", "tolist"):
            if hasattr(o, attr):
                return getattr(o, attr)()
        return str(o)

    def send(**m):
        with lock:
            out.write(_WORKER_TAG + json.dumps(m, default=plain) + "\n")
            out.flush()
        if m.get("t") == "p":                         # progress made: re-arm the "silent for 3 min" stack dump
            try:                                      # (diagnostics only: must never stop a transcription)
                faulthandler.cancel_dump_traceback_later()
                faulthandler.dump_traceback_later(180, repeat=True, file=real_err)
            except Exception:
                pass
    job = json.loads(sys.stdin.readline() or "{}")
    print(f"[worker] start {time.strftime('%Y-%m-%d %H:%M:%S')} python {sys.version.split()[0]} "
          f"model={(job.get('cfg') or {}).get('whisper_model') or 'large-v3-turbo'}", file=sys.stderr, flush=True)

    _quiet(sys.stdin.close)            # never read stdin again (see _watch_parent)
    threading.Thread(target=_watch_parent, args=(job.get("parent_pid"),), daemon=True).start()
    try:
        segs, dur, diar, aligned = transcribe_here(job["audio"], job.get("cfg") or {}, job.get("hf_token"),
                                                   lambda text, pct=None: send(t="p", text=text, pct=pct,
                                                                               eta=getattr(_TASK, "eta", None)),
                                                   job.get("ckpt"))
        send(t="r", segments=segs, duration=dur, diarized=diar, aligned=aligned,
             timing=getattr(transcribe_here, "last_timing", None))
    except ModuleNotFoundError as e:
        send(t="e", msg=friendly_error(e), missing_module=getattr(e, "name", None) or "whisperx")
    except Exception as e:
        import traceback
        traceback.print_exc(file=sys.stderr)
        send(t="e", msg=friendly_error(e))
    faulthandler.cancel_dump_traceback_later()
    print(f"[worker] end {time.strftime('%Y-%m-%d %H:%M:%S')}", file=sys.stderr, flush=True)
    out.flush()
    _quiet(sys.stderr.flush)
    os._exit(0)                         # skip slow library teardown


class _TimedPlan:
    """Overall percent and time left across the transcription's steps, from how long each step takes on
    this computer (learned — see timing_tx). Steps that report no progress of their own (loading a model)
    fill by time. Time spent frozen — paused, or the computer asleep — doesn't count, and isn't learned."""
    TIME_FILL = ("load", "read", "spk_load")

    def __init__(self, say, est):
        self.say, self.order, self.est = say, [k for k, _ in est], dict(est)
        self.lock = threading.Lock()
        self.span, self.pct, self.frozen, self._last = {}, 0.0, 0.0, time.time()
        self.cur, self.cur_start, self.frac, self.text, self.times, self.done = None, 0.0, 0.0, "", {}, False
        self._replan(0)
        threading.Thread(target=self._fill, daemon=True).start()

    def clock(self):
        return time.time() - self.frozen

    def _replan(self, i):
        """Share what's left of the bar among the remaining steps, by their expected time."""
        rest = self.order[i:]
        tot = sum(self.est[k] for k in rest) or 1.0
        lo = self.pct
        for k in rest:
            hi = lo + (100.0 - self.pct) * self.est[k] / tot
            self.span[k], lo = (lo, hi), hi

    def set_est(self, step, secs):
        with self.lock:
            self.est[step] = max(0.1, float(secs))
            if self.cur in self.order:
                self._replan(self.order.index(self.cur))

    def _speed(self):
        """How this run compares with the estimates so far (finished steps that scale with the audio)."""
        done = [k for k in self.times if k not in self.TIME_FILL and self.est.get(k)]
        if not done:
            return 1.0
        return max(0.4, min(2.5, sum(self.times[k] for k in done) / sum(self.est[k] for k in done)))

    def _eta(self):
        cur_left = 0.0
        if self.cur in self.est:
            spent = self.clock() - self.cur_start
            cur_left = max(self.est[self.cur] * (1 - self.frac), self.est[self.cur] - spent, 0.0)
            if self.cur in self.TIME_FILL:
                cur_left = max(self.est[self.cur] - spent, 0.1 * self.est[self.cur])
        rest = self.order[self.order.index(self.cur) + 1:] if self.cur in self.order else []
        return cur_left + self._speed() * sum(self.est[k] for k in rest)

    def _emit(self):
        lo, hi = self.span.get(self.cur, (self.pct, self.pct))
        self.pct = max(self.pct, lo + (hi - lo) * self.frac)
        self.say(self.text, self.pct, self._eta())

    def begin(self, step, text):
        with self.lock:
            now = self.clock()
            if self.cur is not None:
                self.times[self.cur] = self.times.get(self.cur, 0.0) + now - self.cur_start
            self.cur, self.cur_start, self.frac, self.text = step, now, 0.0, text
            if step in self.order:
                self.pct = max(self.pct, self.span[step][0])
                self._replan(self.order.index(step))
            self._emit()

    def update(self, frac, text=None):
        with self.lock:
            self.frac = max(self.frac, min(float(frac), 1.0))
            if text:
                self.text = text
            self._emit()

    def finish(self):
        with self.lock:
            if self.cur is not None:
                self.times[self.cur] = self.times.get(self.cur, 0.0) + self.clock() - self.cur_start
            self.cur, self.done = None, True
            self.pct = 100.0
        self.say("Finishing up…", 100, 0)

    def _fill(self):
        while not self.done:
            time.sleep(0.5)
            now = time.time()
            gap, self._last = now - self._last, now
            if gap > 3.0:                    # we were frozen (paused / asleep): that time doesn't count
                self.frozen += gap - 0.5
            with self.lock:
                if self.done or self.cur not in self.TIME_FILL:
                    continue
                f = min(0.95, (self.clock() - self.cur_start) / max(self.est[self.cur], 0.1))
                if f > self.frac + 0.004:
                    self.frac = f
                    self._emit()


def transcribe_here(audio_path, cfg, hf_token, progress, ckpt=None):
    """progress(text, percent) — percent is overall 0-100 across every step, in proportion to how long
    each step takes on this computer; set_eta() carries the time left alongside. With ckpt (see
    checkpoint_for) every finished piece is saved as it's done, and a later run carries on from there."""
    diarize = speakers_on(hf_token)
    mname = cfg.get("whisper_model") or "large-v3-turbo"
    prof = cfg.get("timing") or timing_tx(mname)
    dev_guess = prof.get("last_device") or "cpu"
    ck = _Checkpoint(ckpt)
    saved = ck.load("plan") or {}
    bounds = [tuple(b) for b in saved.get("bounds") or []]

    def pieces(prefix):
        got = {}
        for i in range(len(bounds)):
            v = ck.load(f"{prefix}-{i}")
            if v is not None:
                got[i] = v
        return got
    tx_done, al_done = pieces("tx"), pieces("al")
    spk_done = ck.load("spk") if diarize else None
    resumed = bool(tx_done)
    mins = (saved.get("duration") or cfg.get("duration_hint") or prof.get("typical_secs") or 45 * 60) / 60

    def left_frac(done):              # share of the recording a step still has to do
        if not bounds or not saved.get("n"):
            return 1.0
        return max(0.0, 1.0 - sum(bounds[i][1] - bounds[i][0] for i in done) / saved["n"])

    def estimates(dev, minutes):
        p = prof.get(dev) or TX_DEFAULTS[dev]
        skip_load = bool(bounds) and len(tx_done) == len(bounds)
        est = [("load", 1.0 if skip_load else p["load"]), ("read", p["read"] * minutes + 1),
               ("tx", max(0.1, p["tx"] * minutes * left_frac(tx_done))),
               ("align", max(0.1, p["align"] * minutes * left_frac(al_done)))]
        if diarize:
            est += [("spk_load", 0.1 if spk_done else p["spk_load"]), ("spk", 0.1 if spk_done else p["spk"] * minutes)]
        return est

    def say(text, pct, eta):
        set_eta(eta)
        progress(text, pct)
    plan = _TimedPlan(say, estimates(dev_guess, mins))
    sr = 16000
    try:
        t0 = time.time()
        if resumed:
            done_secs = sum(bounds[i][1] - bounds[i][0] for i in tx_done) / sr
            plan.begin("load", f"Picking up where it left off ({fmt_ts(done_secs)} already transcribed)…")
            print(f"[worker] resuming: {len(tx_done)}/{len(bounds)} pieces transcribed, {len(al_done)} aligned, "
                  f"speakers {'done' if spk_done else 'to do'}", file=sys.stderr, flush=True)
        else:
            plan.begin("load", "Starting the speech engine…")
        import torch
        import whisperx
        print(f"[worker] engine imported in {time.time() - t0:.1f}s; torch {torch.__version__}", file=sys.stderr, flush=True)

        device = "cuda" if torch.cuda.is_available() else "cpu"
        compute = "float16" if device == "cuda" else "int8"
        lang = saved.get("language") or cfg.get("language") or None
        if device != dev_guess:
            for k, v in estimates(device, mins):
                plan.set_est(k, v)
        model = None

        def load_model():
            plan.update(0, f"Loading the speech model ({mname}, " + ("graphics card" if device == "cuda" else
                           "processor — can take a minute or two") + ")…")
            t1 = time.time()
            threads = int(cfg.get("whisper_threads") or 0) if device == "cpu" else 0
            m = _stage(f"loading the speech model ({mname})", _call_with_optional, whisperx.load_model,
                       {"threads": threads} if threads else {}, mname, device, compute_type=compute, language=lang)
            print(f"[worker] model {mname} loaded on {device}/{compute} in {time.time() - t1:.1f}s",
                  file=sys.stderr, flush=True)
            return m
        if not bounds or len(tx_done) < len(bounds):
            model = load_model()
        plan.begin("read", "Reading the recording…")
        audio = _stage("reading the audio file (FFmpeg)", whisperx.load_audio, audio_path)
        n = len(audio)
        duration = n / sr
        if bounds and saved.get("n") != n:                 # not the same audio after all: start over
            ck.reset()
            bounds, tx_done, al_done, spk_done, resumed, saved = [], {}, {}, None, False, {}
            if model is None:
                model = load_model()
        if not bounds:
            bounds = _chunk_bounds(audio, sr)
            saved = {"bounds": bounds, "n": n, "duration": duration, "language": lang}
            ck.save("plan", saved)
        for k, v in estimates(device, duration / 60):        # now the real length is known
            if k not in ("load", "read"):
                plan.set_est(k, v)

        def piece(a, b):
            return audio if len(bounds) == 1 else audio[a:b]
        label = f"Transcribing {fmt_ts(duration)} of audio"
        done_secs = sum(bounds[i][1] - bounds[i][0] for i in tx_done) / sr
        plan.begin("tx", label + (f" — carrying on from {fmt_ts(done_secs)}" if done_secs else "") + "…")
        todo_secs = max(duration - done_secs, 0.1)
        base = 0.0
        for i, (a, b) in enumerate(bounds):
            if i in tx_done:
                continue
            cd = (b - a) / sr
            res = _stage("transcribing", _with_progress,
                         lambda f, base=base, cd=cd: plan.update((base + f * cd) / todo_secs), cd,
                         _call_with_optional, model.transcribe, {"print_progress": True, "verbose": True},
                         piece(a, b), batch_size=int(cfg.get("batch_size", 8)), language=lang)
            lang = lang or res.get("language")
            tx_done[i] = {"segments": _shift_segments(res.get("segments"), a / sr), "language": res.get("language")}
            ck.save(f"tx-{i}", tx_done[i])               # this piece is safe now, whatever happens next
            if lang and saved.get("language") != lang:
                saved["language"] = lang
                ck.save("plan", saved)
            base += cd
        lang = lang or next((v.get("language") for v in tx_done.values() if v.get("language")), None) or "en"
        model = None
        gc.collect()
        # Alignment gives every word its own timestamps. Word-level speaker assignment
        # (and therefore clean speaker turns) is impossible without it.
        plan.begin("align", f"Lining words up with timestamps ({lang})…")
        need = [i for i in range(len(bounds)) if i not in al_done]
        if need:
            try:
                model_a, md = whisperx.load_align_model(language_code=lang, device=device)
                todo_al = max(sum(bounds[i][1] - bounds[i][0] for i in need) / sr, 0.1)
                base = 0.0
                for i in need:
                    a, b = bounds[i]
                    cd = (b - a) / sr
                    local = _shift_segments(tx_done[i]["segments"], -a / sr)
                    if local:
                        r = _with_progress(lambda f, base=base, cd=cd: plan.update(
                                               (base + f * cd) / todo_al, "Lining words up with timestamps…"),
                                           cd, _call_with_optional, whisperx.align, {"print_progress": True},
                                           local, model_a, md, piece(a, b), device, return_char_alignments=False)
                        al_done[i] = {"segments": _shift_segments(r["segments"], a / sr)}
                    else:
                        al_done[i] = {"segments": []}
                    ck.save(f"al-{i}", al_done[i])
                    base += cd
                del model_a
                gc.collect()
            except Exception as e:
                plan.update(1, f"Word alignment failed ({type(e).__name__}) — speaker labels will be less precise.")
        segments = []
        for i in range(len(bounds)):
            segments += (al_done.get(i) or tx_done[i])["segments"]
        aligned = any(w.get("start") is not None for s in segments for w in s.get("words") or [])
        result = {"segments": segments}
        diarized = False
        if diarize:
            if spk_done is not None:
                plan.begin("spk_load", "Speakers were already identified…")
                import pandas as pd
                segs = pd.DataFrame(spk_done["rows"], columns=["start", "end", "speaker"])
            else:
                plan.begin("spk_load", "Loading the speaker model…")
                DP = getattr(whisperx, "DiarizationPipeline", None)
                if DP is None:
                    from whisperx.diarize import DiarizationPipeline as DP

                def make_dp():
                    try:
                        return DP(use_auth_token=hf_token or None, device=device)
                    except TypeError:
                        return DP(token=hf_token or None, device=device)
                dm = _stage("loading the speaker model (pyannote)", make_dp)
                # pyannote's steps and how much of the speaker step each one takes
                spans = {"segmentation": (0.0, 0.30), "speaker_counting": (0.30, 0.35),
                         "embeddings": (0.35, 0.95), "discrete_diarization": (0.95, 1.0)}
                names = {"segmentation": "Finding where each person speaks",
                         "speaker_counting": "Counting speakers",
                         "embeddings": "Recognizing each speaker's voice",
                         "discrete_diarization": "Assigning speakers"}

                def hook(step, artifact=None, file=None, total=None, completed=None, **_):
                    lo, hi = spans.get(step, (0.0, 1.0))
                    frac = lo + (hi - lo) * (completed / total if total and completed is not None else 0.0)
                    plan.update(frac, f"Identifying speakers: {names.get(step, step)}…")
                if hasattr(dm, "model"):
                    dm.model = _HookedPipeline(dm.model, hook)
                plan.begin("spk", "Identifying speakers…")
                segs = _stage("identifying speakers", _with_progress, lambda f: None, duration, dm, audio,
                              min_speakers=int(cfg.get("min_speakers", 2)),
                              max_speakers=int(cfg.get("max_speakers", 2)))
                try:
                    ck.save("spk", {"rows": [{"start": float(r["start"]), "end": float(r["end"]),
                                              "speaker": str(r["speaker"])}
                                             for r in segs[["start", "end", "speaker"]].to_dict("records")]})
                except Exception:
                    pass
                del dm
                gc.collect()
            result = whisperx.assign_word_speakers(segs, result)   # labels each word, not just segments
            diarized = True
        plan.finish()
    finally:
        plan.done = True
    # a resumed run's times cover only part of the recording: not learned (they'd skew the estimates)
    transcribe_here.last_timing = None if resumed else {
        "device": device, "audio_secs": duration, "times": {k: round(v, 2) for k, v in plan.times.items()}}
    return result["segments"], duration, diarized, aligned


def words_to_turns(segments, pause=2.0, smooth=True, min_dur=0.5, embed_gap=0.3):
    """Build speaker turns from WORD-level speaker labels.

    WhisperX's segment label is a majority vote, so a segment spanning both
    speakers gets one label for everyone's words. After alignment +
    assign_word_speakers each word carries its own `speaker`, so turns are
    rebuilt word by word instead of trusting the segment label.

    * Words with no timing/speaker (often numbers or symbols the aligner can't
      place) inherit the neighbouring speaker and timestamp.
    * Segments with no word data (alignment failed) fall back to the segment label.
    * smooth: a one-word turn shorter than `min_dur` seconds, sitting between two
      turns of the same other speaker with almost no pause on either side
      (< embed_gap s), is treated as diarization flicker and folded back in.
      Real short answers ("No." after a question) have pauses around them, so
      they're left alone.
    """
    words = []
    for s in segments:
        ws = [w for w in (s.get("words") or []) if (w.get("word") or "").strip()]
        if not ws:
            text = (s.get("text") or "").strip()
            if text:
                words.append({"text": text, "start": s.get("start"), "end": s.get("end"),
                              "speaker": s.get("speaker")})
            continue
        for w in ws:
            words.append({"text": w["word"].strip(), "start": w.get("start"), "end": w.get("end"),
                          "speaker": w.get("speaker") or None})
    if not words:
        return []

    # inherit speaker from the nearest labelled neighbour (previous first, then next)
    last = None
    for w in words:
        last = w["speaker"] = w["speaker"] or last
    nxt = None
    for w in reversed(words):
        nxt = w["speaker"] = w["speaker"] or nxt
    # fill missing timestamps from neighbours
    prev_end = 0.0
    for w in words:
        w["speaker"] = w["speaker"] or "SPEAKER"
        w["start"] = float(w["start"]) if w["start"] is not None else prev_end
        w["end"] = float(w["end"]) if w["end"] is not None else w["start"]
        prev_end = max(prev_end, w["end"])

    turns = []
    for w in words:
        t = turns[-1] if turns else None
        if t and t["speaker"] == w["speaker"] and w["start"] - t["end"] < pause:
            t["words"].append(w)
            t["end"] = max(t["end"], w["end"])
        else:
            turns.append({"speaker": w["speaker"], "start": w["start"], "end": w["end"], "words": [w]})

    if smooth:
        i = 1
        while i < len(turns) - 1:
            prev, t, nxt = turns[i - 1], turns[i], turns[i + 1]
            flicker = (len(t["words"]) == 1 and t["end"] - t["start"] < min_dur
                       and prev["speaker"] == nxt["speaker"] != t["speaker"]
                       and t["start"] - prev["end"] < embed_gap and nxt["start"] - t["end"] < embed_gap)
            if flicker:
                prev["words"] += t["words"] + nxt["words"]
                prev["end"] = nxt["end"]
                del turns[i:i + 2]
                i = max(1, i - 1)
            else:
                i += 1

    return [{"start": t["start"], "end": t["end"], "speaker": t["speaker"],
             "text": " ".join(w["text"] for w in t["words"])} for t in turns]


def guess_roles(lines, labels=None):
    labels = labels or ROLES
    you, them, other = labels[0], labels[1], labels[-1]
    speakers = list(dict.fromkeys(l["speaker"] for l in lines))
    if len(speakers) == 1:
        return {speakers[0]: "Speaker"}
    q = {s: 0 for s in speakers}
    for l in lines:
        q[l["speaker"]] += l["text"].count("?")
    clinician = max(speakers, key=lambda s: q[s])
    roles, client_done = {}, False
    for s in speakers:
        if s == clinician:
            roles[s] = you
        elif not client_done:
            roles[s], client_done = them, True
        else:
            roles[s] = other
    return roles


def render_transcript(lines, roles):
    return "\n".join(f"[{fmt_ts(l['start'])}] {roles.get(l['speaker'], l['speaker'])}: {l['text']}"
                     for l in lines)


def parse_name_map(s, legacy=False):
    """'Danielle, Patient; John, Husband' (or one pair per line) -> [(name, '[Placeholder]')].
    A name with no placeholder becomes [Name]. legacy=True reads the old plain
    comma-separated name list."""
    s = s or ""
    if legacy:
        return [(n.strip(), "[Name]") for n in s.split(",") if n.strip()]
    pairs = []
    for entry in re.split(r"[;\n]+", s):
        entry = entry.strip()
        if not entry:
            continue
        name, _, ph = entry.partition(",")
        name, ph = name.strip(), ph.strip().strip("[]").strip() or "Name"
        if name:
            pairs.append((name, f"[{ph}]"))
    return pairs


def apply_name_map(text, pairs):
    """Replace each name (case-insensitive, whole word, possessives included) with its
    placeholder. For a full name like 'Danielle Smith', the first and last names are
    also replaced on their own."""
    expanded = []
    for name, ph in pairs:
        expanded.append((name, ph))
        parts = name.split()
        if len(parts) > 1:
            expanded += [(p, ph) for p in parts if len(p) > 2]
    for name, ph in sorted(expanded, key=lambda x: len(x[0]), reverse=True):
        text = re.sub(r"(?<![\w\[])" + re.escape(name) + r"\b", ph, text, flags=re.IGNORECASE)
    return text


def client_name_map(client):
    return parse_name_map(client.get("names_to_hide", ""), legacy=client.get("names_format") != 2)


_AI_NAMES = {"on": True}


def set_ai_names(on):
    _AI_NAMES["on"] = bool(on)


def names_to_ai(client=None):
    """Whether the local AI reads this patient's real names: Settings › "Patient names for the AI" (on
    unless turned off), unless the patient is set to keep names hidden. The AI runs on this computer, so
    names never leave it either way; names help it keep straight who said and did what."""
    return _AI_NAMES["on"] and not (client or {}).get("hide_names")


def names_note(client=None):
    return "names included" if names_to_ai(client) else "names hidden"


def client_hider(client, always=False):
    """What every AI step passes the patient's material through: names → placeholders ([Patient],
    [Husband]…) when names are hidden, the text as it is when the AI may read them. always=True hides
    regardless — for what's shared beyond you (the supervision packet) or kept for every patient (the
    preferences learned from your edits)."""
    if not always and names_to_ai(client):
        return lambda s: s or ""
    pairs = client_name_map(client)
    return lambda s: apply_name_map(s or "", pairs)


_EMAIL_RE = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")
_PHONE_RE = re.compile(r"(?<!\d)(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}(?!\d)")
_URL_RE = re.compile(r"\bhttps?://\S+|\bwww\.\S+", re.I)


_SPELLED_PHONE_RE = re.compile(r"(?<!\d)(?<!\d )(?:\d ){9,10}\d(?! ?\d)")       # "6 3 1 4 5 6 1 2 3 4" (screen-reader text)


def scrub_contact_details(text):
    """Email addresses, phone numbers and links -> placeholders (messages often carry them in signatures
    and headers, and the patient's names-to-hide list doesn't cover them)."""
    text = _EMAIL_RE.sub("[EMAIL]", text or "")
    text = _URL_RE.sub("[LINK]", text)
    text = _SPELLED_PHONE_RE.sub("[PHONE]", text)
    return _PHONE_RE.sub("[PHONE]", text)


_INVISIBLE_RE = re.compile("[​-‏‪-‮⁦-⁩﻿]")
_WEEKDAYS = "Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday"
_MSG_FROM_RE = re.compile(
    r"^Message from (?P<who>[^,]+), (?P<body>.*), (?:" + _WEEKDAYS + r"), (?P<mon>[A-Za-z]+) (?P<day>\d{1,2}),? "
    r"(?P<year>\d{4}),? (?P<time>\d{1,2}:\d\d\s*[AaPp]\.?[Mm]\.?)\.?$", re.S)
_MSG_STAMP_RE = re.compile(r"^.{0,40}?\s*•\s*\d{1,2}:\d\d\s*[AaPp]\.?[Mm]\.?$")   # "(631) 456-1234 • 1:15 PM"
_MONTHS = {m: i for i, m in enumerate(("january", "february", "march", "april", "may", "june", "july", "august",
                                       "september", "october", "november", "december"), 1)}


def tidy_message_thread(text, other="Patient"):
    """Text messages copied from a phone or messages web app, as plain one-line-per-message text.

    Handles the screen-reader form some apps copy ("* Message from 6 3 1 …, <text>, Friday, November 13
    2026, 1:08 PM." followed by the same text again, and "(631) 456-1234 • 1:15 PM" lines): each message
    becomes "[2026-11-13 1:08 PM] Patient: <text>", the repeated copy and the number/time lines are
    dropped, and the sender's number never appears. Lines it doesn't recognize are kept as they are."""
    out, dup = [], ""
    norm = lambda s: re.sub(r"\s+", " ", s).strip().lower()
    for raw in _INVISIBLE_RE.sub("", text or "").replace("\r\n", "\n").split("\n"):
        line = re.sub(r"^\s*[*•·-]\s*", "", raw).strip() if re.match(r"^\s*[*•·]", raw) else raw.strip()
        if not line:
            if out and out[-1] != "":
                out.append("")
            continue
        m = _MSG_FROM_RE.match(line)
        if m:
            who = m.group("who").strip()
            if re.fullmatch(r"[\d\s+().-]+", who):
                who = other                          # a phone number: the person on the other end
            elif who.lower() in ("you", "me", "myself"):
                who = "Counselor"
            mon = _MONTHS.get(m.group("mon").lower())
            when = (f"{int(m.group('year')):04d}-{mon:02d}-{int(m.group('day')):02d} " if mon else "") + \
                re.sub(r"\s+", " ", m.group("time")).upper().replace(".", "")
            body = m.group("body").strip()
            out.append(f"[{when}] {who}: {body}")
            dup = norm(body)
            continue
        if _MSG_STAMP_RE.match(line):
            continue                                 # the sender/time header the app shows above a message
        if dup and norm(line) and norm(line) in dup:
            continue                                 # the message's text again, right after its description
        dup = ""
        out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def looks_like_message_export(text):
    return bool(re.search(r"(?m)^\W*Message from .+, (?:" + _WEEKDAYS + r"), ", _INVISIBLE_RE.sub("", text or "")))


def read_messages_file(path):
    """Text of a saved message file: .eml (headers + text body), or anything extract_text reads."""
    if path.lower().endswith(".eml"):
        import email
        from email import policy
        with open(path, "rb") as f:
            msg = email.message_from_binary_file(f, policy=policy.default)
        body = msg.get_body(preferencelist=("plain", "html"))
        text = body.get_content() if body else ""
        if body is not None and body.get_content_type() == "text/html":
            text = re.sub(r"<[^>]+>", " ", text)
        head = "\n".join(f"{h}: {msg[h]}" for h in ("From", "To", "Date", "Subject") if msg[h])
        return (head + "\n\n" + text.strip()).strip()
    return extract_text(path)


# --------------------------------------------------------------------------- #
# Built-in AI (installer builds): llama.cpp's llama-server instead of LM Studio
# --------------------------------------------------------------------------- #
# An installer build ships llama-server in engine\ and one or more GGUF models in models\llm\. The app
# starts the server itself (on this computer only, 127.0.0.1) with the model chosen in Settings, sized
# for this computer's memory and graphics, and stops it when the app closes. Without an engine folder
# (a plain copy of the program) everything works with LM Studio, as before.
ENGINE_DIR = os.path.join(APP_DIR, "engine")
LLM_DIRS = (os.path.join(APP_DIR, "models", "llm"), os.path.join(LOCAL_DIR, "models"))
HARDWARE_PATH = os.path.join(LOCAL_DIR, "hardware.json")
GB = 1024 ** 3
_SHARD = re.compile(r"-(\d{5})-of-(\d{5})\.gguf$", re.I)


def engine_exe():
    """The bundled llama-server, or None."""
    for name in ("llama-server.exe", "llama-server"):
        p = os.path.join(ENGINE_DIR, name)
        if os.path.isfile(p):
            return p
    return None


def ai_engine(cfg):
    """'builtin' (bundled llama-server) or 'lmstudio'."""
    choice = (cfg or {}).get("ai_engine") or "auto"
    if choice == "lmstudio":
        return "lmstudio"
    return "builtin" if engine_exe() else "lmstudio"


def ai_name(cfg):
    return "the built-in AI" if ai_engine(cfg) == "builtin" else "LM Studio"


# ---- this computer's hardware --------------------------------------------- #
def _ram_bytes():
    """(total, available) memory in bytes; (0, 0) if it can't be read."""
    try:
        if IS_WIN:
            import ctypes

            class MS(ctypes.Structure):
                _fields_ = [("dwLength", ctypes.c_ulong), ("dwMemoryLoad", ctypes.c_ulong),
                            ("ullTotalPhys", ctypes.c_ulonglong), ("ullAvailPhys", ctypes.c_ulonglong),
                            ("ullTotalPageFile", ctypes.c_ulonglong), ("ullAvailPageFile", ctypes.c_ulonglong),
                            ("ullTotalVirtual", ctypes.c_ulonglong), ("ullAvailVirtual", ctypes.c_ulonglong),
                            ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]
            ms = MS()
            ms.dwLength = ctypes.sizeof(MS)
            ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(ms))
            return int(ms.ullTotalPhys), int(ms.ullAvailPhys)
        if IS_MAC:
            total = int(subprocess.run(["sysctl", "-n", "hw.memsize"], capture_output=True,
                                       text=True, timeout=10).stdout.strip())
            return total, total // 2
        info = {}
        with open("/proc/meminfo") as f:
            for line in f:
                k, _, v = line.partition(":")
                info[k] = int(v.split()[0]) * 1024
        return info.get("MemTotal", 0), info.get("MemAvailable", info.get("MemFree", 0))
    except Exception:
        return 0, 0


def _cpu_info():
    """(name, physical cores, logical cores)."""
    logical = os.cpu_count() or 4
    name, physical = platform.processor() or "", 0
    try:
        if IS_WIN:
            out = subprocess.run(["powershell", "-NoProfile", "-Command",
                                  "Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores | "
                                  "ConvertTo-Json"], capture_output=True, text=True, timeout=30).stdout
            rows = json.loads(out or "[]")
            rows = rows if isinstance(rows, list) else [rows]
            physical = sum(int(r.get("NumberOfCores") or 0) for r in rows)
            name = (rows[0].get("Name") or name).strip() if rows else name
        elif not IS_MAC and os.path.exists("/proc/cpuinfo"):
            cores = set()
            phys = core = None
            with open("/proc/cpuinfo") as f:
                for line in f:
                    k, _, v = line.partition(":")
                    k, v = k.strip(), v.strip()
                    if k == "model name" and not name.strip():
                        name = v
                    elif k == "physical id":
                        phys = v
                    elif k == "core id":
                        core = v
                    elif not k and phys is not None:
                        cores.add((phys, core))
                        phys = core = None
            if phys is not None:
                cores.add((phys, core))
            physical = len(cores)
    except Exception:
        pass
    return name, physical or max(1, logical // 2), logical


_INTEGRATED = re.compile(r"\b(UHD|Iris|HD Graphics|Radeon\(TM\) Graphics|Radeon Graphics|Vega \d+ Graphics|"
                         r"Radeon \d{3}M|Arc\(TM\) Graphics|Adreno|Mali|llvmpipe)\b", re.I)


def _gpu_devices(exe=None):
    """Graphics devices llama-server can use: [{'name', 'total', 'free', 'integrated'}] (bytes).
    Asks the bundled llama-server itself (--list-devices), so it lists exactly what it will see."""
    exe = exe or engine_exe()
    if not exe:
        return []
    try:
        out = subprocess.run([exe, "--list-devices"], capture_output=True, text=True, errors="replace",
                             timeout=60, cwd=os.path.dirname(exe))
        text = (out.stdout or "") + "\n" + (out.stderr or "")
    except Exception:
        return []
    gpus = []
    for m in re.finditer(r"^\s*([A-Za-z]+\d+):\s*(.+?)\s*\((\d+)\s*MiB,\s*(\d+)\s*MiB free\)", text, re.M):
        name = m.group(2).strip()
        gpus.append({"id": m.group(1), "name": name, "total": int(m.group(3)) * 1024 ** 2,
                     "free": int(m.group(4)) * 1024 ** 2, "integrated": bool(_INTEGRATED.search(name))})
    return gpus


def _cuda_available():
    """Whether the speech engine can use an NVIDIA card (without importing PyTorch here: slow)."""
    if not shutil.which("nvidia-smi"):
        return False
    try:
        spec = importlib.util.find_spec("torch")
        if spec is None or not spec.origin:
            return False
        lib = os.path.join(os.path.dirname(spec.origin), "lib")
        return any("cudart" in f.lower() or f.lower().startswith("cudnn") for f in os.listdir(lib))
    except Exception:
        return False


def detect_hardware(refresh=False):
    """What this computer has, for sizing the AI and the speech model. Cached in hardware.json (the
    checks take a few seconds); refresh=True looks again. Free memory is always read fresh."""
    total, avail = _ram_bytes()
    hw = {} if refresh else _read_json(HARDWARE_PATH)
    if not hw.get("cpu_logical") or hw.get("ram_total") != total or hw.get("engine") != bool(engine_exe()):
        name, physical, logical = _cpu_info()
        hw = {"ram_total": total, "cpu_name": name, "cpu_physical": physical, "cpu_logical": logical,
              "gpus": _gpu_devices(), "cuda": _cuda_available(), "engine": bool(engine_exe()),
              "checked": datetime.now().isoformat(timespec="seconds")}
        try:
            os.makedirs(LOCAL_DIR, exist_ok=True)
            _atomic_json(HARDWARE_PATH, hw)
        except OSError:
            pass
    hw["ram_free"] = avail
    return hw


def hardware_cached():
    """The last hardware check, without running a new one (for screens that redraw often)."""
    hw = _read_json(HARDWARE_PATH)
    return hw if hw.get("cpu_logical") else {"ram_total": _ram_bytes()[0], "gpus": []}


def best_gpu(hw):
    """The graphics device to run the AI on: a dedicated card if there is one, else integrated."""
    gpus = [g for g in hw.get("gpus") or [] if g.get("total")]
    if not gpus:
        return None
    return sorted(gpus, key=lambda g: (not g.get("integrated"), g.get("free") or 0))[-1]


def hardware_summary(hw):
    bits = [f"{hw.get('ram_total', 0) / GB:.0f} GB memory"]
    if hw.get("cpu_name"):
        bits.append(f"{hw['cpu_name']} ({hw.get('cpu_physical')} cores)")
    g = best_gpu(hw)
    if g:
        kind = "integrated graphics" if g.get("integrated") else f"{g['total'] / GB:.0f} GB graphics card"
        bits.append(f"{g['name']} ({kind})")
    else:
        bits.append("no graphics acceleration found")
    return ", ".join(bits)


# ---- model files ------------------------------------------------------------ #
def _gguf_meta(path, want):
    """The metadata values named in `want` from a GGUF file's header (stops reading once it has them)."""
    scalar = {0: "<B", 1: "<b", 2: "<H", 3: "<h", 4: "<I", 5: "<i", 6: "<f", 7: "<?", 10: "<Q", 11: "<q", 12: "<d"}
    got = {}
    with open(path, "rb") as f:
        if f.read(4) != b"GGUF":
            raise ValueError("not a GGUF file")
        version = struct.unpack("<I", f.read(4))[0]
        if version < 2:
            raise ValueError("GGUF version 1 isn't supported")
        _tensors, nkv = struct.unpack("<QQ", f.read(16))

        def rstr():
            n = struct.unpack("<Q", f.read(8))[0]
            return f.read(n).decode("utf-8", errors="replace")

        def rval(t):
            if t in scalar:
                fmt = scalar[t]
                return struct.unpack(fmt, f.read(struct.calcsize(fmt)))[0]
            if t == 8:
                return rstr()
            if t == 9:
                it, n = struct.unpack("<IQ", f.read(12))
                if it in scalar and n > 64:                 # long numeric arrays: skip over them
                    f.seek(n * struct.calcsize(scalar[it]), 1)
                    return None
                if it == 8 and n > 64:                      # e.g. the tokenizer's vocabulary
                    for _ in range(n):
                        f.seek(struct.unpack("<Q", f.read(8))[0], 1)
                    return None
                return [rval(it) for _ in range(n)]
            raise ValueError(f"unknown GGUF value type {t}")
        for _ in range(nkv):
            key = rstr()
            t = struct.unpack("<I", f.read(4))[0]
            val = rval(t)
            if key in want or key == "general.architecture":
                got[key] = val
                if key == "general.architecture":
                    want = set(w.replace("{arch}", val) for w in want)
                if "general.architecture" in got and all(w in got for w in want):
                    break
    return got


_GGUF_CACHE = {}


def gguf_info(path):
    try:
        key = (path, os.path.getmtime(path))
    except OSError:
        return {}
    if key not in _GGUF_CACHE:
        _GGUF_CACHE[key] = _gguf_info(path)
    return dict(_GGUF_CACHE[key])


def _gguf_info(path):
    """{'layers', 'ctx_train', 'kv_bytes_per_token', 'arch'} for a model file ({} if unreadable).
    The memory a context of N tokens needs is about N × kv_bytes_per_token (16-bit cache)."""
    want = {"general.architecture", "{arch}.block_count", "{arch}.context_length", "{arch}.embedding_length",
            "{arch}.attention.head_count", "{arch}.attention.head_count_kv", "{arch}.attention.key_length",
            "{arch}.attention.value_length"}
    try:
        meta = _gguf_meta(path, want)
    except (OSError, ValueError, struct.error):
        return {}
    arch = meta.get("general.architecture") or ""

    def g(name, default=0):
        v = meta.get(f"{arch}.{name}", default)
        if isinstance(v, list):
            v = max((x for x in v if isinstance(x, (int, float))), default=default)
        return v or default
    layers, heads = int(g("block_count")), int(g("attention.head_count", 1))
    kv_heads = int(g("attention.head_count_kv", heads))
    head_dim = int(g("embedding_length")) // max(heads, 1)
    k_len, v_len = int(g("attention.key_length", head_dim)), int(g("attention.value_length", head_dim))
    return {"arch": arch, "layers": layers, "ctx_train": int(g("context_length")),
            "kv_bytes_per_token": layers * kv_heads * (k_len + v_len) * 2}


def model_files():
    """Every AI model (GGUF) this computer has: the installer's models\\llm and the local app folder's
    models\\ (drop more files there). Split models count once, by their first part."""
    seen, out = set(), []
    for d in LLM_DIRS:
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for fn in names:
            low = fn.lower()
            if not low.endswith(".gguf") or "mmproj" in low:
                continue
            m = _SHARD.search(fn)
            if m and int(m.group(1)) != 1:
                continue
            path = os.path.join(d, fn)
            parts = [path]
            if m:
                stem = fn[:m.start()]
                parts = [os.path.join(d, f"{stem}-{i:05d}-of-{m.group(2)}.gguf") for i in range(1, int(m.group(2)) + 1)]
                if not all(os.path.isfile(p) for p in parts):
                    continue                             # incomplete download: leave it out
            name = _SHARD.sub("", fn)
            name = name[:-5] if name.lower().endswith(".gguf") else name
            if name.lower() in seen:
                continue
            seen.add(name.lower())
            out.append({"name": name, "path": path, "bytes": sum(os.path.getsize(p) for p in parts),
                        "bundled": d == LLM_DIRS[0]})
    return out


def find_model(name):
    name = (name or "").strip().lower()
    return next((m for m in model_files() if m["name"].lower() == name), None)


# ---- fitting a model to this computer -------------------------------------- #
OVERHEAD = int(0.8 * GB)        # llama-server's own buffers, beyond the weights and the context cache
CONTEXTS = (16384, 12288, 8192)


def plan_model(model, hw, ctx_wanted=16384):
    """How to run `model` here: {'fit': 'good'|'slow'|'no', 'ctx', 'gpu_layers', 'need', 'why'}.
    Memory needed ≈ the file + the context cache + a little overhead. On a dedicated card as much as fits
    goes on the card and the rest stays in memory; integrated graphics share the computer's memory, so
    there it's about whether the computer has room."""
    info = gguf_info(model["path"]) if os.path.isfile(model.get("path") or "") else {}
    layers = info.get("layers") or 40
    per_tok = info.get("kv_bytes_per_token") or 160 * 1024
    ctx_cap = info.get("ctx_train") or 32768
    ram = hw.get("ram_total") or 8 * GB
    gpu = best_gpu(hw)
    dedicated = gpu is not None and not gpu.get("integrated")
    room_ram = ram - 3 * GB                       # Windows and the app itself keep a few GB
    vram = (gpu.get("free") or gpu.get("total") or 0) if dedicated else 0
    weights = model.get("bytes") or 0
    for ctx in [c for c in CONTEXTS if c <= max(ctx_wanted, CONTEXTS[-1])]:
        ctx = min(ctx, ctx_cap)
        need = weights + per_tok * ctx + OVERHEAD
        if need <= room_ram + vram * 0.9:
            break
    else:
        return {"fit": "no", "ctx": CONTEXTS[-1], "gpu_layers": 0, "need": need,
                "why": f"needs about {need / GB:.0f} GB of memory; this computer has {ram / GB:.0f} GB"}
    if dedicated:
        usable = vram * 0.9 - per_tok * ctx - OVERHEAD
        n = layers if usable >= weights else max(0, int(layers * usable / max(weights, 1)))
        on_card = n / max(layers, 1)
        fit = "good" if on_card >= 0.999 else "slow"
        why = ("runs entirely on the graphics card" if fit == "good" else
               f"{on_card:.0%} on the graphics card, the rest on the processor")
    else:
        # Integrated graphics (or none): the model runs from the computer's memory either way. Offloading
        # layers lets the integrated GPU (Vulkan) help with reading the transcript — as many as the share
        # of memory the graphics driver offers will hold.
        n = 0
        if gpu is not None:
            usable = (gpu.get("free") or gpu.get("total") or 0) * 0.9 - per_tok * ctx - OVERHEAD
            n = layers if usable >= weights else max(0, int(layers * usable / max(weights, 1)))
        share = need / max(ram, 1)
        fit = "good" if share <= 0.6 and weights <= 8 * GB else "slow"
        why = ((f"uses about {need / GB:.0f} of {ram / GB:.0f} GB memory"
                + ("" if fit == "good" else "; large for this computer, so expect slow note writing")))
        if gpu is not None:
            why += f"; {gpu['name']} helps"
    if ctx < ctx_wanted:
        why += f"; context shortened to {ctx // 1024}K to fit"
    return {"fit": fit, "ctx": ctx, "gpu_layers": n, "need": need, "why": why}


FIT_LABEL = {"good": "Fits well", "slow": "Slow here", "no": "Won't fit"}


def recommend_whisper(hw, cached):
    """(speech model, batch size, threads) for this computer from the models it has."""
    cuda = hw.get("cuda")
    ram = (hw.get("ram_total") or 8 * GB) / GB
    cores = hw.get("cpu_physical") or 4
    order = (["large-v3-turbo", "large-v3", "medium.en", "small.en"] if cuda or (ram >= 12 and cores >= 6)
             else ["medium.en", "small.en", "large-v3-turbo", "large-v3"] if ram >= 8 else
             ["small.en", "medium.en", "large-v3-turbo", "large-v3"])
    model = next((m for m in order if m in cached), None)
    batch = 16 if cuda else (8 if ram >= 16 else 4)
    return model, batch, max(1, min(cores, 16))


def auto_tune(cfg, refresh=False):
    """Fit the settings to this computer: the AI model (the installer's choice if it fits, otherwise the
    best one that does), its context and graphics offload, and the speech model. Runs on the first start
    of an installer build and from Settings › Check this computer again. Returns a summary line."""
    hw = detect_hardware(refresh)
    stamp = f"{hw.get('ram_total')}|{[g.get('name') for g in hw.get('gpus') or []]}|{len(model_files())}"
    if not refresh and cfg.get("tuned_for") == stamp:
        return None
    changes = []
    if ai_engine(cfg) == "builtin":
        models = model_files()
        bundle = BUNDLE.get("default_model") or ""
        current = find_model(cfg.get("model")) or find_model(bundle)
        plans = {m["name"]: plan_model(m, hw) for m in models}
        rank = {"good": 0, "slow": 1, "no": 2}
        pick = current if current and plans[current["name"]]["fit"] != "no" else None
        if pick is None and models:                         # largest model that still runs well, else fits
            pick = sorted(models, key=lambda m: (rank[plans[m["name"]]["fit"]], -m["bytes"]))[0]
        if pick:
            p = plans[pick["name"]]
            cfg.update(model=pick["name"], lm_context=p["ctx"], gpu_layers=p["gpu_layers"])
            changes.append(f"AI: {pick['name']} ({FIT_LABEL[p['fit']].lower()}: {p['why']})")
    wm, batch, threads = recommend_whisper(hw, cached_whisper_models())
    if wm:
        cfg.update(whisper_model=wm, batch_size=batch, whisper_threads=threads)
        changes.append(f"speech: {wm}")
    cfg["tuned_for"] = stamp
    save_config(cfg)
    return f"This computer: {hardware_summary(hw)}. " + ("Using " + "; ".join(changes) + "." if changes else "")


# ---- running llama-server ------------------------------------------------- #
class LocalEngine:
    """Starts, watches and stops the bundled llama-server. One model at a time; asking for another
    model (or other settings) restarts it. The server listens on 127.0.0.1 only."""

    def __init__(self):
        self.proc = None
        self.key = None
        self.port = None
        self.alias = None
        self.lock = threading.RLock()
        self.log_path = os.path.join(LOCAL_DIR, "logs", "ai-engine.log")
        self._job = None

    @property
    def base_url(self):
        return f"http://127.0.0.1:{self.port}/v1"

    def running(self):
        return self.proc is not None and self.proc.poll() is None

    def _free_port(self):
        s = socket.socket()
        try:
            s.bind(("127.0.0.1", 0))
            return s.getsockname()[1]
        finally:
            s.close()

    def _tie_to_app(self, p):
        """Windows: put the server in a job that closes with the app, so a crash never leaves it holding
        memory. (Elsewhere, stop() runs when the app exits.)"""
        if not IS_WIN:
            return
        try:
            import ctypes
            from ctypes import wintypes
            k32 = ctypes.windll.kernel32
            if self._job is None:
                job = k32.CreateJobObjectW(None, None)

                class BASIC(ctypes.Structure):
                    _fields_ = [("PerProcessUserTimeLimit", ctypes.c_int64), ("PerJobUserTimeLimit", ctypes.c_int64),
                                ("LimitFlags", wintypes.DWORD), ("MinimumWorkingSetSize", ctypes.c_size_t),
                                ("MaximumWorkingSetSize", ctypes.c_size_t), ("ActiveProcessLimit", wintypes.DWORD),
                                ("Affinity", ctypes.c_size_t), ("PriorityClass", wintypes.DWORD),
                                ("SchedulingClass", wintypes.DWORD)]

                class IOC(ctypes.Structure):
                    _fields_ = [(n, ctypes.c_uint64) for n in ("r", "w", "o", "rb", "wb", "ob")]

                class EXT(ctypes.Structure):
                    _fields_ = [("BasicLimitInformation", BASIC), ("IoInfo", IOC),
                                ("ProcessMemoryLimit", ctypes.c_size_t), ("JobMemoryLimit", ctypes.c_size_t),
                                ("PeakProcessMemoryUsed", ctypes.c_size_t), ("PeakJobMemoryUsed", ctypes.c_size_t)]
                info = EXT()
                info.BasicLimitInformation.LimitFlags = 0x2000          # KILL_ON_JOB_CLOSE
                k32.SetInformationJobObject(job, 9, ctypes.byref(info), ctypes.sizeof(info))
                self._job = job
            handle = k32.OpenProcess(0x0001 | 0x0100, False, p.pid)      # TERMINATE | SET_QUOTA
            k32.AssignProcessToJobObject(self._job, handle)
            k32.CloseHandle(handle)
        except Exception:
            pass

    def log_tail(self, n=4000):
        try:
            with open(self.log_path, encoding="utf-8", errors="replace") as f:
                return f.read()[-n:]
        except OSError:
            return ""

    def ensure(self, cfg, model_name=None):
        try:
            return self._ensure(cfg, model_name)
        except RuntimeError as e:
            ngl = cfg.get("gpu_layers")
            if not ngl or "stopped while loading" not in str(e):
                raise
            # Some graphics drivers can't run it: carry on with the processor only, and remember that.
            cfg["gpu_layers"] = 0
            _quiet(save_config, cfg)
            return self._ensure(cfg, model_name)

    def _ensure(self, cfg, model_name=None):
        """Make sure the server runs the chosen model with this computer's settings; returns the model's
        name (what the server answers to). Waits while the model loads (a minute or more for a big one)."""
        exe = engine_exe()
        if not exe:
            raise RuntimeError("The built-in AI isn't installed in this copy of Session Scribe.")
        model = find_model(model_name or cfg.get("model")) or (model_files() or [None])[0]
        if model is None:
            raise RuntimeError("No AI model found. Put a .gguf model file in " + LLM_DIRS[1] + " or reinstall.")
        ctx = int(cfg.get("lm_context") or 16384)
        ngl = cfg.get("gpu_layers")
        ngl = 0 if ngl in (None, "") else int(ngl)
        key = (model["path"], ctx, ngl)
        with self.lock:
            if self.running() and self.key == key:
                return self.alias
            self.stop()
            os.makedirs(os.path.dirname(self.log_path), exist_ok=True)
            self.port = self._free_port()
            self.alias = model["name"]
            cmd = [exe, "-m", model["path"], "--host", "127.0.0.1", "--port", str(self.port),
                   "-c", str(ctx), "-ngl", str(ngl), "--parallel", "1", "--alias", self.alias, "--jinja"]
            log = open(self.log_path, "w", encoding="utf-8", errors="replace")
            log.write(" ".join(cmd) + "\n")
            log.flush()
            kw = {"start_new_session": True} if not IS_WIN else {}
            self.proc = subprocess.Popen(cmd, stdout=log, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL,
                                         cwd=os.path.dirname(exe), **kw)
            log.close()
            self._tie_to_app(self.proc)
            self.key = key
            deadline = time.time() + 1800
            while True:
                if self.proc.poll() is not None:
                    tail = self.log_tail(1500)
                    self.proc, self.key = None, None
                    hint = (" It may not have enough memory for this model — pick a smaller one in Settings."
                            if re.search(r"alloc|memory|out of", tail, re.I) else "")
                    raise RuntimeError(f"The built-in AI stopped while loading {model['name']}.{hint}\n\n"
                                       + tail.strip()[-600:])
                try:
                    with _NO_PROXY.open(f"http://127.0.0.1:{self.port}/health", timeout=2) as r:
                        if r.status == 200:
                            break
                except Exception:
                    pass
                if time.time() > deadline:
                    self.stop()
                    raise RuntimeError(f"The built-in AI took too long to load {model['name']}.")
                try:
                    check_cancelled()
                except Cancelled:
                    self.stop()
                    raise
                time.sleep(0.5)
            return self.alias

    def stop(self):
        with self.lock:
            p, self.proc, self.key = self.proc, None, None
            if p is None or p.poll() is not None:
                return
            try:
                p.terminate()
                p.wait(timeout=10)
            except Exception:
                _quiet(p.kill)

    def make_room(self, cfg):
        """Before transcribing: if this computer can't hold the AI model and the speech models at once,
        unload the AI (it starts again by itself for the notes)."""
        if not self.running():
            return
        hw = detect_hardware()
        if (hw.get("ram_free") or 0) < 6 * GB:
            self.stop()


ENGINE = LocalEngine()


# --------------------------------------------------------------------------- #
# Local LLM (LM Studio or the built-in AI)
# --------------------------------------------------------------------------- #
def assert_local_url(url):
    if not _is_local_host(urllib.parse.urlparse(url).hostname):
        raise NetworkBlocked("The AI server address must be on this computer "
                             "(localhost or 127.0.0.1).")


_NO_PROXY = urllib.request.build_opener(urllib.request.ProxyHandler({}))


def _http_json(url, body=None, timeout=30):
    assert_local_url(url)
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(url, data=data, headers={"Content-Type": "application/json"})
    try:
        with _NO_PROXY.open(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", errors="replace")[:300]
        raise RuntimeError(f"LM Studio returned an error ({e.code}): {detail}") from None
    except (urllib.error.URLError, ConnectionError, socket.timeout) as e:
        err = RuntimeError("Couldn't reach LM Studio. Open LM Studio, load a model, and start the "
                           f"local server (Developer tab). Details: {e}")
        # not running at all (vs. a connection dropped part-way, e.g. by the computer sleeping)
        err.refused = isinstance(e, ConnectionRefusedError) or isinstance(getattr(e, "reason", None),
                                                                          ConnectionRefusedError)
        raise err from None


def list_models(cfg, timeout=30):
    if ai_engine(cfg) == "builtin":
        return [m["name"] for m in model_files()]
    data = _http_json(cfg["lmstudio_url"].rstrip("/") + "/models", timeout=timeout)
    return [m.get("id") for m in data.get("data", []) if m.get("id")]


_LM_LOADED = {"key": None, "at": 0.0}


def ensure_model_loaded(cfg, model):
    """If the chosen model isn't loaded in LM Studio, load it with Session Scribe's settings (context length,
    one request slot, flash attention) instead of letting LM Studio load it on demand with its defaults —
    those (several request slots) made reading long transcripts about 3× slower on a laptop GPU.
    Quietly does nothing on LM Studio versions without the /api/v1 endpoints."""
    if ai_engine(cfg) == "builtin":
        return ENGINE.ensure(cfg, model)
    if not model:
        return
    base = cfg["lmstudio_url"].rstrip("/")
    root = base[:-3] if base.endswith("/v1") else base
    key = (root, model)
    if _LM_LOADED["key"] == key and time.time() - _LM_LOADED["at"] < 60:
        return
    try:
        models = _http_json(root + "/api/v1/models", timeout=5).get("models") or []
    except Exception:
        return
    entry = next((m for m in models if model in (m.get("key"), *(m.get("variants") or []))), None)
    if entry is None:
        return                                   # not a model LM Studio knows by that name: let it report that
    if not entry.get("loaded_instances"):
        try:
            _http_json(root + "/api/v1/models/load",
                       {"model": entry.get("key") or model, "context_length": int(cfg.get("lm_context") or 16384),
                        "parallel": max(1, int(cfg.get("lm_parallel") or 1)), "flash_attention": True},
                       timeout=900)
        except RuntimeError as e:
            if "Couldn't reach" in str(e):
                raise
            pass                                 # fall back to LM Studio's own on-demand loading
    _LM_LOADED.update(key=key, at=time.time())


LLM_RETRY_WAITS = (5, 15, 30)      # seconds before trying LM Studio again after a dropped connection


def llm_chat(cfg, prompt, on_progress=None, expected=1500, system=None, on_text=None, temperature=0.2,
             on_eta=None):
    """Ask the local model (see _llm_chat_once). If the connection to LM Studio drops part-way — most
    often because the computer went to sleep — the request is sent again after a short wait instead of
    failing; finished steps of the notes are kept by the caller, so only this step is redone."""
    _SleepWatch.start()
    keep_awake(True)
    try:
        for i, wait in enumerate(LLM_RETRY_WAITS + (None,)):
            started = time.time()
            try:
                return _llm_chat_once(cfg, prompt, on_progress, expected, system, on_text, temperature, on_eta)
            except RuntimeError as e:
                if wait is None or not str(e).startswith("Couldn't reach"):
                    raise
                if getattr(e, "refused", False) and not _SleepWatch.slept_since(started - 120):
                    raise                 # LM Studio simply isn't running: say so now, don't make you wait
            end = time.time() + wait
            while time.time() < end:                      # (stops at once if cancelled)
                check_cancelled()
                time.sleep(0.25)
    finally:
        keep_awake(False)


def _llm_chat_once(cfg, prompt, on_progress=None, expected=1500, system=None, on_text=None, temperature=0.2,
                   on_eta=None):
    """Ask the local model. Streams the reply so on_progress(fraction 0..1) can
    drive a progress bar; `expected` is the rough length (characters) of a
    typical answer, used to estimate the fraction while it's being written.
    If the task is cancelled, the connection is cut at once and LM Studio stops writing."""
    import http.client
    check_cancelled()
    builtin = ai_engine(cfg) == "builtin"
    who = "The built-in AI" if builtin else "LM Studio"
    if builtin:
        model = ENGINE.ensure(cfg)                       # starts it (or switches model) when needed
        base = ENGINE.base_url
    else:
        model = cfg.get("model") or (list_models(cfg) or [None])[0]
        if not model:
            raise RuntimeError("LM Studio is running but no model is loaded.")
        if cfg.get("model"):
            ensure_model_loaded(cfg, model)
        base = cfg["lmstudio_url"]
    url = base.rstrip("/") + "/chat/completions"
    assert_local_url(url)
    body = {"model": model, "temperature": temperature, "stream": True,
            "messages": [{"role": "system", "content": system or SYSTEM_PROMPT},
                         {"role": "user", "content": prompt}]}
    text, thinking, finish = "", 0, None
    report_f = on_progress or (lambda f: None)
    eta_out = on_eta or set_eta
    # Learned speed of this model on this computer: how long reading the prompt and writing the answer take.
    rates = timing_llm(model)
    prompt_chars = len(prompt) + len(system or SYSTEM_PROMPT)
    pre_est = prompt_chars / max(rates["prefill"], 1.0)
    gen_est = max(expected, 1) / max(rates["gen"], 0.1)
    share = pre_est / (pre_est + gen_est)
    clock = {"sent": None, "first": None, "chars": 0, "stop": False}

    def report(f, eta):
        eta_out(eta)
        report_f(f)

    def reading_prompt():                  # nothing streams back while LM Studio reads: fill by time
        while not clock["stop"]:
            time.sleep(0.5)
            if clock["stop"] or clock["first"] is not None or clock["sent"] is None:
                continue
            el = time.time() - clock["sent"]
            _quiet(report, share * min(0.95, el / max(pre_est, 0.1)), max(pre_est - el, 0.0) + gen_est)
    u = urllib.parse.urlparse(url)
    conn_cls = http.client.HTTPSConnection if u.scheme == "https" else http.client.HTTPConnection
    conn = conn_cls(u.hostname, u.port, timeout=1800)
    held = {}

    def cut():
        # shut the socket itself: the response keeps reading from it even after http.client
        # lets go of it, and shutdown() wakes a read that's waiting for LM Studio
        sock = held.get("sock") or getattr(conn, "sock", None)
        if sock is not None:
            _quiet(sock.shutdown, socket.SHUT_RDWR)
        _quiet(conn.close)
    forget = on_cancel(cut)
    try:
        conn.connect()
        held["sock"] = conn.sock
        check_cancelled()
        conn.request("POST", (u.path or "/") + (f"?{u.query}" if u.query else ""),
                     body=json.dumps(body).encode("utf-8"), headers={"Content-Type": "application/json"})
        clock["sent"] = time.time()
        threading.Thread(target=reading_prompt, daemon=True).start()
        r = conn.getresponse()
        if r.status >= 400:
            detail = r.read().decode("utf-8", errors="replace")[:300]
            raise RuntimeError(f"{who} returned an error ({r.status}): {detail}")
        if "event-stream" not in (r.getheader("Content-Type") or ""):
            data = json.loads(r.read().decode("utf-8"))      # server ignored streaming
            choice = data["choices"][0]
            text, finish = choice["message"]["content"] or "", choice.get("finish_reason")
        else:
            while True:
                raw = r.readline()
                check_cancelled()
                if not raw:
                    break
                line = raw.decode("utf-8", errors="replace").strip()
                if not line.startswith("data:"):
                    continue
                payload = line[5:].strip()
                if payload == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload)["choices"][0]
                except (ValueError, KeyError, IndexError):
                    continue
                delta = chunk.get("delta") or {}
                text += delta.get("content") or ""
                thinking += len(delta.get("reasoning_content") or delta.get("reasoning") or "")
                finish = chunk.get("finish_reason") or finish
                shown = re.sub(r"<think>.*?(</think>|$)", "", text, flags=re.S)
                visible = len(shown)
                if on_text is not None and delta.get("content"):
                    on_text(shown)
                now = time.time()
                if clock["first"] is None and (delta.get("content") or thinking):
                    clock["first"] = now
                clock["chars"] = len(text) + thinking
                # thinking counts a little, so the bar still moves for reasoning models
                g = min(0.97, (visible + 0.15 * (thinking + len(text) - visible)) / max(expected, 1))
                if clock["first"] is not None and now - clock["first"] > 1.5:
                    rate = clock["chars"] / (now - clock["first"])          # this answer's own pace
                else:
                    rate = rates["gen"]
                left = max(expected * 1.0 - visible, 0.03 * expected) / max(rate, 0.1)
                report(share + (1 - share) * g, left)
    except (Cancelled, RuntimeError, NetworkBlocked):
        raise
    except Exception as e:
        check_cancelled()                  # a read cut short by cancelling is a cancel, not an error
        if isinstance(e, (KeyError, IndexError, ValueError)):
            raise RuntimeError(f"{who} sent back an unexpected response.") from None
        if builtin:                        # it stopped part-way: the next try starts it again
            err = RuntimeError(f"Couldn't reach the built-in AI. Details: {e}\n\n{ENGINE.log_tail(600)}")
            err.refused = False
            raise err from None
        err = RuntimeError("Couldn't reach LM Studio. Open LM Studio, load a model, and start the "
                           f"local server (Developer tab). Details: {e}")
        # not running at all (vs. a connection dropped part-way, e.g. by the computer sleeping)
        err.refused = isinstance(e, ConnectionRefusedError) or isinstance(getattr(e, "reason", None),
                                                                          ConnectionRefusedError)
        raise err from None
    finally:
        clock["stop"] = True
        forget()
        _quiet(conn.close)
    report(1.0, 0.0)
    if clock["sent"] and clock["first"] and not _SleepWatch.slept_since(clock["sent"]):   # learn its speed
        _quiet(record_llm, model, prompt_chars, clock["first"] - clock["sent"], clock["chars"],
               time.time() - clock["first"])
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.S)
    text = re.sub(r"^\s*```[a-z]*\n|\n```\s*$", "", text.strip())
    if finish == "length":
        text += ("\n\n[VERIFY: the AI stopped early — output may be cut off. "
                 + ("Choose a model with more room in Settings, or lower “Condense transcripts over”.]" if builtin
                    else "Increase the context length in LM Studio.]"))
    return text.strip()


class _Steps:
    """Overall progress across several AI calls. Each step's share of the bar is how long it's expected to
    take on this computer: reading its prompt plus writing a document of the length that step usually
    produces (both learned). Time left covers the steps still to come."""

    def __init__(self, progress, plan, prompt_hint=8000):
        # plan: [(label, expected_chars)] or [(label, expected_chars, prompt_chars)]
        self.progress, self.rates = progress, timing_llm()
        self.labels = [p[0] for p in plan]
        self.out = [expected_out(p[0], p[1]) for p in plan]
        self.secs = [self._secs(p[2] if len(p) > 2 else prompt_hint, o) for p, o in zip(plan, self.out)]
        self.pct = 0.0

    def _secs(self, prompt_chars, out_chars):
        return prompt_chars / max(self.rates["prefill"], 1.0) + out_chars / max(self.rates["gen"], 0.1)

    def run(self, i, cfg, prompt):
        label = self.labels[i]
        self.secs[i] = self._secs(len(prompt), self.out[i])          # the real prompt is known now
        lo = self.pct
        hi = lo + (100.0 - lo) * self.secs[i] / (sum(self.secs[i:]) or 1.0)
        later = sum(self.secs[i + 1:])
        memo = getattr(_TASK, "memo", None)      # finished steps of a paused-then-resumed task
        key = hashlib.sha256((label + "\0" + prompt).encode("utf-8", "replace")).hexdigest()
        if memo is not None and key in memo:
            set_eta(later)
            self.progress(f"{label} — already done before the pause…", hi)
            self.pct = hi
            return memo[key]
        set_eta(self.secs[i] + later)
        self.progress(f"{label}…", lo)
        out = llm_chat(cfg, prompt, lambda f: self.progress(f"{label}…", lo + (hi - lo) * f),
                       expected=self.out[i], on_eta=lambda e: set_eta((e or 0) + later))
        record_out(label, len(out))
        if memo is not None:
            memo[key] = out
        self.pct = hi
        return out


def split_chunks(text, max_chars, sep="\n"):
    chunks, cur, size = [], [], 0
    for part in text.split(sep):
        if cur and size + len(part) + len(sep) > max_chars:
            chunks.append(sep.join(cur))
            cur, size = [], 0
        cur.append(part)
        size += len(part) + len(sep)
    if cur:
        chunks.append(sep.join(cur))
    return chunks


def session_label(meta):
    kind = "Intake" if meta.get("kind") == "intake" else CONTACT_NAMES[contact_with(meta)][2] if meta.get("kind") == "parent" else \
        (f"Session {meta['session_number']}" if meta.get("session_number") else "Session")
    return f"{kind} — {fmt_date(meta.get('session_date', '?'))}" + (" (imported)" if meta.get("source") == "imported" else "")


def group_by_date(sessions):
    """[(sid, data)] -> [(date, [(sid, data), ...])], oldest date first. Everything
    saved for the same date (generated session, imported notes…) shows as one entry.
    Within a date: generated before imported, intake before progress."""
    groups = {}
    for sid, d in sessions:
        groups.setdefault(d.get("meta", {}).get("session_date") or "undated", []).append((sid, d))

    def rec_key(x):
        m = x[1].get("meta", {})
        return (m.get("source") == "imported", m.get("kind") != "intake", m.get("created", ""))
    return [(day, sorted(recs, key=rec_key)) for day, recs in sorted(groups.items())]


def day_title(records):
    metas = [d.get("meta", {}) for _, d in records]
    if any(m.get("kind") == "intake" for m in metas):
        return "Intake"
    if metas and all(m.get("kind") == "parent" for m in metas):
        names = {CONTACT_NAMES[contact_with(m)][2] for m in metas}
        return names.pop() if len(names) == 1 else "Outside contacts"
    num = next((m.get("session_number") for m in metas if m.get("session_number")), "")
    return f"Session {num}" if num else "Session"


def record_docs(d):
    """[(tab label, key)] for one saved record."""
    m = d.get("meta", {})
    intake = m.get("kind") == "intake"
    if m.get("source") == "imported":
        return [("Imported intake" if intake else "Imported " + CONTACT_NAMES[contact_with(m)][2].lower()
                 if m.get("kind") == "parent" else "Imported note", "note")]
    labels = doc_labels(m)
    docs = [(labels[0], "note")]
    if d.get("overview", "").strip():
        docs.append((labels[1], "overview"))
    if d.get("transcript", "").strip():
        docs.append(("Messages" if m.get("source") == "messages" else "Transcript", "transcript"))
    return docs


def day_docs(records):
    """Every document for one date: [(label, key, sid, data)], labels made unique."""
    out, seen = [], {}
    for sid, d in records:
        for label, key in record_docs(d):
            seen[label] = seen.get(label, 0) + 1
            out.append((label if seen[label] == 1 else f"{label} ({seen[label]})", key, sid, d))
    return out


def search_patient(client, sessions, query, limit=300):
    """Search every document for one patient (case overview, notes, overviews,
    transcripts, intakes, imported notes). Case-insensitive; all words must appear.
    Returns [{"day", "label", "key", "sid", "count", "snippet"}], newest first."""
    words = [w for w in query.lower().split() if w]
    if not words:
        return []

    def check(text):
        low = (text or "").lower()
        if not all(w in low for w in words):
            return 0, ""
        count = sum(low.count(w) for w in words)
        i = low.find(words[0])
        a, b = max(0, i - 50), min(len(text), i + len(words[0]) + 70)
        snippet = ("…" if a else "") + re.sub(r"\s+", " ", text[a:b]).strip() + ("…" if b < len(text) else "")
        return count, snippet

    results = []
    case = (client.get("case_overview") or {}).get("text", "")
    n, snip = check(case)
    if n:
        results.append({"day": None, "label": "Case overview", "key": "case", "sid": None, "count": n,
                        "snippet": snip})
    plan = current_plan(client)
    if plan:
        n, snip = check(plan["text"])
        if n:
            results.append({"day": None, "label": "Treatment plan", "key": "plan", "sid": None, "count": n,
                            "snippet": snip})
    for day, records in reversed(group_by_date(sessions)):
        for label, key, sid, d in day_docs(records):
            n, snip = check(d.get(key, ""))
            if not n and words and all(w in day for w in words):          # searching a date finds that day
                n, snip = 1, (d.get(key, "") or "")[:110]
            if n:
                results.append({"day": day, "label": label, "key": key, "sid": sid, "count": n, "snippet": snip})
            if len(results) >= limit:
                return results
    return results


# --------------------------------------------------------------------------- #
# Treatment plans
# --------------------------------------------------------------------------- #
PLAN_SPLIT = re.compile(r"\n\s*-{3,}\s*\n(?=\s*NOTES FOR CLINICIAN)", re.I)


def current_plan(client):
    plans = client.get("treatment_plans") or []
    return plans[-1] if plans else None


NOTE_USED_RE = re.compile(r"(?im)^\s*therapeutic interventions used\s*:?\s*$")
NOTE_PLANNED_RE = re.compile(r"(?im)^\s*planned interventions\b[^\n]*$")


def note_sections(text):
    """A progress note's parts: (paragraph, interventions used, planned interventions).
    The lists are '' when the note doesn't have them (older or imported notes)."""
    text = text or ""
    u, pl = NOTE_USED_RE.search(text), NOTE_PLANNED_RE.search(text)
    cuts = sorted(m.start() for m in (u, pl) if m)
    body = text[:cuts[0]] if cuts else text

    def part(m):
        if not m:
            return ""
        nxt = [c for c in cuts if c > m.start()]
        return text[m.end():nxt[0] if nxt else len(text)].strip()
    return body.strip(), part(u), part(pl)


def plan_for_ehr(text):
    """The plan without the clinician-only notes at the end (what gets copied to the EHR)."""
    return PLAN_SPLIT.split(text or "", maxsplit=1)[0].strip()


def plan_goals(text):
    """'Goal 1: ...' lines from a plan, for the patient profile's treatment goals."""
    return [m.group(1).strip() for m in re.finditer(r"(?im)^\s*goal\s*\d+\s*[:.\-–]\s*(.+)$", plan_for_ehr(text))]


def plan_review_due(plan):
    try:
        start = datetime.fromisoformat(plan.get("created", "")[:19]).date()
        from datetime import timedelta
        return start + timedelta(days=int(plan.get("review_days") or 90))
    except (ValueError, TypeError):
        return None


def group_blocks(blocks, max_chars):
    """Split documentation blocks into groups that each fit the model (empty list if
    everything already fits)."""
    if len("\n\n".join(blocks)) <= max_chars:
        return []
    groups, cur = [], ""
    for b in blocks:
        if cur and len(cur) + len(b) > max_chars:
            groups.append(cur)
            cur = ""
        cur += ("\n\n" if cur else "") + b
    groups.append(cur)
    return groups


def plan_material(client, sessions, hide):
    """Everything a treatment plan should rest on, oldest first."""
    blocks = []
    prev = current_plan(client)
    if prev:
        blocks.append(f"=== PREVIOUS TREATMENT PLAN (version {prev['version']}, {prev.get('created', '')[:10]}) ===\n"
                      f"{hide(plan_for_ehr(prev['text']))}")
    case = (client.get("case_overview") or {}).get("text", "")
    if case:
        blocks.append(f"=== CASE OVERVIEW ===\n{hide(case)}")
    blocks += documents_blocks(client, hide)
    for day, records in group_by_date([(None, d) for d in sessions]):
        parts = []
        for label, key, _, d in day_docs(records):
            if key == "transcript" or not d.get(key, "").strip():
                continue
            if key == "overview" and d.get("meta", {}).get("kind") != "intake":
                continue                                   # progress notes carry the content
            parts.append(f"{label.upper()}:\n{hide(d[key]).strip()}")
        if parts:
            blocks.append(f"=== {day_title(records)} — {fmt_date(day)} ===\n" + "\n\n".join(parts))
    return blocks


def generate_treatment_plan(cfg, client, sessions, orientation, review_days, instructions, progress):
    hide = client_hider(client)
    blocks = plan_material(client, sessions, hide)
    groups = group_blocks(blocks, int(cfg.get("max_chars", 24000)))
    steps = _Steps(progress, [(f"Condensing the record, part {i} of {len(groups)}", 3500)
                              for i in range(1, len(groups) + 1)] + [("Writing the treatment plan", 5000)])
    if groups:
        material = "\n\n".join(steps.run(i, cfg, fill(NOTES_DIGEST_PROMPT, {"part": i + 1, "total": len(groups),
                                                                          "chunk": g}))
                                for i, g in enumerate(groups))
        kind = "condensed digests of this patient's documentation, oldest first"
    else:
        material = "\n\n".join(blocks)
        kind = "this patient's documentation, oldest first"
    out = steps.run(len(groups), cfg, fill(read_template("treatment_plan.txt"), {
        "client_code": client.get("code", ""), "orientation": orientation or "not specified",
        "background": hide(client.get("background", "")).strip() or "(not provided)",
        "goals": hide(client.get("goals", "")).strip() or "(not provided)",
        "review_days": review_days,
        "instructions": (f"\nCLINICIAN'S INSTRUCTIONS FOR THIS PLAN: {hide(instructions)}\n"
                         if instructions.strip() else ""),
        "source_kind": kind, "material": material or "(no documentation yet)"}))
    progress("Done.", 100)
    return out


def build_context(client, prior_sessions, n_prev, hide, same_day=None):
    """prior_sessions: oldest-first session dicts from EARLIER dates. same_day: other
    documentation already saved for this session's date (e.g. an imported note)."""
    case = client.get("case_overview") or {}
    case_txt = ""
    if case.get("text"):
        case_txt = (f"\nCASE OVERVIEW TO DATE (generated {case.get('generated', '')[:10]}):\n"
                    f"{hide(case['text'])}\n")
    intakes = [d for d in prior_sessions if d.get("meta", {}).get("kind") == "intake" and d.get("note", "").strip()]
    intake_txt = ""
    if intakes:
        d = intakes[-1]
        intake_txt = f"\nINTAKE ASSESSMENT ({session_label(d['meta'])}):\n{hide(d['note'])[:6000]}\n"
    notes = [d for d in prior_sessions if d.get("note", "").strip()
             and d.get("meta", {}).get("kind") not in ("intake", "parent")]
    recent = notes[-max(0, n_prev):] if n_prev else []
    parents = [d for d in prior_sessions if d.get("meta", {}).get("kind") == "parent" and d.get("note", "").strip()]
    parent_txt = ("\nRECENT CONTACTS OUTSIDE SESSIONS — with the patient, a parent/guardian or others (oldest first):\n" + "\n\n".join(
        f"{session_label(d['meta'])}:\n{hide(d['note'])[:2500]}" for d in parents[-2:]) + "\n") if parents else ""
    if recent:
        prev = "\nPREVIOUS SESSION NOTES (oldest first):\n" + "\n\n".join(
            f"{session_label(d['meta'])}:\n{hide(d['note'])}" for d in recent)
    elif not prior_sessions:
        prev = "\nThis is the first documented session for this patient.\n"
    else:
        prev = ""
    used = ([session_label(intakes[-1]["meta"])] if intakes else []) + [session_label(d["meta"]) for d in recent]
    same = [d for d in (same_day or []) if d.get("note", "").strip()]
    if same:
        prev += ("\nOTHER DOCUMENTATION ALREADY ON FILE FOR THIS SAME DATE (likely the clinician's own record of "
                 "this session). Keep the new draft consistent with it; if they conflict, flag it with [VERIFY]:\n"
                 + "\n\n".join(f"{session_label(d['meta'])}:\n{hide(d['note'])[:4000]}" for d in same) + "\n")
        used += [session_label(d["meta"]) + " (same date)" for d in same]
    if case_txt:
        used.append("case overview")
    plan = current_plan(client)
    plan_txt = ""
    if plan:
        plan_txt = (f"\nCURRENT TREATMENT PLAN (version {plan['version']}, {plan.get('created', '')[:10]}) — relate "
                    f"progress to these goals:\n{hide(plan_for_ehr(plan['text']))[:5000]}\n")
        used.append(f"treatment plan v{plan['version']}")
    hw = homework_text(client)
    if hw:
        parent_txt += "\nHOMEWORK ASSIGNED EARLIER (if this session followed it up, say how it went):\n" + hw + "\n"
        used = used + ["open homework"]
    meas = measures_text(client)
    if meas:
        parent_txt += "\nOUTCOME MEASURES (latest scores; mention them in the note only where relevant):\n" + meas + "\n"
        used = used + ["PHQ-9/GAD-7 scores"]
    return fill(CONTEXT_HEADER, {"background": hide(client.get("background", "").strip()) or "(not provided)",
                                 "plan": plan_txt,
                                 "intake": intake_txt, "case": case_txt, "previous": prev + parent_txt}), \
        used + [session_label(d["meta"]) for d in parents[-2:]]


def generate_documents(cfg, values, transcript, context, progress, kind="progress", reference=None,
                       instructions="", which=("first", "second")):
    """Returns (first, second): progress -> (note, overview); intake -> (assessment, questionnaire).
    `which` limits what's written (the other comes back as None); `instructions` are the
    clinician's directions for this draft."""
    max_chars = int(cfg.get("max_chars", 24000))
    chunks = split_chunks(transcript, max_chars) if len(transcript) > max_chars else []
    if kind == "intake":
        tail = [("Writing the intake assessment", 4000), ("Filling in the 13-section intake questionnaire", 5000)]
    elif kind == "parent":
        tail = [("Writing the contact note", 1200), ("Writing the conversation summary", 2500)]
    else:
        tail = [("Writing the progress note", 1000), ("Writing the session overview", 3500)]
    tail = [t for t, name in zip(tail, ("first", "second")) if name in which]
    # how much each step has to read, roughly — so the first estimate already reflects a long session
    final_read = len(context) + (3000 * len(chunks) if chunks else len(transcript)) + 6000
    steps = _Steps(progress, [(f"Long session — condensing part {i} of {len(chunks)}", 3000, len(c) + 1500)
                              for i, c in enumerate(chunks, 1)] + [(lbl, w, final_read) for lbl, w in tail])
    if chunks:
        digests = []
        for i, chunk in enumerate(chunks, 1):
            digests.append(steps.run(i - 1, cfg, fill(DIGEST_PROMPT, {"part": i, "total": len(chunks),
                                                                       "chunk": chunk})))
        source = "\n\n".join(f"--- Part {i} of {len(digests)} ---\n{d}"
                             for i, d in enumerate(digests, 1))
        kind_txt = ("a detailed, time-stamped digest of the session (the full transcript was too long "
                    "to include in one pass)")
    else:
        source, kind_txt = transcript, ("the full transcript of the conversation with "
                                        + values.get("contact_party", "the patient's parent or guardian")
                                        if kind == "parent" else "the full session transcript")
    if values.get("source_kind") and not chunks:          # e.g. "the parent's text messages, in order"
        kind_txt = values["source_kind"]
    v = dict(values, transcript=source, source_kind=kind_txt)
    v.setdefault("contact_method", "Conversation (recorded)")
    if kind == "parent":
        for k, val in contact_values(values.get("contact_with") or "parent", values.get("contact_who", "")).items():
            v.setdefault(k, val)
    style = style_block(reference, kind)
    prefs = style_notes_block(values.get("style_notes"))
    lead = context + prefs + ("\n\n" + style if style else "") + "\n\n"
    extra = (f"\n\nCLINICIAN'S INSTRUCTIONS FOR THIS DRAFT (follow them, as long as the transcript supports "
             f"it):\n{instructions.strip()}" if instructions.strip() else "")
    n = len(chunks)
    t1, t2 = {"intake": ("intake_assessment.txt", "intake_questionnaire.txt"),
              "parent": ("parent_note.txt", "parent_summary.txt")}.get(kind, ("session_note.txt", "overview.txt"))
    first = second = None
    if "first" in which:
        first = steps.run(n, cfg, lead + fill(read_template(t1), v) + extra)
        n += 1
    if "second" in which:
        second = steps.run(n, cfg, context + prefs + "\n\n" + fill(read_template(t2), v) + extra)
    progress("Done.", 100)
    return first, second



# --------------------------------------------------------------------------- #
# Session review: the session map (computed here), skills feedback and techniques used (local AI)
# --------------------------------------------------------------------------- #
_NEG_WORDS = set("""sad sadness unhappy hopeless helpless worthless useless anxious anxiety nervous worried worry worrying
scared afraid fear fearful terrified panic panicked angry anger mad furious rage frustrated frustrating annoyed
upset hurt hurting pain painful cry cried crying tears lonely alone isolated empty numb tired exhausted drained
stressed stress overwhelmed overwhelming depressed depression miserable awful terrible horrible hate hated guilty
guilt ashamed shame embarrassed jealous resent resentful bitter rejected abandoned betrayed disappointed
disappointing struggle struggling struggled hard difficult worse worst failing failed failure lost confused
insecure irritable restless trapped stuck broken grief grieving dead die dying death kill suicide suicidal cut
cutting harm hurtful abuse abused yelled yelling screamed fight fighting argument argued""".split())
_POS_WORDS = set("""happy happier happiness glad good great better best proud pride calm calmer relaxed relief relieved
hope hopeful excited exciting fun enjoy enjoyed enjoying love loved loving grateful thankful safe secure confident
peaceful content comfortable optimistic motivated strong stronger progress improved improving accomplished
connected supported supportive understood laugh laughed laughing smile smiled nice wonderful amazing excellent
fine okay ok""".split())
_NEGATORS = {"not", "no", "never", "don't", "dont", "didn't", "didnt", "isn't", "isnt", "wasn't", "wasnt", "can't",
             "cant", "won't", "wont", "nothing", "hardly"}
_OPEN_Q = ("what", "how", "why", "tell", "describe", "explain", "walk", "help me", "in what", "where do", "say more",
           "talk about", "share")
_CLOSED_Q = ("do", "did", "does", "is", "are", "was", "were", "can", "could", "will", "would", "have", "has", "had",
             "should", "any", "anything", "is there", "are there", "who", "when", "which")


def _tone_of(text):
    """(score -1..1, negative words, positive words) for a stretch of speech (a simple word list, no AI)."""
    words = re.findall(r"[a-z']+", (text or "").lower())
    neg = pos = 0
    for i, w in enumerate(words):
        flipped = any(x in _NEGATORS for x in words[max(0, i - 2):i])
        if w in _NEG_WORDS:
            pos, neg = (pos + 1, neg) if flipped else (pos, neg + 1)
        elif w in _POS_WORDS:
            pos, neg = (pos, neg + 1) if flipped else (pos + 1, neg)
    return (pos - neg) / (pos + neg + 1.0), neg, pos


def question_kind(sentence):
    s = sentence.strip().lower().lstrip("\"'([ ")
    s = re.sub(r"^(so|and|but|okay|ok|well|um|uh|now|like)[, ]+", "", s)
    if any(s.startswith(p) for p in _OPEN_Q):
        return "open"
    if any(s.startswith(p + " ") or s == p for p in _CLOSED_Q):
        return "closed"
    return "other"


def _same_label(a, b):
    return bool(a) and bool(b) and a.strip().lower() == b.strip().lower()


_CLINICIAN_WORDS = ("clinician", "counselor", "counsellor", "therapist", "interviewer", "provider", "extern",
                    "intern", "trainee", "social worker", "psychologist")
_PATIENT_WORDS = ("patient", "client")
_NOT_PATIENT_WORDS = ("other", "parent", "guardian", "mother", "father", "mom", "dad", "caregiver", "teacher",
                      "sibling", "partner", "spouse")


def map_patient(speakers, counselor_label, patient_label=None):
    """Which speaker in this transcript is the patient: the one labelled as the patient (Settings → speaker
    labels, or simply "Patient"/"Client"); otherwise, when the counselor can be told (your label, or e.g.
    "Therapist"/"Clinician"), whoever else talked most — never a parent, "Other", or an unlabelled speaker.
    None when it can't be told, so no one else's tone is shown by mistake."""
    names = [s["label"] for s in speakers]           # most talk first
    low = lambda n: (n or "").strip().lower()
    for n in names:
        if _same_label(n, patient_label):
            return n
    for n in names:
        if low(n) in _PATIENT_WORDS:
            return n
    is_counselor = lambda n: _same_label(n, counselor_label) or any(w in low(n) for w in _CLINICIAN_WORDS)
    if not any(is_counselor(n) for n in names):
        return None
    for n in names:
        if is_counselor(n) or any(w in low(n) for w in _NOT_PATIENT_WORDS) or re.match(r"(?i)speaker[ _]?\d+$", n):
            continue
        return n
    return None


_TS = r"((?:\d{1,2}:)?\d{1,2}:\d{2})(?:[.,]\d+)?"
_TS_FIRST = re.compile(r"^\s*[\[(]?" + _TS + r"[\])]?\s*[-–—]?\s*([^:\[\]()]{1,40}?)\s*:\s*(.*)$")   # [00:01:23] Patient: …
_TS_AFTER = re.compile(r"^\s*([^:\[\]()\d][^:\[\]()]{0,39}?)\s*[\[(]" + _TS + r"[\])]\s*:?\s*(.*)$")  # Patient (00:01:23): …


def _ts_secs(ts):
    secs = 0
    for part in ts.split(":"):
        secs = secs * 60 + int(part)
    return float(secs)


def lines_from_transcript(text):
    """Timed lines read back from a transcript's own timestamps — for sessions saved without the
    transcription's timings (pasted or imported transcripts, older sessions). Each line lasts until the next
    one starts, so pauses count as talk; [] when the text has fewer than two timestamped lines or the times
    run backwards."""
    out = []
    for raw in (text or "").splitlines():
        m = _TS_FIRST.match(raw)
        if m:
            ts, who, said = m.groups()
        else:
            m = _TS_AFTER.match(raw)
            if m:
                who, ts, said = m.groups()
        if m:
            out.append({"start": _ts_secs(ts), "speaker": who.strip(), "text": said.strip()})
        elif out and raw.strip():
            out[-1]["text"] = (out[-1]["text"] + " " + raw.strip()).strip()   # a line that wrapped
    if len(out) < 2:
        return []
    for a, b in zip(out, out[1:]):
        if b["start"] < a["start"]:
            return []
        a["end"] = b["start"]
    out[-1]["end"] = out[-1]["start"] + max(2.0, len(out[-1]["text"].split()) / 2.5)
    return [dict(l, approx=True) for l in out if l["text"]]


def timed_lines(d):
    """A session's transcript lines with start and end times: the transcription's own when it has them,
    else read from the timestamps in the transcript text."""
    lines = [l for l in d.get("lines") or [] if l.get("start") is not None]
    if lines and all(l.get("end") is not None for l in lines):
        return d["lines"]
    if lines:                                       # starts only: each line ends where the next begins
        lines = sorted((dict(l) for l in lines), key=lambda l: float(l["start"]))
        for a, b in zip(lines, lines[1:]):
            if a.get("end") is None:
                a["end"] = b["start"]
        if lines[-1].get("end") is None:
            lines[-1]["end"] = float(lines[-1]["start"]) + max(2.0, len((lines[-1].get("text") or "").split()) / 2.5)
        return lines
    return lines_from_transcript(d.get("transcript") or "")


def session_map(lines, roles, counselor_label, window=120.0, patient_label=None):
    """Who talked when, how much, and how the patient's words felt over the session — computed on this
    computer from the transcript (no AI). Tone and the heaviest moments follow the patient's speech only (never
    the counselor's or a third person's). Returns None when there's no timed transcript."""
    lines = [l for l in lines or [] if l.get("end") is not None and l.get("start") is not None
             and (l.get("text") or "").strip()]
    if not lines:
        return None
    label = lambda l: roles.get(l["speaker"], l["speaker"])
    dur = max(float(l["end"]) for l in lines)
    per = {}
    for l in lines:
        sp = per.setdefault(label(l), {"label": label(l), "secs": 0.0, "turns": 0, "longest": 0.0, "words": 0})
        d = max(0.0, float(l["end"]) - float(l["start"]))
        sp["secs"] += d
        sp["turns"] += 1
        sp["longest"] = max(sp["longest"], d)
        sp["words"] += len(l["text"].split())
    talk = sum(s["secs"] for s in per.values()) or 1.0
    speakers = sorted(per.values(), key=lambda s: -s["secs"])
    for s in speakers:
        s["pct"] = round(100 * s["secs"] / talk)
        s["avg_turn"] = s["secs"] / max(s["turns"], 1)
    patient = map_patient(speakers, counselor_label, patient_label)
    tone, heavy = [], []
    n_win = max(1, int(math.ceil(dur / window)))
    for k in range(n_win):
        a, b = k * window, (k + 1) * window
        said = [l for l in lines if patient and label(l) == patient and a <= float(l["start"]) < b]
        text = " ".join(l["text"] for l in said)
        score, neg, pos = _tone_of(text)
        tone.append({"t": min(b, dur) - (min(b, dur) - a) / 2, "score": round(score, 3), "neg": neg, "pos": pos,
                     "words": len(text.split())})
        if neg >= 2 and score < -0.2:
            best = max(said, key=lambda l: _tone_of(l["text"])[1])
            heavy.append({"t": float(best["start"]), "neg": neg, "quote": best["text"].strip()[:160]})
    heavy = sorted(sorted(heavy, key=lambda h: -h["neg"])[:3], key=lambda h: h["t"])
    q = {"open": 0, "closed": 0, "other": 0}
    for l in lines:
        if _same_label(label(l), counselor_label) or (not any(_same_label(x["label"], counselor_label) for x in speakers)
                                                       and any(w in label(l).lower() for w in _CLINICIAN_WORDS)):
            for sent in re.findall(r"[^.?!]*\?", l["text"]):
                q[question_kind(sent)] += 1
    gaps = sum(max(0.0, float(b["start"]) - float(a["end"])) for a, b in zip(lines, lines[1:]))
    approx = any(l.get("approx") for l in lines)      # timings read from the transcript's timestamps
    return {"duration": dur, "approx": approx, "speakers": speakers, "counselor": counselor_label, "patient": patient,
            "timeline": [(float(l["start"]), float(l["end"]), label(l)) for l in lines],
            "tone": tone, "heavy": heavy, "questions": dict(q, total=sum(q.values())),
            "silence_pct": round(100 * gaps / dur) if dur else 0}


def session_map_text(m):
    """The map's numbers in words (for the page, and for the AI's skills feedback)."""
    if not m:
        return ""
    out = [f"Length {fmt_ts(m['duration'])}. Talk time: " + ", ".join(
        f"{s['label']} {s['pct']}% ({s['turns']} turns, longest {round(s['longest'])} s)" for s in m["speakers"])
        + ("" if m.get("approx") else f". Pauses between turns: {m['silence_pct']}% of the session.")]
    q = m["questions"]
    if q["total"]:
        out.append(f"{m['counselor']}'s questions: {q['total']} — {q['open']} open, {q['closed']} closed"
                   + (f", {q['other']} other" if q["other"] else "") + ".")
    if m["heavy"]:
        out.append("Heaviest moments (most distress words): " + "; ".join(
            f"[{fmt_ts(h['t'])}] “{h['quote']}”" for h in m["heavy"]) + ".")
    return "\n".join(out)


REVIEW_FEEDBACK_PROMPT = """You are an experienced, warm clinical supervisor reviewing a session recorded by a \
counseling trainee (the "{counselor}" in the transcript; the other speaker is the "{patient}"). The trainee's \
theoretical orientation: {orientation}. Write feedback the trainee can learn from, like good supervision notes.

Use these plain-text headings, in this order:

WHAT WENT WELL
2-4 specific moments that worked. For each: the timestamp, the trainee's exact words in quotes, and one sentence \
on why it helped.

MISSED OPPORTUNITIES
2-5 moments where a reflection of feeling or meaning, a follow-up question, a summary or a pause could have \
deepened the work. For each: the timestamp, what the {patient} said (exact quote), what the trainee did instead, \
and one example of what could have been said.

WHERE THE {patient_upper} PULLED BACK
Moments the {patient} seemed to disengage: shorter answers, changing the subject, deflecting with humor, \
"I don't know", contradicting. For each: the timestamp, the quote, and a hypothesis (label it as one) about what \
happened just before. Write "None noticed" if there were none.

ONE THING TO PRACTICE NEXT SESSION
One concrete, specific skill, with an example of how it might sound with this {patient}.

Rules: quote only words that are actually in the transcript, with their [mm:ss] timestamps. Keep placeholders \
such as [Patient] exactly as written. Be specific, supportive and honest — no generic praise. Don't diagnose. \
If risk or safety came up, note in one line whether it was explored and documented.

Numbers measured from the recording (who talked how much, the trainee's questions):
{map}

Below is {part}.

{transcript}"""

REVIEW_TECHNIQUES_PROMPT = """Identify the therapeutic techniques and counselor skills the {counselor} (a \
counseling trainee; orientation: {orientation}) actually used in this session transcript. Use the agency's \
own terms where they fit:
{vocabulary}

Write one line per technique, most significant first, at most 10, each exactly like this:
- <technique> — [mm:ss] "<the {counselor}'s exact words>" — <a short phrase on how it was used>

Only list a technique with clear evidence in the transcript; quote exactly. Then, after one blank line:

For the note: <one sentence in the agency's note style naming the 2-3 main interventions, for example \
"Person centered therapy was used to ...; Counselor utilized reflection of feeling and validation ...">

Below is {part}.

{transcript}"""


def review_transcript(d, roles=None):
    """The transcript with timestamps and role names (what the review reads)."""
    roles = roles if roles is not None else d.get("roles") or {}
    if d.get("lines"):
        return render_transcript(d["lines"], roles)
    return d.get("transcript", "")


def generate_session_review(cfg, client, d, counselor, patient, orientation, reference, progress,
                            which=("feedback", "techniques")):
    """{"feedback": text, "techniques": text} for one recorded session. Names are hidden first; a long
    session is read in parts (each part's feedback is kept, labelled)."""
    hide = client_hider(client)
    transcript = hide(review_transcript(d))
    smap = session_map(timed_lines(d), d.get("roles") or {}, counselor, patient_label=patient)
    max_chars = int(cfg.get("max_chars", 24000))
    parts = split_chunks(transcript, max_chars) if len(transcript) > max_chars else [transcript]
    vocab = (reference or {}).get("vocabulary") or BUILTIN_REFERENCE.get("vocabulary", "")
    plan = []
    for kind in which:
        for i, p in enumerate(parts, 1):
            name = "Writing skills feedback" if kind == "feedback" else "Finding the techniques used"
            plan.append((name + (f" (part {i} of {len(parts)})" if len(parts) > 1 else ""),
                         2600 if kind == "feedback" else 1400, len(p) + 2500))
    steps = _Steps(progress, plan)
    out, n = {}, 0
    for kind in which:
        texts = []
        for i, p in enumerate(parts, 1):
            part = ("the full session transcript" if len(parts) == 1 else
                    f"part {i} of {len(parts)} of the session transcript")
            v = {"counselor": counselor, "patient": patient or "patient", "patient_upper": (patient or "patient").upper(),
                 "orientation": orientation or "not specified", "map": session_map_text(smap) or "(not available)",
                 "vocabulary": vocab, "part": part, "transcript": p}
            t = steps.run(n, cfg, fill(REVIEW_FEEDBACK_PROMPT if kind == "feedback" else REVIEW_TECHNIQUES_PROMPT, v))
            n += 1
            texts.append((f"— Part {i} of {len(parts)} —\n" if len(parts) > 1 else "") + t.strip())
        out[kind] = "\n\n".join(texts)
    progress("Done.", 100)
    return out



# --------------------------------------------------------------------------- #
# Supervision prep packet
# --------------------------------------------------------------------------- #
SUPERVISION_PATIENT_PROMPT = """Prepare a counseling trainee's notes for SUPERVISION about one patient ({code}), \
covering {start} to {end}. Use ONLY the documentation below; never invent facts. Keep placeholders such as \
[Patient] exactly as written. Plain text, with exactly these labels, each followed by 1-4 short lines \
starting with "- ":

This period:
(what the sessions and contacts covered, with dates)

Risk and safety:
(anything documented — suicidal or homicidal thoughts, self-harm, abuse, safety planning — and what was done; \
or "- Nothing documented")

Progress toward goals:
(movement on the treatment goals, or what's stalled)

Bring to supervision:
(1-3 specific questions the trainee could ask — clinical decisions, being stuck, the trainee's own reactions, \
ethics or next steps — written as questions)

The trainee's theoretical orientation: {orientation}
Treatment goals: {goals}

Documentation for this period (oldest first):
{docs}"""


def supervision_inputs(client, sessions, start, end):
    """The documentation one patient contributes to a supervision packet (names always hidden: it's shared)."""
    hide = client_hider(client, always=True)
    docs = []
    for sid, d in sessions:
        day = d.get("meta", {}).get("session_date") or ""
        if not (start <= day <= end):
            continue
        part = f"{session_label(d['meta'])}:\n{hide(d.get('note', ''))[:3500]}"
        fb = (d.get("review") or {}).get("feedback", "")
        if fb:
            part += "\n(Skills feedback on this session, for the trainee:)\n" + hide(fb)[:1500]
        docs.append(part)
    return docs


def practice_points(sessions, start, end):
    """'ONE THING TO PRACTICE' from each session review in the period: [(date, text)]."""
    out = []
    for _, d in sessions:
        day = d.get("meta", {}).get("session_date") or ""
        fb = (d.get("review") or {}).get("feedback", "")
        if start <= day <= end and fb:
            m = re.search(r"ONE THING TO PRACTICE[^\n]*\n+(.+?)(?:\n\s*\n|$)", fb, re.S)
            if m:
                out.append((day, re.sub(r"\s+", " ", m.group(1)).strip()))
    return out


def generate_supervision_packet(cfg, patients, start, end, questions, orientation, progress):
    """patients: [(client, sessions)]. Returns the packet text (plain text with CAPS headings)."""
    work = []
    for client, sessions in patients:
        docs = supervision_inputs(client, sessions, start, end)
        if docs:
            work.append((client, sessions, docs))
    steps = _Steps(progress, [(f"Preparing {c.get('code', '')}", 900, sum(len(x) for x in docs) + 1500)
                              for c, _, docs in work])
    sections, practice = [], []
    for i, (client, sessions, docs) in enumerate(work):
        hide = client_hider(client, always=True)
        text = steps.run(i, cfg, fill(SUPERVISION_PATIENT_PROMPT, {
            "code": client.get("code", ""), "start": fmt_date(start), "end": fmt_date(end),
            "orientation": orientation or "not specified", "goals": hide(client.get("goals", "")) or "(none listed)",
            "docs": "\n\n".join(docs)}))
        n = len(docs)
        sections.append(f"{client.get('code', '')} — {n} session{'s' if n != 1 else ''} or contact{'s' if n != 1 else ''}"
                        f"\n{text.strip()}")
        practice += [(client.get("code", ""), day, t) for day, t in practice_points(sessions, start, end)]
    head = (f"SUPERVISION PREP\n{fmt_date(start)} to {fmt_date(end)} · prepared "
            f"{fmt_date(date.today().isoformat())} · {len(work)} patient{'s' if len(work) != 1 else ''}")
    out = [head]
    if (questions or "").strip():
        out.append("WHAT I'D LIKE TO FOCUS ON\n" + "\n".join(("- " + q.strip().lstrip("-• ").strip())
                                                  for q in questions.splitlines() if q.strip()))
    if practice:
        out.append("SKILLS I'M WORKING ON (from my session reviews)\n" + "\n".join(
            f"- {code}, {fmt_date(day)}: {t}" for code, day, t in practice))
    out.append("PATIENTS\n\n" + ("\n\n".join(sections) if sections else "No sessions or contacts in this period."))
    progress("Done.", 100)
    return "\n\n".join(out)


def _capwords(s):
    import string
    return string.capwords(s)


def text_to_blocks(title, text):
    """Plain text with CAPS headings -> write_docx/write_pdf blocks."""
    blocks = [("title", title)]
    para = []

    def flush():
        if para:
            blocks.append(("p", "\n".join(para)))
            para.clear()
    for line in (text or "").splitlines():
        s_ = line.strip()
        if s_ and len(s_) <= 90 and s_.upper() == s_ and re.search(r"[A-Z]", s_) and not s_.startswith("-"):
            flush()
            blocks.append(("h1", _capwords(s_.lower()) if len(s_) > 3 else s_))   # "I'd", not "I'D"
        elif not s_:
            flush()
        else:
            para.append(line.rstrip())
    flush()
    return blocks



# --------------------------------------------------------------------------- #
# Goals check: which treatment goals each note addresses
# --------------------------------------------------------------------------- #
GOALS_STALE_AFTER = 3          # a goal not addressed in this many of the latest sessions is flagged


def llm_json(text):
    """The first JSON object in a model's reply ({} if there isn't a readable one)."""
    text = re.sub(r"<think>.*?</think>", "", text or "", flags=re.S)
    start = text.find("{")
    while start != -1:
        depth, in_str, esc = 0, False, False
        for i in range(start, len(text)):
            ch = text[i]
            if in_str:
                esc = (ch == "\\" and not esc)
                if ch == '"' and not esc:
                    in_str = False
                elif ch != "\\":
                    esc = False
                continue
            if ch == '"':
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    try:
                        val = json.loads(text[start:i + 1])
                        return val if isinstance(val, dict) else {}
                    except ValueError:
                        break
        start = text.find("{", start + 1)
    return {}


def patient_goals(client):
    """The goals notes are checked against: the current treatment plan's, else the profile's."""
    plan = current_plan(client)
    goals = plan_goals(plan["text"]) if plan else []
    if not goals:
        goals = [re.sub(r"^\s*(?:[-•*]|\d+[.)])\s*", "", g).strip() for g in (client.get("goals") or "").splitlines()]
    return [g for g in goals if g]


def goals_key(goals):
    return hashlib.sha256("\n".join(goals).encode("utf-8")).hexdigest()[:16]


GOALS_CHECK_PROMPT = """Below are a patient's treatment goals, numbered, and the documentation of one session \
or contact. For EACH goal, decide whether this documentation shows the goal was addressed — worked on, \
discussed, or progress or a setback reported. Be strict: a passing mention that isn't related to the goal \
doesn't count.

Reply with JSON only, one entry per goal number, exactly like:
{{"1": {{"addressed": true, "evidence": "at most 15 words from or about the note"}}, "2": {{"addressed": false, "evidence": ""}}}}

Goals:
{goals}

Documentation ({label}):
{note}"""


def goals_check_note(cfg, client, d, goals, steps, i):
    """[{goal, addressed, evidence}] for one saved record."""
    hide = client_hider(client)
    numbered = "\n".join(f"{n}. {hide(g)}" for n, g in enumerate(goals, 1))
    prompt = GOALS_CHECK_PROMPT.replace("{{", "{").replace("}}", "}")
    prompt = fill(prompt, {"goals": numbered, "label": session_label(d.get("meta", {})),
                           "note": hide(d.get("note", ""))[:6000]})
    ans = llm_json(steps.run(i, cfg, prompt))
    out = []
    for n, g in enumerate(goals, 1):
        a = ans.get(str(n)) or {}
        out.append({"goal": g, "addressed": bool(a.get("addressed")) if isinstance(a, dict) else False,
                    "evidence": (a.get("evidence") or "").strip()[:200] if isinstance(a, dict) else ""})
    return out


def goals_todo(client, sessions):
    """Saved records whose goals check is missing or out of date."""
    goals = patient_goals(client)
    if not goals:
        return goals, []
    key = goals_key(goals)
    return goals, [(sid, d) for sid, d in sessions if (d.get("note") or "").strip()
                   and (d.get("goals_check") or {}).get("key") != key]


def goals_summary(client, sessions, stale_after=GOALS_STALE_AFTER):
    """{goals, columns: [(date, sid, [bool|None per goal])], last: {goal: date}, stale: [(goal, n, since)]}."""
    goals = patient_goals(client)
    key = goals_key(goals) if goals else None
    cols = []
    for sid, d in sorted(sessions, key=lambda x: session_sort_key(x[1])):
        gc = d.get("goals_check") or {}
        if not (d.get("note") or "").strip():
            continue
        hits = [it["addressed"] for it in gc.get("items", [])] if gc.get("key") == key else [None] * len(goals)
        cols.append((d["meta"].get("session_date") or "", sid, hits))
    last, stale = {}, []
    checked = [c for c in cols if c[2] and c[2][0] is not None]
    for gi, g in enumerate(goals):
        dates = [day for day, _, hits in checked if gi < len(hits) and hits[gi]]
        last[g] = dates[-1] if dates else None
        run = 0
        for day, _, hits in reversed(checked):
            if gi < len(hits) and hits[gi]:
                break
            run += 1
        if run >= stale_after:
            stale.append((g, run, last[g]))
    return {"goals": goals, "columns": cols, "last": last, "stale": stale}



# --------------------------------------------------------------------------- #
# Risk timeline: every documented mention of suicidal or homicidal thoughts, self-harm, abuse or other
# safety concerns, with what was done
# --------------------------------------------------------------------------- #
RISK_VERSION = 1
RISK_RE = re.compile(
    r"\b(suicid\w*|kill(?:ing)? (?:my|him|her|them)sel(?:f|ves)|want(?:ed|s)? to die|wish(?:ed)? (?:i|he|she|they) "
    r"(?:was|were) dead|end (?:it|my life|things)|not (?:want|wanting) to (?:be here|live|wake up)|self[- ]?harm\w*|"
    r"cut(?:ting|s)? (?:my|him|her|them)sel(?:f|ves)|cutting|overdos\w*|hurt(?:ing)? (?:my|him|her|them)sel(?:f|ves)|"
    r"homicid\w*|hurt (?:someone|somebody|others|him|her|them)|weapons?|guns?|firearms?|abus\w*|molest\w*|"
    r"assault\w*|neglect\w*|hit(?:s|ting)? (?:me|him|her)|beat(?:s|ing)? (?:me|him|her)|threat\w*|"
    r"safety plan\w*|\bSI\b|\bHI\b|\bSIB\b|crisis|988|hospitali[sz]\w*|psych(?:iatric)? (?:er|emergency|eval\w*))", re.I)
RISK_TYPES = ["suicidal thoughts", "self-harm", "homicidal thoughts or violence", "abuse or neglect",
              "other safety concern", "screened — denied"]

RISK_PROMPT = """Read the documentation of one counseling session or contact and list every mention of risk or \
safety: suicidal thoughts, self-harm, homicidal thoughts or violence, abuse or neglect (of the patient or \
by the patient), or another safety concern. Also list a risk SCREENING where the patient DENIED these \
(for example "denied SI/HI"). Use only what's written; keep placeholders such as [Patient] exactly.

Reply with JSON only, exactly like:
{{"items": [{{"type": "one of: {types}", "summary": "what was said or observed, at most 25 words", \
"when": "the [mm:ss] timestamp if there is one, else \\"\\"", "action": "what the counselor did — assessed, \
safety plan made or reviewed, crisis line given, supervisor or guardian notified, referral — or \\"not documented\\""}}], \
"safety_plan": "created" or "reviewed" or "not mentioned"}}
If there is nothing about risk or safety at all, reply {{"items": [], "safety_plan": "not mentioned"}}.

Documentation ({label}):
{text}"""


def risk_source(d):
    """The parts of a record worth reading for risk: the note and overview in full, and the transcript lines
    that mention a risk word (with the line before and after)."""
    parts = []
    for key in ("note", "overview"):
        if (d.get(key) or "").strip():
            parts.append(f"[{key}]\n{d[key].strip()}")
    text = d.get("transcript") or ""
    keep = set()
    if RISK_RE.search(text):                  # most transcripts never mention risk: one quick pass, then done
        tl = text.splitlines()
        for i, ln in enumerate(tl):
            if RISK_RE.search(ln):
                keep.update({i - 1, i, i + 1})
    if keep:
        parts.append("[transcript excerpts]\n" + "\n".join(tl[i] for i in sorted(keep) if 0 <= i < len(tl)))
    return "\n\n".join(parts)


def risk_todo(sessions):
    """[(sid, d, source, key)] for records whose risk check is missing or out of date."""
    out = []
    for sid, d in sessions:
        src = risk_source(d)
        key = hashlib.sha256(f"{RISK_VERSION}\0{src}".encode("utf-8")).hexdigest()[:16]
        if (d.get("risk_check") or {}).get("key") != key:
            out.append((sid, d, src, key))
    return out


def risk_check_record(cfg, client, d, src, steps=None, i=0):
    """{"items": [...], "safety_plan": ...}; records that never mention a risk word skip the AI."""
    if not RISK_RE.search(src or ""):
        return {"items": [], "safety_plan": "not mentioned"}
    hide = client_hider(client)
    prompt = RISK_PROMPT.replace("{{", "{").replace("}}", "}")
    prompt = fill(prompt, {"types": " | ".join(RISK_TYPES), "label": session_label(d.get("meta", {})),
                           "text": hide(src)[:9000]})
    ans = llm_json(steps.run(i, cfg, prompt) if steps else llm_chat(cfg, prompt, expected=500))
    items = []
    for it in ans.get("items") or []:
        if not isinstance(it, dict) or not (it.get("summary") or "").strip():
            continue
        t = (it.get("type") or "other safety concern").strip().lower()
        t = next((x for x in RISK_TYPES if x.split()[0] in t), "other safety concern")
        items.append({"type": t, "summary": it["summary"].strip()[:300], "when": (it.get("when") or "").strip()[:12],
                      "action": (it.get("action") or "not documented").strip()[:300]})
    sp = (ans.get("safety_plan") or "not mentioned").strip().lower()
    return {"items": items, "safety_plan": sp if sp in ("created", "reviewed") else "not mentioned"}


def risk_summary(client, sessions, recent_days=30):
    """The timeline (newest first), the latest screening, safety-plan status and anything recent."""
    rows, screens, plans = [], [], []
    for sid, d in sessions:
        rc = d.get("risk_check") or {}
        day = d.get("meta", {}).get("session_date") or ""
        for it in rc.get("items") or []:
            row = dict(it, date=day, sid=sid, label=session_label(d.get("meta", {})))
            (screens if it["type"] == "screened — denied" else rows).append(row)
        if rc.get("safety_plan") in ("created", "reviewed"):
            plans.append((day, rc["safety_plan"]))
    rows.sort(key=lambda r: r["date"], reverse=True)
    screens.sort(key=lambda r: r["date"], reverse=True)
    plans.sort(reverse=True)
    files = [f_ for f_ in client.get("files") or [] if "safety" in (f_.get("name") or "").lower()]
    cutoff = (date.today() - timedelta(days=recent_days)).isoformat()
    recent = [r for r in rows if r["date"] >= cutoff]
    return {"rows": rows, "last_screen": screens[0] if screens else None, "plans": plans, "plan_files": files,
            "recent": recent, "needs_plan": bool(recent) and not plans and not files,
            "checked": sum(1 for _, d in sessions if d.get("risk_check"))}



# --------------------------------------------------------------------------- #
# Outcome measures: PHQ-9 (depression) and GAD-7 (anxiety)
# --------------------------------------------------------------------------- #
MEASURES = {
    "PHQ-9": {"items": 9, "max": 27, "bands": [(0, "minimal"), (5, "mild"), (10, "moderate"),
                                                (15, "moderately severe"), (20, "severe")],
              "questions": ["Little interest or pleasure in doing things", "Feeling down, depressed, or hopeless",
                            "Trouble falling or staying asleep, or sleeping too much", "Feeling tired or having little energy",
                            "Poor appetite or overeating", "Feeling bad about yourself", "Trouble concentrating",
                            "Moving or speaking slowly / being fidgety or restless",
                            "Thoughts that you would be better off dead, or of hurting yourself"]},
    "GAD-7": {"items": 7, "max": 21, "bands": [(0, "minimal"), (5, "mild"), (10, "moderate"), (15, "severe")],
              "questions": ["Feeling nervous, anxious, or on edge", "Not being able to stop or control worrying",
                            "Worrying too much about different things", "Trouble relaxing",
                            "Being so restless that it's hard to sit still", "Becoming easily annoyed or irritable",
                            "Feeling afraid as if something awful might happen"]},
}
MEASURE_CHANGE = 5            # a change of this many points is clinically meaningful (both scales)


def measure_band(kind, total):
    spec = MEASURES.get(kind)
    if not spec or total is None:
        return ""
    return [name for lo, name in spec["bands"] if total >= lo][-1]


def measure_entry(kind, day, total=None, items=None, source="manual", note=""):
    """A validated score entry (ValueError with a plain message if it doesn't add up)."""
    spec = MEASURES[kind]
    if items is not None:
        items = [int(x) for x in items]
        if len(items) != spec["items"] or any(x not in (0, 1, 2, 3) for x in items):
            raise ValueError(f"{kind} needs {spec['items']} answers, each 0-3.")
        if total is not None and int(total) != sum(items):
            raise ValueError(f"The {kind} answers add up to {sum(items)}, not {total}.")
        total = sum(items)
    if total is None:
        raise ValueError(f"Enter the {kind} total or its answers.")
    total = int(total)
    if not 0 <= total <= spec["max"]:
        raise ValueError(f"A {kind} total is between 0 and {spec['max']}.")
    if not re.fullmatch(r"\d{4}-\d\d-\d\d", day or ""):
        raise ValueError("Enter the date it was completed.")
    return {"id": uuid.uuid4().hex[:12], "kind": kind, "date": day, "total": total, "items": items,
            "source": source, "note": note, "added": datetime.now().isoformat(timespec="seconds")}


def measure_series(client, kind):
    return sorted((m for m in client.get("measures") or [] if m.get("kind") == kind),
                  key=lambda m: (m["date"], m.get("added", "")))


def measure_trend(client, kind):
    """{"latest", "previous", "first", "change", "worse", "better", "item9"} for one scale (None if no scores)."""
    s = measure_series(client, kind)
    if not s:
        return None
    last, prev = s[-1], (s[-2] if len(s) > 1 else None)
    ch = last["total"] - prev["total"] if prev else 0
    band_up = prev is not None and [b for _, b in MEASURES[kind]["bands"]].index(measure_band(kind, last["total"])) > \
        [b for _, b in MEASURES[kind]["bands"]].index(measure_band(kind, prev["total"]))
    return {"latest": last, "previous": prev, "first": s[0], "change": ch,
            "worse": prev is not None and (ch >= MEASURE_CHANGE or band_up),
            "better": prev is not None and ch <= -MEASURE_CHANGE,
            "item9": kind == "PHQ-9" and bool(last.get("items")) and last["items"][8] > 0}


def measures_text(client):
    """One line per scale for notes, the patient page and the AI's context (empty if no scores)."""
    out = []
    for kind in MEASURES:
        t = measure_trend(client, kind)
        if not t:
            continue
        l_ = t["latest"]
        line = f"{kind} {l_['total']} ({measure_band(kind, l_['total'])}) on {fmt_date(l_['date'])}"
        if t["previous"]:
            p_ = t["previous"]
            line += (f", {'up' if t['change'] > 0 else 'down' if t['change'] < 0 else 'no change'}"
                     + (f" {abs(t['change'])}" if t["change"] else "") + f" from {p_['total']} on {fmt_date(p_['date'])}")
        if t["item9"]:
            line += f"; item 9 (thoughts of being better off dead or self-harm) answered {l_['items'][8]}"
        out.append(line + ".")
    more = assessments_text(client)                   # the other questionnaires taken here (latest of each)
    if more:
        out.append(more)
    return "\n".join(out)




# --------------------------------------------------------------------------- #
# Assessment library: questionnaires the patient takes on this computer (full screen), scored here.
# Only free / public-domain instruments, worded as on their official forms (sources in each "credit").
# Proprietary tests (BDI-II, CDI-2, MMPI, WAIS…) can't be reproduced; their scores go in with
# "Add assessment…" instead.
# --------------------------------------------------------------------------- #
DEFAULT_DOC_TYPES = ["Psychological assessment", "Psychiatric evaluation", "Discharge summary",
                     "School / IEP records", "Medical records", "Letter or correspondence", "Other document"]


def documents_blocks(client, hide):
    """Imported documents (psychological assessments, records…) as material for the AI, oldest first."""
    out = []
    for d in sorted(client.get("documents") or [], key=lambda x: x.get("date", "")):
        if (d.get("text") or "").strip():
            out.append(f"=== {d.get('type', 'Document').upper()} — {fmt_date(d.get('date', ''))} (imported document"
                       + (f": {d['title']}" if d.get("title") else "") + f") ===\n"
                       + hide(strip_word_xml(d["text"])).strip())
    return out


ASSESS_GROUPS = [("child", "Children", "about 7–12"), ("adolescent", "Adolescents", "about 12–17"),
                 ("adult", "Adults", "18 and over")]
ASSESS_CATEGORIES = ["Depression", "Anxiety, stress & distress", "Trauma & PTSD", "Substance use", "ADHD",
                     "Behavior & functioning", "Suicide risk & safety"]

_FREQ4 = [(0, "Not at all"), (1, "Several days"), (2, "More than half the days"), (3, "Nearly every day")]
_DIFFICULT = [(0, "Not difficult at all"), (1, "Somewhat difficult"), (2, "Very difficult"), (3, "Extremely difficult")]
_YN = [(1, "Yes"), (0, "No")]
_BOTHER5 = [(0, "Not at all"), (1, "A little bit"), (2, "Moderately"), (3, "Quite a bit"), (4, "Extremely")]
_OFTEN5 = [(0, "Never"), (1, "Rarely"), (2, "Sometimes"), (3, "Often"), (4, "Very often")]
_NSO3 = [(0, "Never"), (1, "Sometimes"), (2, "Often")]


def _q(qid, text, opts=None, **kw):
    """One question: kind 'choice' (opts = [(score, label)]), 'number' (lo/hi) or 'text' (optional, unscored)."""
    d = {"id": str(qid), "text": text, "kind": kw.pop("kind", "choice" if opts is not None else "number")}
    if opts is not None:
        d["opts"] = opts
    d.update(kw)
    return d


def _band(v, bands):
    """bands = [(lowest score, label)] ascending; the label for v."""
    out = bands[0][1]
    for lo, name in bands:
        if v >= lo:
            out = name
    return out


def _val(a, qid, default=0):
    v = (a or {}).get(str(qid))
    return default if v is None or v == "" else v


def _label_of(inst, qid, value):
    q = next((x for x in inst["items"] if x["id"] == str(qid)), None)
    if not q or q["kind"] != "choice":
        return "" if value is None else str(value)
    return next((lbl for sc, lbl in q["opts"] if sc == value), str(value))


def assessment_visible(inst, answers):
    """The questions this patient is asked, in order (follows the instrument's skip rules)."""
    return [q for q in inst["items"] if not q.get("show") or q["show"](answers or {})]


# ---- scoring -----------------------------------------------------------------------------------------------
_PHQ_BANDS = [(0, "minimal"), (5, "mild"), (10, "moderate"), (15, "moderately severe"), (20, "severe")]


def _score_phq(a, adolescent=False):
    total = sum(int(_val(a, i)) for i in range(1, 10))
    band = _band(total, _PHQ_BANDS)
    flags, lines = [], [f"{total} of 27: {band} depressive symptoms."]
    if total >= 10:
        lines.append("10 or more: possible major depression — confirm with a clinical interview.")
    if int(_val(a, 9)) > 0:
        flags.append(f"Item 9 (thoughts of being better off dead or of hurting yourself) answered "
                     f"“{_FREQ4[int(_val(a, 9))][1]}”. Assess suicide risk today (ASQ or C-SSRS, then a brief "
                     "suicide safety assessment).")
    if adolescent:
        if int(_val(a, "month", 0)) == 1:
            flags.append("Answered YES: serious thoughts about ending their life in the past month.")
        if int(_val(a, "ever", 0)) == 1:
            flags.append("Answered YES: has tried to kill themselves or made a suicide attempt at some point.")
        if int(_val(a, "year", 0)) == 1:
            lines.append("Felt depressed or sad most days in the past year (possible persistent depressive symptoms).")
    if (a or {}).get("diff") not in (None, ""):
        lines.append(f"Effect on daily life: {_DIFFICULT[int(a['diff'])][1].lower()}.")
    return {"total": total, "max": 27, "band": band, "summary": f"{total}/27 ({band})", "lines": lines,
            "flags": flags, "risk": bool(flags), "values": {"Total": total}}


def _score_gad7(a):
    total = sum(int(_val(a, i)) for i in range(1, 8))
    band = _band(total, [(0, "minimal"), (5, "mild"), (10, "moderate"), (15, "severe")])
    lines = [f"{total} of 21: {band} anxiety symptoms."]
    if total >= 10:
        lines.append("10 or more: possible generalized anxiety disorder — confirm with a clinical interview.")
    if (a or {}).get("diff") not in (None, ""):
        lines.append(f"Effect on daily life: {_DIFFICULT[int(a['diff'])][1].lower()}.")
    return {"total": total, "max": 21, "band": band, "summary": f"{total}/21 ({band})", "lines": lines, "flags": [],
            "values": {"Total": total}}


_DASS_SCALES = {"Depression": ([3, 5, 10, 13, 16, 17, 21], [(0, "normal"), (10, "mild"), (14, "moderate"),
                                                              (21, "severe"), (28, "extremely severe")]),
                "Anxiety": ([2, 4, 7, 9, 15, 19, 20], [(0, "normal"), (8, "mild"), (10, "moderate"), (15, "severe"),
                                                       (20, "extremely severe")]),
                "Stress": ([1, 6, 8, 11, 12, 14, 18], [(0, "normal"), (15, "mild"), (19, "moderate"), (26, "severe"),
                                                       (34, "extremely severe")])}


def _score_dass(a):
    vals, parts, lines = {}, [], []
    for name, (items, bands) in _DASS_SCALES.items():
        v = 2 * sum(int(_val(a, i)) for i in items)               # ×2: DASS-21 on the DASS-42 scale
        vals[name] = v
        parts.append(f"{name[0]} {v} ({_band(v, bands)})")
        lines.append(f"{name}: {v} of 42 — {_band(v, bands)}.")
    lines.append("Scores are doubled to the full DASS scale. The DASS measures severity along each dimension; it "
                 "isn't a diagnosis.")
    worst = max(_band(vals[n], b).count("severe") for n, (_, b) in _DASS_SCALES.items())
    return {"total": None, "max": 42, "band": "", "summary": ", ".join(parts), "lines": lines, "flags": [],
            "values": vals, "worse_up": True, "_sev": worst}


def _score_k10(a):
    item = {i: (int(_val(a, i, 1)) if str(i) in (a or {}) else 1) for i in range(1, 11)}
    total = sum(item.values())
    band = _band(total, [(10, "likely to be well"), (20, "mild"), (25, "moderate"), (30, "severe")])
    k6 = sum(item[i] - 1 for i in (2, 4, 5, 8, 9, 10))
    lines = [f"{total} (10–50): " + ("likely to be well." if total < 20 else
                                    f"likely to have a {band} mental health disorder (primary care guide)."),
             f"K6 from the same answers: {k6} of 24" + (" — 13 or more suggests serious psychological distress."
                                                         if k6 >= 13 else ".")]
    return {"total": total, "max": 50, "band": band, "summary": f"{total}/50 ({band}); K6 {k6}", "lines": lines,
            "flags": [], "values": {"K10": total, "K6": k6}}


def _score_who5(a):
    raw = sum(int(_val(a, i)) for i in range(1, 6))
    pct = raw * 4
    low = [i for i in range(1, 6) if int(_val(a, i)) <= 1]
    poor = raw < 13 or low
    lines = [f"Raw score {raw} of 25 = {pct}% (higher is better well-being)."]
    if poor:
        lines.append("Below 13, or 0–1 on any item: poor well-being — screen for depression (e.g. PHQ-9).")
    lines.append("A 10-point change in the percentage score is a meaningful change.")
    return {"total": pct, "max": 100, "band": "poor well-being" if poor else "", "higher_better": True,
            "summary": f"{pct}% (raw {raw}/25)" + (" — poor well-being" if poor else ""), "lines": lines, "flags": [],
            "values": {"Well-being %": pct}}


def _score_pcl5(a):
    v = {i: int(_val(a, i)) for i in range(1, 21)}
    total = sum(v.values())
    clusters = {"Intrusion (B)": range(1, 6), "Avoidance (C)": range(6, 8), "Mood & cognition (D)": range(8, 15),
                "Arousal (E)": range(15, 21)}
    vals = {"Total": total}
    vals.update({k: sum(v[i] for i in r) for k, r in clusters.items()})
    n = {k: sum(1 for i in r if v[i] >= 2) for k, r in clusters.items()}       # 2 = "Moderately" or more
    dsm = n["Intrusion (B)"] >= 1 and n["Avoidance (C)"] >= 1 and n["Mood & cognition (D)"] >= 2 \
        and n["Arousal (E)"] >= 2
    probable = total >= 31
    lines = [f"Total {total} of 80. " + ("31–33 or more suggests probable PTSD (National Center for PTSD) — confirm "
                                          "with a clinical interview." if probable else "Below the usual cut-point "
                                                                                         "(31–33).")]
    lines.append("DSM-5 symptom pattern (items rated 2+: 1 B, 1 C, 2 D, 2 E): " + ("met" if dsm else "not met") + ".")
    lines += [f"{k}: {vals[k]}" for k in clusters]
    return {"total": total, "max": 80, "band": "probable PTSD" if probable else "below cut-point",
            "summary": f"{total}/80" + (" (probable PTSD)" if probable else ""), "lines": lines, "flags": [],
            "values": vals}


def _score_pcptsd5(a):
    if int(_val(a, "exp")) != 1:
        return {"total": 0, "max": 5, "band": "no trauma exposure reported", "summary": "0/5 (no exposure reported)",
                "lines": ["No traumatic event reported: screen total 0."], "flags": [], "values": {"Total": 0}}
    total = sum(int(_val(a, i)) for i in range(1, 6))
    pos = total >= 4
    lines = [f"{total} of 5 “yes”. " + ("Positive screen (cut-point 4): probable PTSD — further assessment, ideally "
                                       "a structured interview." if pos else "Below the cut-point of 4."),
             "VA guidance: for women a cut-point of 3 may be considered to avoid missed cases."]
    return {"total": total, "max": 5, "band": "positive" if pos else "negative",
            "summary": f"{total}/5 ({'positive' if pos else 'negative'})", "lines": lines, "flags": [],
            "values": {"Total": total}}


def _score_iesr(a):
    sub = {"Intrusion": [1, 2, 3, 6, 9, 14, 16, 20], "Avoidance": [5, 7, 8, 11, 12, 13, 17, 22],
           "Hyperarousal": [4, 10, 15, 18, 19, 21]}
    total = sum(int(_val(a, i)) for i in range(1, 23))
    vals = {"Total": total}
    lines = [f"Total {total} of 88. " + ("33 or more: best cut-point for probable PTSD." if total >= 33 else
                                         "24 or more: PTSD is a clinical concern." if total >= 24 else
                                         "Below 24.")]
    for k, items in sub.items():
        m = round(sum(int(_val(a, i)) for i in items) / len(items), 2)
        vals[k] = m
        lines.append(f"{k}: mean {m} (0–4)")
    lines.append("A screening measure, not a diagnosis.")
    band = "probable PTSD" if total >= 33 else "clinical concern" if total >= 24 else "below 24"
    return {"total": total, "max": 88, "band": band, "summary": f"{total}/88 ({band})", "lines": lines,
            "flags": [], "values": vals}


def _score_audit(a):
    v = {i: int(_val(a, i)) for i in range(1, 11)}
    total = sum(v.values())
    zone = _band(total, [(0, "Zone I: low risk"), (8, "Zone II: hazardous use"), (16, "Zone III: harmful use"),
                         (20, "Zone IV: possible dependence")])
    ac = v[1] + v[2] + v[3]
    lines = [f"Total {total} of 40 — {zone}.",
             {"Zone I: low risk": "Alcohol education.", "Zone II: hazardous use": "Simple advice.",
              "Zone III: harmful use": "Simple advice plus brief counseling and continued monitoring.",
              "Zone IV: possible dependence": "Referral to a specialist for diagnostic evaluation and treatment."}[zone]
             + " (WHO guidance)",
             f"AUDIT-C (questions 1–3): {ac} of 12 — positive at 4+ for men, 3+ for women."]
    flags = []
    if v[4] + v[5] + v[6] > 0:
        lines.append("Points on questions 4–6 suggest possible alcohol dependence.")
    return {"total": total, "max": 40, "band": zone.split(":")[0], "summary": f"{total}/40 ({zone})",
            "lines": lines, "flags": flags, "values": {"AUDIT": total, "AUDIT-C": ac}}


_ASRS_SOMETIMES = {1, 2, 3, 9, 12, 16, 18}            # shaded from "Sometimes"; the others from "Often"


def _score_asrs(a):
    v = {i: int(_val(a, i)) for i in range(1, 19)}
    hit = {i: v[i] >= (2 if i in _ASRS_SOMETIMES else 3) for i in v}
    part_a = sum(hit[i] for i in range(1, 7))
    part_b = sum(hit[i] for i in range(7, 19))
    inatt = sum(hit[i] for i in (1, 2, 3, 4, 7, 8, 9, 10, 11))
    hyper = sum(hit[i] for i in (5, 6, 12, 13, 14, 15, 16, 17, 18))
    pos = part_a >= 4
    lines = [f"Part A (screener): {part_a} of 6 in the shaded range — " +
             ("4 or more: symptoms highly consistent with ADHD in adults; further investigation warranted."
              if pos else "below the screener threshold of 4."),
             f"Part B: {part_b} of 12 in the shaded range (more detail for the clinical interview).",
             f"All 18: {inatt} of 9 inattentive and {hyper} of 9 hyperactive/impulsive symptoms in the shaded range."]
    return {"total": part_a, "max": 6, "band": "positive screen" if pos else "negative screen",
            "summary": f"Part A {part_a}/6 ({'positive' if pos else 'negative'}); Part B {part_b}/12", "lines": lines,
            "flags": [], "values": {"Part A": part_a, "Part B": part_b}}


_GDS_KEY = {1: 0, 2: 1, 3: 1, 4: 1, 5: 0, 6: 1, 7: 0, 8: 1, 9: 1, 10: 1, 11: 0, 12: 1, 13: 0, 14: 1, 15: 1}


def _score_gds(a):
    total = sum(1 for i, key in _GDS_KEY.items() if str(i) in (a or {}) and int(a[str(i)]) == key)
    band = "normal" if total <= 5 else "suggests depression" if total < 10 else "almost always depression"
    lines = [f"{total} of 15. " + ("Above 5 suggests depression; follow up with a clinical interview."
                                   if total > 5 else "5 or less: not suggestive of depression.")]
    if total >= 10:
        lines.append("10 or more almost always indicates depression.")
    return {"total": total, "max": 15, "band": band, "summary": f"{total}/15 ({band})", "lines": lines, "flags": [],
            "values": {"Total": total}}


def _score_bam(a):
    g = lambda i: int(_val(a, i))
    use = g(4) + g(5) + g(6)
    risk = g(1) + g(2) + g(3) + g(8) + g(11) + g(15)
    prot = g(9) + g(10) + g(12) + g(13) + g(14) + g(16)
    drugs = [lbl for qid, lbl in (("7a", "marijuana"), ("7b", "sedatives/tranquilizers"), ("7c", "cocaine/crack"),
                                  ("7d", "other stimulants"), ("7e", "opiates"), ("7f", "inhalants"),
                                  ("7g", "other drugs")) if g(qid) > 0]
    lines = [f"Use {use} (0–90), Risk {risk} (0–180), Protective {prot} (0–180).",
             "Lower Use and Risk and higher Protective are better; there are no cut-offs — compare with this "
             "patient's earlier BAMs and look at the items behind each score.",
             f"Days drinking: {g(4)}; heavy drinking: {g(5)}; drug use: {g(6)}" +
             (f" ({', '.join(drugs)})" if drugs else "") + "."]
    return {"total": use, "max": 90, "band": "", "summary": f"Use {use}, Risk {risk}, Protective {prot}",
            "lines": lines, "flags": [], "values": {"Use": use, "Risk": risk, "Protective": prot}}


def _score_asq(a):
    yes = [i for i in range(1, 5) if int(_val(a, i)) == 1]
    if not yes:
        return {"total": 0, "max": 1, "band": "negative", "summary": "Negative screen",
                "lines": ["No to questions 1–4: negative screen. Clinical judgment can always override a negative "
                          "screen."], "flags": [], "values": {}, "risk": False}
    acute = int(_val(a, 5)) == 1
    only_past = yes == [4]
    flags = [("ACUTE POSITIVE SCREEN — imminent risk: thoughts of killing themselves right now. Needs a STAT/urgent "
              "safety and full mental health evaluation; the patient can't leave until evaluated. Keep them in "
              "sight, remove dangerous objects, alert the clinician responsible.") if acute else
             ("Non-acute positive screen — potential risk. Needs a brief suicide safety assessment to decide whether "
              "(and when) a full mental health evaluation is needed.")]
    lines = [f"Yes to question{'s' if len(yes) > 1 else ''} {', '.join(map(str, yes))}."]
    if 4 in yes and (a or {}).get("4a") not in (None, ""):
        lines.append("Most recent attempt: " + ("within the last 12 months." if int(a["4a"]) == 1 else
                                                "over 1 year ago."))
    if only_past and not acute and int(_val(a, "4a", 1)) == 0:
        lines.append("Positive only because of a past attempt more than a year ago: for adults a brief suicide "
                     "safety assessment may not be necessary; for youth, only if one has been documented since "
                     "that attempt (NIMH).")
    lines.append("Give every patient: 988 Suicide & Crisis Lifeline (call or text 988) and Crisis Text Line "
                 "(text HOME to 741741).")
    return {"total": 2 if acute else 1, "max": 2, "band": "acute positive" if acute else "non-acute positive",
            "summary": "ACUTE positive screen" if acute else "Non-acute positive screen", "lines": lines,
            "flags": flags, "values": {}, "risk": True}


def _score_cssrs(a):
    y = lambda q: int(_val(a, q)) == 1
    recent6 = y(6) and int(_val(a, "6a")) == 1
    if y(4) or y(5) or recent6:
        level = "high"
    elif y(3) or y(6):
        level = "moderate"
    elif y(1) or y(2):
        level = "low"
    else:
        level = "none"
    said = [n for n, q in (("wish to be dead", 1), ("thoughts of killing themselves", 2), ("thinking about how", 3),
                           ("some intention of acting", 4), ("worked out details / intends to carry out a plan", 5),
                           ("suicidal behavior or preparation (lifetime)", 6)) if y(q)]
    flags = []
    if level == "high":
        flags.append("HIGH RISK on the C-SSRS screener (intent, a plan, or suicidal behavior in the past 3 months): "
                     "immediate safety evaluation and safety planning; don't leave the patient alone.")
    elif level == "moderate":
        flags.append("MODERATE RISK on the C-SSRS screener: complete a suicide safety assessment and safety plan; "
                     "consult your supervisor.")
    elif level == "low":
        flags.append("LOW RISK on the C-SSRS screener (passive or active ideation without method, intent or "
                     "plan): assess further and consider a safety plan and follow-up.")
    lines = [("Yes to: " + "; ".join(said) + ".") if said else "No to every question."]
    if y(6):
        lines.append("Behavior was " + ("within the past three months." if recent6 else "more than three months ago."))
    return {"total": {"none": 0, "low": 1, "moderate": 2, "high": 3}[level], "max": 3,
            "band": f"{level} risk" if level != "none" else "no ideation reported",
            "summary": f"{level.capitalize()} risk" if level != "none" else "No ideation or behavior reported",
            "lines": lines, "flags": flags, "values": {}, "risk": level != "none"}


_CRAFFT_SUD = {1: 32, 2: 64, 3: 79, 4: 92, 5: 100, 6: 100}


def _score_crafft(a):
    days = [int(_val(a, i)) for i in (1, 2, 3)]
    score = sum(1 for i in range(4, 10) if int(_val(a, i)) == 1)
    car = int(_val(a, 4)) == 1
    lines = [f"Past-year days: alcohol {days[0]}, marijuana {days[1]}, other drugs {days[2]}.",
             f"CRAFFT score {score} of 6" + (" — 2 or more suggests a serious problem and need for further "
                                              "assessment." if score >= 2 else ".")]
    if score:
        lines.append(f"About {_CRAFFT_SUD[score]}% of adolescents with this score have a DSM-5 substance use "
                     "disorder (Mitchell et al., 2014).")
    flags = ["CAR question answered YES: riding/driving risk counseling (Contract for Life, crafft.org/contract)."] \
        if car else []
    return {"total": score, "max": 6, "band": "positive" if score >= 2 else "negative",
            "summary": f"CRAFFT {score}/6" + (" (positive)" if score >= 2 else "") +
                       ("; no use reported" if not any(days) else ""),
            "lines": lines, "flags": flags, "values": {"CRAFFT score": score}}


_S2BI_SUBST = [("1", "nicotine/tobacco"), ("2", "alcohol"), ("3", "marijuana"), ("4", "prescription drugs not "
               "prescribed"), ("5", "illegal drugs"), ("6", "inhalants"), ("7", "herbs or synthetic drugs")]


def _score_s2bi(a):
    used = [(lbl, int(_val(a, q))) for q, lbl in _S2BI_SUBST if int(_val(a, q)) > 0]
    top = max([v for _, v in used], default=0)
    level = ["No reported use", "Lower risk (once or twice)", "Higher risk (monthly use)",
             "Highest risk (weekly or more)"][top]
    advice = ["Positive reinforcement; discourage all substance use.",
              "Brief advice: recommend not using at all.",
              "Monthly use: a substance use disorder is likely. Brief intervention, recommend cessation, and consider "
              "a referral.",
              "Weekly or more: a severe substance use disorder is likely. Brief intervention and referral to "
              "treatment."][top]
    freq = {1: "once or twice", 2: "monthly", 3: "weekly or more"}
    lines = [level + ".", advice]
    if used:
        lines.append("Past year: " + "; ".join(f"{lbl} {freq[v]}" for lbl, v in used) + ".")
    return {"total": top, "max": 3, "band": level, "summary": level, "lines": lines, "flags": [], "values": {}}


_SCARED_SUB = {"Panic/somatic": ([1, 6, 9, 12, 15, 18, 19, 22, 24, 27, 30, 34, 38], 7,
                                 "panic disorder or significant somatic symptoms"),
               "Generalized anxiety": ([5, 7, 14, 21, 23, 28, 33, 35, 37], 9, "generalized anxiety disorder"),
               "Separation anxiety": ([4, 8, 13, 16, 20, 25, 29, 31], 5, "separation anxiety disorder"),
               "Social anxiety": ([3, 10, 26, 32, 39, 40, 41], 8, "social anxiety disorder"),
               "School avoidance": ([2, 11, 17, 36], 3, "significant school avoidance")}


def _score_scared(a):
    total = sum(int(_val(a, i)) for i in range(1, 42))
    vals, lines = {"Total": total}, [f"Total {total} of 82. " + (
        "Above 30 is more specific for an anxiety disorder." if total > 30 else
        "25 or more may indicate an anxiety disorder." if total >= 25 else "Below 25.")]
    for name, (items, cut, what) in _SCARED_SUB.items():
        v = sum(int(_val(a, i)) for i in items)
        vals[name] = v
        lines.append(f"{name}: {v}" + (f" — {cut}+ may indicate {what}." if v >= cut else f" (cut-point {cut})."))
    band = "likely anxiety disorder" if total > 30 else "possible anxiety disorder" if total >= 25 else "below 25"
    return {"total": total, "max": 82, "band": band, "summary": f"{total}/82 ({band})", "lines": lines, "flags": [],
            "values": vals}


def _score_smfq(a):
    total = sum(int(_val(a, i)) for i in range(1, 14))
    pos = total >= 8
    lines = [f"{total} of 26. " + ("8 or more suggests possible depression — follow up with a clinical interview "
                                   "(some studies use a higher cut-point for teens)." if pos else "Below 8.")]
    if int(_val(a, 8)) == 2 or int(_val(a, 5)) == 2:
        lines.append("Strong self-criticism endorsed (“I hated myself” / “I felt I was no good anymore”).")
    return {"total": total, "max": 26, "band": "possible depression" if pos else "below cut-point",
            "summary": f"{total}/26" + (" (possible depression)" if pos else ""), "lines": lines, "flags": [],
            "values": {"Total": total}}


def _score_psc(a, youth=False):
    if youth:                     # Y-PSC-17 item order
        sub = {"Internalizing": [2, 6, 9, 11, 15], "Attention": [1, 3, 7, 13, 17],
               "Externalizing": [4, 5, 8, 10, 12, 14, 16]}
    else:
        sub = {"Internalizing": [1, 2, 3, 4, 5], "Attention": [6, 7, 8, 9, 10],
               "Externalizing": [11, 12, 13, 14, 15, 16, 17]}
    cuts = {"Internalizing": 5, "Attention": 7, "Externalizing": 7}
    total = sum(int(_val(a, i)) for i in range(1, 18))
    vals, lines = {"Total": total}, [f"Total {total} of 34" + (" — 15 or more: positive screen; further evaluation."
                                                                  if total >= 15 else " (cut-point 15).")]
    for k, items in sub.items():
        v = sum(int(_val(a, i)) for i in items)
        vals[k] = v
        lines.append(f"{k}: {v}" + (f" — positive ({cuts[k]}+)." if v >= cuts[k] else f" (cut-point {cuts[k]})."))
    if (a or {}).get("help") not in (None, "") and int(a["help"]) == 1:
        lines.append("The parent says the child has emotional or behavioral problems they need help with.")
    pos = total >= 15 or any(vals[k] >= cuts[k] for k in cuts)
    return {"total": total, "max": 34, "band": "positive" if pos else "negative",
            "summary": f"{total}/34 ({'positive' if pos else 'negative'})", "lines": lines, "flags": [],
            "values": vals}


# ---- the instruments -----------------------------------------------------------------------------------------
_PHQ_STEM = "Over the last 2 weeks, how often have you been bothered by any of the following problems?"
_PHQ9_ITEMS = ["Little interest or pleasure in doing things", "Feeling down, depressed, or hopeless",
               "Trouble falling or staying asleep, or sleeping too much", "Feeling tired or having little energy",
               "Poor appetite or overeating",
               "Feeling bad about yourself — or that you are a failure or have let yourself or your family down",
               "Trouble concentrating on things, such as reading the newspaper or watching television",
               "Moving or speaking so slowly that other people could have noticed? Or the opposite — being so "
               "fidgety or restless that you have been moving around a lot more than usual",
               "Thoughts that you would be better off dead or of hurting yourself in some way"]
_GAD7_ITEMS = ["Feeling nervous, anxious, or on edge", "Not being able to stop or control worrying",
               "Worrying too much about different things", "Trouble relaxing",
               "Being so restless that it is hard to sit still", "Becoming easily annoyed or irritable",
               "Feeling afraid as if something awful might happen"]
_ANY = lambda ids: (lambda a: any(int(_val(a, i)) > 0 for i in ids))
_PHQ_PFIZER = ("PHQ-9 and GAD-7: developed by Drs. Robert L. Spitzer, Janet B.W. Williams, Kurt Kroenke and colleagues, "
               "with an educational grant from Pfizer Inc. No permission required to reproduce, translate, display "
               "or distribute.")

ASSESS_INSTRUMENTS = {}


def _inst(**d):
    d.setdefault("respondent", "patient")
    d.setdefault("stem", "")
    ASSESS_INSTRUMENTS[d["id"]] = d
    return d


_inst(id="phq9", name="PHQ-9", title="Patient Health Questionnaire-9", groups=("adult",), cat="Depression",
      measures="Depression severity", ages="18+", minutes=3, measure_kind="PHQ-9",
      intro="This questionnaire asks how you have been feeling over the last 2 weeks.", stem=_PHQ_STEM,
      items=[_q(i, t, _FREQ4) for i, t in enumerate(_PHQ9_ITEMS, 1)] + [
          _q("diff", "If you checked off any problems, how difficult have these problems made it for you to do your "
                     "work, take care of things at home, or get along with other people?", _DIFFICULT,
             stem="", show=_ANY(range(1, 10)), scored=False)],
      score=_score_phq, credit=_PHQ_PFIZER)

